INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$6ee959d0-12ab-5eba-bd01-6a424145afec$ml$::uuid, $ml$cybersecurity$ml$, 1, 1, $ml${"id": "cybersecurity-d1-c1", "title": "A carmaker stops its lines", "lessonTitle": "Who is attacking, and why", "slot": 1, "type": "apply", "brief": {"headline": "In September 2025, a cyberattack forced Jaguar Land Rover to shut its systems. Production stopped for over a month, and one estimate put the cost to the UK economy at £1.9 billion.", "kicker": "Apply the motive: what did the attackers want from a carmaker?", "fullText": "Jaguar Land Rover shut down its systems in early September 2025 to contain a cyberattack. Production halted for over a month, and output fell by about 5,000 vehicles a week for five weeks. A group calling itself Scattered Lapsus$ Hunters claimed the attack.\n\nThe Cyber Monitoring Centre estimated the cost to the UK economy at £1.9 billion, about $2.5 billion, and said over 5,000 UK organisations were affected. A stopped factory puts heavy pressure on a company, which is exactly what a money motivated group wants.", "sources": [{"url": "https://securityaffairs.com/183733/security/cyberattack-on-jaguar-land-rover-inflicts-2-5b-loss-on-uk-economy.html", "label": "Security Affairs, JLR attack cost to the UK economy"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each attacker by its most likely type.", "buckets": ["Criminal gang", "Nation-state", "Hacktivist"], "items": [{"text": "A group that halts a factory and seeks a payout", "bucket": 0}, {"text": "A crew that steals data to extort its owner", "bucket": 0}, {"text": "Hackers quietly sitting inside water systems", "bucket": 1}, {"text": "Spies reading telecom call records for years", "bucket": 1}, {"text": "A group defacing websites over a political cause", "bucket": 2}, {"text": "Activists knocking a ministry site offline in protest", "bucket": 2}], "explanation": "Gangs want money, so they hit what hurts most. States want quiet access. Hacktivists want attention for a cause."}, "numbers": {"kind": "numberSense", "prompt": "The Cyber Monitoring Centre estimated the cost to the UK economy. About how much, in billions of pounds?", "min": 0, "max": 5, "value": 1.9, "unit": "B", "explanation": "About £1.9 billion, within a modelled range of £1.6 billion to £2.1 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a security role at a carmaker. They ask who is most likely to attack them.", "prompt": "Which answer shows you think in threat actors?", "options": ["Hacktivists, since carmakers are political targets", "Nobody, since factories are not online", "Criminal gangs, since a stopped line pressures us to pay"], "correctIndex": 2, "consequences": ["Possible, but money is the bigger driver for this target.", "JLR shows factories depend on IT that can be shut down.", "You name the attacker and the motive, as JLR showed."], "explanation": "A carmaker loses heavily for every week its lines stop. That pressure is what money motivated gangs exploit."}, "proReasoning": "Strong candidates name the likely attacker and why it would pick this target. Motive predicts the attack.", "commonMistake": "Listing every threat equally. Teams plan around the attackers most likely to come for them.", "mentalModel": "Name the attacker, its motive, and what it would hit."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a large manufacturer. The JLR attack makes you rethink its risks.", "prompt": "What does the JLR case show an investor?", "options": ["A cyberattack can stop revenue for weeks", "Cyber losses stay inside the IT budget", "Only customer data is ever at risk"], "correctIndex": 0, "consequences": ["JLR lost about 5,000 vehicles of output a week for five weeks.", "The loss here was lost production, far beyond IT costs.", "Here the damage came from stopped factories, not leaked data."], "explanation": "The cost of an attack can be lost output, not just a cleanup bill. That belongs in how you value a manufacturer."}, "proReasoning": "Investors ask how long a company could run if its systems went dark. Downtime is where cyber losses grow.", "commonMistake": "Treating cyber risk as a small IT line item. JLR shows it can hit the whole income statement.", "mentalModel": "Ask how much output an outage would stop, and for how long."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps factories restart safely after a cyberattack. You need a first customer.", "prompt": "Which buyer feels this pain most?", "options": ["A firm whose staff all work on paper", "A manufacturer whose lines depend on IT systems", "A small shop that only sells online gift cards"], "correctIndex": 1, "consequences": ["With no IT, it has little to restart after an attack.", "Every week offline costs it real output, as JLR found.", "Its pain is real, but it has no production line to restart."], "explanation": "Factories lose output for every day they stay shut. A faster safe restart is worth a lot to them."}, "proReasoning": "Founders pick the customer whose loss grows by the day. That is where speed is worth paying for.", "commonMistake": "Pitching recovery to companies with nothing urgent to recover.", "mentalModel": "Sell to whoever loses the most for each day offline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why criminals would bother hacking a carmaker instead of a bank.", "prompt": "What's the best explanation?", "options": ["Hackers want to steal the cars and sell them abroad", "Carmakers keep more cash than banks", "Stopping a factory creates pressure to pay quickly"], "correctIndex": 2, "consequences": ["The attack hit IT systems, not the vehicles.", "The target was the pain of downtime, not cash on hand.", "A halted line costs a fortune each day, which is the pressure gangs want."], "explanation": "Money motivated gangs look for victims who lose the most while systems are down. A factory is one."}, "proReasoning": "Ask what the attacker gains by stopping this victim. The answer usually explains the target.", "commonMistake": "Assuming hackers only go after banks. Any company that cannot afford to stop is a target.", "mentalModel": "Gangs hit whoever is hurt most by downtime."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:44a05e1f88f9$ml$]::text[]),
($ml$25e27c9f-222d-5885-9ab9-00b44335f325$ml$::uuid, $ml$cybersecurity$ml$, 1, 2, $ml${"id": "cybersecurity-d1-c2", "title": "Two attacks, two motives", "lessonTitle": "Who is attacking, and why", "slot": 2, "type": "connect", "brief": {"headline": "Ransomware gang BlackCat hit Change Healthcare, touching 192.7 million people and drawing a $22 million ransom. China-linked Volt Typhoon instead hid inside US infrastructure.", "kicker": "Connect two ideas: the motive tells you how the attacker behaves.", "fullText": "Day 1 split attackers by motive. In February 2024, the BlackCat ransomware group hit Change Healthcare, part of UnitedHealth Group. The breach touched 192.7 million people, and the company paid a $22 million ransom.\n\nVolt Typhoon, which US agencies link to China, works the other way. CISA warned it was quietly settling into critical infrastructure for access it could use later, not demanding money. One attacker wants to be paid fast; the other wants to stay unseen.", "sources": [{"url": "https://www.digitalhealthnews.com/uhg-confirms-final-count-in-change-healthcare-breach-192-7-mn-affected", "label": "Digital Health News, Change Healthcare final count"}, {"url": "https://cisa.gov/news-events/alerts/2024/02/07/cisa-and-partners-release-advisory-prc-sponsored-volt-typhoon-activity-and-supplemental-living-land", "label": "CISA, Volt Typhoon advisory"}]}, "evidence": {"kind": "faceOff", "prompt": "Which attacker is more likely to stay hidden for months and ask for nothing?", "left": {"name": "A ransomware gang", "note": "Locks or steals data, then demands payment"}, "right": {"name": "A nation-state group", "note": "Seeks quiet access it can use later"}, "correctIndex": 1, "explanation": "A gang needs the victim to notice so it can get paid. A state group gains most by staying unseen."}, "numbers": {"kind": "numberSense", "prompt": "About how many people did the Change Healthcare breach touch, in millions?", "min": 0, "max": 300, "value": 192.7, "unit": "M", "explanation": "192.7 million, the largest health data breach on record in the US."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how defending against ransomware differs from defending against spies.", "prompt": "Which answer shows you understand motive?", "options": ["Gangs want fast payment; spies want long hidden access", "Both want money, so the same plan works", "Spies only target companies, never government agencies"], "correctIndex": 0, "consequences": ["You link each motive to how the attack plays out.", "Volt Typhoon sought access, not a ransom.", "Volt Typhoon targeted critical infrastructure."], "explanation": "A gang acts loudly to get paid. A state group hides to keep access. Defenses differ because the goals differ."}, "proReasoning": "Good answers tie each attacker to its goal and its behavior. That shows you can plan defenses.", "commonMistake": "Treating every attacker as a ransomware gang.", "mentalModel": "Name the motive, then the behavior it predicts."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in a health services company and a power utility.", "prompt": "Which risk fits each company best?", "options": ["No cyber risk for a regulated utility", "Ransom demands for health; hidden access for power", "Hacktivist protests are the main risk for both firms"], "correctIndex": 1, "consequences": ["Volt Typhoon shows utilities are targets.", "Change Healthcare paid $22 million; Volt Typhoon targeted infrastructure.", "Neither case here was driven by protest."], "explanation": "Health data draws money motivated gangs. Infrastructure draws states seeking access."}, "proReasoning": "Investors map each holding to its likely attacker. The risk looks different for each.", "commonMistake": "Assuming regulated companies are too boring to target.", "mentalModel": "Match each company to the attacker that wants it."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup detects intruders who move quietly and steal nothing at first.", "prompt": "Which attacker does your tool fit best?", "options": ["Ransomware gangs that announce themselves loudly", "Hacktivists posting on social media", "State groups hiding in infrastructure for access"], "correctIndex": 2, "consequences": ["Gangs make themselves known to get paid.", "Hacktivists want to be seen, not hidden.", "Volt Typhoon is exactly this kind of quiet, patient intruder."], "explanation": "Quiet, patient intruders are the hard case. A tool that finds them fits the nation-state threat."}, "proReasoning": "Founders build for one attacker type and its habits. That keeps the product sharp.", "commonMistake": "Claiming one tool stops every kind of attacker.", "mentalModel": "Build for one attacker and how it behaves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks all hackers are after money.", "prompt": "What's the more accurate picture?", "options": ["Some want money; others want hidden access", "All hackers only want to cause chaos", "Hackers never target governments"], "correctIndex": 0, "consequences": ["BlackCat wanted payment; Volt Typhoon wanted access.", "Most attackers have a clear goal, not just chaos.", "Volt Typhoon targeted critical infrastructure."], "explanation": "Motives differ. Gangs want money, states want hidden access, and hacktivists want attention."}, "proReasoning": "Ask what the attacker gets out of it. The answer usually sorts them.", "commonMistake": "Picturing every hacker as the same kind of criminal.", "mentalModel": "Ask what the attacker gains."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1e7aba09f750$ml$]::text[]),
($ml$02e3f056-51fe-5eb8-8192-7c5674c8a66d$ml$::uuid, $ml$cybersecurity$ml$, 1, 3, $ml${"id": "cybersecurity-d1-c3", "title": "First move at a hospital", "lessonTitle": "Who is attacking, and why", "slot": 3, "type": "decide", "brief": {"headline": "You run security at a regional hospital. Ransomware gangs hit health care hard, and Change Healthcare's attacked systems lacked multifactor authentication.", "kicker": "Decide: which defense matches the attacker most likely to come?", "fullText": "You run security at a regional hospital. Your board asks where to start.\n\nDay 1 showed that ransomware gangs want money, and health care pays when systems stop. In the Change Healthcare attack, former CEO Andrew Witty testified that the outdated systems involved lacked multifactor authentication, and the company paid a $22 million ransom.", "sources": [{"url": "https://www.digitalhealthnews.com/uhg-confirms-final-count-in-change-healthcare-breach-192-7-mn-affected", "label": "Digital Health News, Change Healthcare final count"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which gap did Change Healthcare's attacked systems have?", "options": ["No firewall at all", "No antivirus on any laptop", "No multifactor authentication"], "correctIndex": 2, "explanation": "The former CEO testified the outdated systems lacked multifactor authentication."}, "numbers": {"kind": "numberSense", "prompt": "About how large was the ransom Change Healthcare paid, in millions of dollars?", "min": 0, "max": 50, "value": 22, "unit": "M", "explanation": "$22 million, as the former CEO testified."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview what a hospital should fix first against ransomware.", "prompt": "What do you recommend?", "options": ["Ban all email attachments forever", "Add multifactor logins to remote access", "Buy insurance and wait"], "correctIndex": 1, "consequences": ["Too blunt, and it ignores the login gap.", "It closes the gap seen at Change Healthcare.", "Insurance pays later; it does not stop the attack."], "explanation": "The attacker type here is a money motivated gang. Strong logins on remote access block a common way in."}, "proReasoning": "Strong candidates tie the first fix to the likely attacker and a known gap.", "commonMistake": "Starting with a long wish list instead of the most likely way in.", "mentalModel": "Fix the door the likely attacker uses most."}, "invest": {"call": {"kind": "theCall", "situation": "A health IT vendor you might invest in says its systems still allow logins without MFA.", "prompt": "How should that affect your view?", "options": ["It does not matter for health firms", "It makes the company safer", "It is a serious, known risk to weigh"], "correctIndex": 2, "consequences": ["Health care is a top ransomware target.", "Missing MFA raises risk; it does not lower it.", "Change Healthcare showed what that gap can cost."], "explanation": "A known gap in a high-target sector is a real risk to the business, not a footnote."}, "proReasoning": "Investors ask basic security questions. A missing control in a targeted sector is a red flag.", "commonMistake": "Assuming a vendor is safe because it is large or regulated.", "mentalModel": "Ask about basic controls before trusting the story."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells easy multifactor login for small clinics.", "prompt": "What pitch fits the threat best?", "options": ["Stop gangs that use weak logins to get in", "Protect against spies stealing state secrets", "Make websites load faster for patients"], "correctIndex": 0, "consequences": ["It speaks to the clinics' most likely attacker.", "Clinics rarely face state spies.", "Speed has nothing to do with the threat."], "explanation": "Clinics face money motivated gangs. A login fix that blocks them speaks to their real fear."}, "proReasoning": "Founders pitch against the attacker the buyer actually faces.", "commonMistake": "Selling against a threat the customer does not have.", "mentalModel": "Pitch against the buyer's likely attacker."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a hospital can best protect itself from ransomware.", "prompt": "Where should it start?", "options": ["Hope attackers pick someone else", "Make sure logins need a second check", "Unplug every computer from the internet"], "correctIndex": 1, "consequences": ["Hospitals are frequent ransomware targets.", "Missing MFA was a gap in the Change Healthcare attack.", "Hospitals need connected systems to work."], "explanation": "A second login check stops many break-ins by money motivated gangs."}, "proReasoning": "Start with the simple control attackers keep finding missing.", "commonMistake": "Thinking only big, expensive tools make a difference.", "mentalModel": "Start with strong logins."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:95241f75aac2$ml$]::text[]),
($ml$40e39396-31b7-5b40-8b16-da468331c59a$ml$::uuid, $ml$cybersecurity$ml$, 2, 1, $ml${"id": "cybersecurity-d2-c1", "title": "The ransom on the blockchain", "lessonTitle": "How the money in cybercrime moves", "slot": 1, "type": "apply", "brief": {"headline": "In mid-June 2024, an attack knocked out CDK Global, whose software runs nearly 15,000 car dealerships. About 387 bitcoin, then roughly $25 million, was sent to the hackers.", "kicker": "Apply the money trail: how did anyone see the ransom?", "fullText": "CDK Global makes software that nearly 15,000 car dealerships use to run their business. An attack in mid-June 2024 knocked it offline.\n\nCNN reported that about 387 bitcoin, then roughly $25 million, was sent to hackers affiliated with the BlackSuit ransomware. The payment was visible on the public blockchain. CDK began restoring service about a week later. CDK did not confirm paying.", "sources": [{"url": "https://abc17news.com/money/cnn-business-consumer/2024/07/11/how-did-the-auto-dealer-outage-end-cdk-almost-certainly-paid-a-25-million-ransom/", "label": "CNN via ABC 17, CDK almost certainly paid a $25 million ransom"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the money trail in order.", "steps": ["Attackers knock CDK's dealer software offline", "Thousands of dealers lose the software they rely on", "About 387 bitcoin goes to a wallet tied to BlackSuit", "The payment shows up on the public blockchain", "Service begins to come back a week later"], "explanation": "The attack created pressure, the payment followed, and the blockchain left a public record of it."}, "numbers": {"kind": "numberSense", "prompt": "About how many bitcoin were sent to the hackers?", "min": 0, "max": 1000, "value": 387, "unit": "", "explanation": "About 387 bitcoin, roughly $25 million at the time."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why one software vendor's outage stopped thousands of dealers.", "prompt": "What does it show?", "options": ["A shared vendor can be one point of failure", "Each car dealer had weak passwords on its own PCs", "Bitcoin caused the outage"], "correctIndex": 0, "consequences": ["Nearly 15,000 dealers relied on one supplier.", "The attack hit CDK, not each dealer.", "Bitcoin was the payment, not the cause."], "explanation": "When many businesses run on one vendor, one attack stops all of them at once."}, "proReasoning": "Strong candidates spot shared dependencies. They are where one attack does the most damage.", "commonMistake": "Blaming the victims downstream instead of the shared vendor.", "mentalModel": "Find the vendor everyone depends on."}, "invest": {"call": {"kind": "theCall", "situation": "You are judging a software company that serves thousands of small businesses.", "prompt": "What does CDK teach about its risk?", "options": ["Ransomware only hits large banks, not software firms", "An outage could stop all its customers at once", "Small customers mean small risk"], "correctIndex": 1, "consequences": ["CDK served car dealers, not banks.", "CDK's outage stopped dealers across the country.", "Thousands of small customers add up to a big outage."], "explanation": "A vendor that many firms depend on carries concentrated risk. One attack hits every customer."}, "proReasoning": "Investors weigh how many customers one outage would touch.", "commonMistake": "Assuming a vendor is safe because each customer is small.", "mentalModel": "Count who stops when the vendor stops."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup traces ransom payments on the blockchain for investigators.", "prompt": "Why can your product work at all?", "options": ["Hackers always give their names", "Banks report every bitcoin transfer", "Bitcoin payments leave a public record"], "correctIndex": 2, "consequences": ["Attackers hide their identities.", "Many crypto transfers never touch a bank.", "CNN tracked the CDK payment on the public blockchain."], "explanation": "Public blockchains record every payment. That trail is what makes tracing possible."}, "proReasoning": "Founders build on a structural fact, like a public ledger, not on hope.", "commonMistake": "Assuming crypto payments are invisible.", "mentalModel": "Build on the trail the payment leaves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how reporters knew CDK likely paid a ransom if CDK never said so.", "prompt": "What's the answer?", "options": ["The bitcoin payment was visible on the blockchain", "CDK announced it in an ad", "The hackers sent reporters a signed press release"], "correctIndex": 0, "consequences": ["About 387 bitcoin was traced to a BlackSuit-linked wallet.", "CDK did not confirm the payment.", "The evidence came from the blockchain, not the hackers."], "explanation": "Bitcoin moves on a public ledger. Analysts can follow payments even when no one admits them."}, "proReasoning": "Follow the money. In crypto, it leaves a public trail.", "commonMistake": "Believing crypto makes ransom payments untraceable.", "mentalModel": "Crypto payments leave a public trail."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:210d15b3f1a2$ml$]::text[]),
($ml$cb0a8d5b-a5e7-515c-a0bc-38447a2d9749$ml$::uuid, $ml$cybersecurity$ml$, 2, 2, $ml${"id": "cybersecurity-d2-c2", "title": "From one ransom to the median", "lessonTitle": "How the money in cybercrime moves", "slot": 2, "type": "connect", "brief": {"headline": "Change Healthcare paid a $22 million ransom in 2024. Yet in 2025 the median ransomware payment was $59,556, and only 28% of victims paid at all.", "kicker": "Connect day 1 and day 2: one huge ransom is not the typical case.", "fullText": "Day 1 told the story of Change Healthcare, which paid a $22 million ransom after the BlackCat attack.\n\nDay 2 put that in context. Chainalysis found the median ransomware payment rose 368% in 2025, to $59,556. Ransomware gangs collected at least $820 million in crypto that year, while the share of victims who paid fell to a record low of 28%. Headlines show the biggest ransoms; the typical victim pays far less, or nothing.", "sources": [{"url": "https://www.digitalhealthnews.com/uhg-confirms-final-count-in-change-healthcare-breach-192-7-mn-affected", "label": "Digital Health News, Change Healthcare final count"}, {"url": "https://www.bleepingcomputer.com/news/security/ransomware-payment-rate-drops-to-record-low-despite-attack-surge", "label": "BleepingComputer on Chainalysis 2025 ransomware data"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Most ransomware victims paid in 2025.", "The median payment in 2025 was $59,556.", "Change Healthcare paid a $22 million ransom."], "fakeIndex": 0, "explanation": "Only 28% of victims paid in 2025, a record low."}, "numbers": {"kind": "numberSense", "prompt": "About how much was the median ransomware payment in 2025, in thousands of dollars?", "min": 0, "max": 200, "value": 60, "unit": "K", "explanation": "$59,556, up 368% from the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how big a typical ransom is.", "prompt": "Which answer is best?", "options": ["Ransoms are always paid in cash", "Far smaller than headline cases, around $60,000", "Usually over $20 million, like Change Healthcare"], "correctIndex": 1, "consequences": ["Ransoms are paid in crypto.", "The 2025 median was $59,556.", "$22 million was one of the largest cases."], "explanation": "The median shows the typical case. Big headline ransoms are the exception."}, "proReasoning": "Using the median, not the headline, shows you understand the data.", "commonMistake": "Taking the biggest ransom you heard of as normal.", "mentalModel": "Quote the median, then the outliers."}, "invest": {"call": {"kind": "theCall", "situation": "A cyber insurer you might invest in prices policies off the biggest ransoms in the news.", "prompt": "What is wrong with that?", "options": ["Ransom payments are falling to zero", "Insurers never pay ransoms", "Most victims pay far less, or nothing"], "correctIndex": 2, "consequences": ["Payments still totaled at least $820 million.", "The case says nothing about insurer payouts.", "The median was $59,556 and 72% did not pay."], "explanation": "Pricing off outliers misreads the typical loss. The median and the payment rate tell the real story."}, "proReasoning": "Investors check whether a business models the typical case, not the headline.", "commonMistake": "Letting one extreme case set the whole price.", "mentalModel": "Price off the median, plan for the outlier."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps victims recover without paying a ransom.", "prompt": "Which trend supports your pitch?", "options": ["Only 28% of victims paid in 2025", "Ransoms are always $22 million", "Attacks fell to zero in 2025"], "correctIndex": 0, "consequences": ["Most victims already refuse; you help them recover.", "The median was $59,556, not $22 million.", "Attacks rose about 50% in 2025."], "explanation": "A record low payment rate means many victims want another way out. That is your market."}, "proReasoning": "Founders tie the pitch to a trend in the data, not a single story.", "commonMistake": "Pitching with the one dramatic case instead of the broad trend.", "mentalModel": "Back the pitch with the trend."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks every ransomware victim pays millions.", "prompt": "What's the more accurate picture?", "options": ["Ransoms are always refunded", "Most do not pay; the typical ransom is far smaller", "Every victim pays at least $1 million to the gang"], "correctIndex": 1, "consequences": ["Ransoms are not refunded.", "72% did not pay, and the median was $59,556.", "The median was far below $1 million."], "explanation": "The biggest cases make the news. The typical victim pays much less, or refuses."}, "proReasoning": "Look for the median, not just the biggest number.", "commonMistake": "Mistaking the headline case for the usual one.", "mentalModel": "Headlines show the extremes."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e9bd7b7fabfe$ml$]::text[]),
($ml$5e14a8e7-2508-5adc-a6a6-95ff853364f8$ml$::uuid, $ml$cybersecurity$ml$, 2, 3, $ml${"id": "cybersecurity-d2-c3", "title": "To pay or to rebuild", "lessonTitle": "How the money in cybercrime moves", "slot": 3, "type": "decide", "brief": {"headline": "You run a mid-size company hit by ransomware. In 2025, 72% of victims refused to pay, and gangs rent their tools to affiliates who split the ransom.", "kicker": "Decide: what does paying feed, and what else can you do?", "fullText": "You run a mid-size company and ransomware has locked your files. Your board asks whether to pay.\n\nDay 2 showed the business behind the demand. Developers rent ransomware to affiliates, who break in and split the ransom; LockBit had 187 registered affiliates. In 2025, only 28% of victims paid. Paying funds the next attack and does not guarantee your data comes back.", "sources": [{"url": "https://www.bleepingcomputer.com/news/security/ransomware-payment-rate-drops-to-record-low-despite-attack-surge", "label": "BleepingComputer on Chainalysis 2025 ransomware data"}, {"url": "https://www.computing.co.uk/news/4177130/operation-cronos-nca-reveals-details-lockbit-affiliates", "label": "Computing, Operation Cronos"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan leaves you less exposed next time?", "left": {"name": "Pay quickly and move on", "note": "Funds the gang and its affiliates"}, "right": {"name": "Restore from backups and report", "note": "Slower, but builds lasting defenses"}, "correctIndex": 1, "explanation": "Backups and reporting cut the gang out. Paying funds the same business model that targeted you."}, "numbers": {"kind": "numberSense", "prompt": "Organizations spent heavily on information security in 2025. About how much, in billions of dollars?", "min": 0, "max": 500, "value": 218, "unit": "B", "explanation": "$217.7 billion, according to Gartner."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how you'd advise a company deciding whether to pay a ransom.", "prompt": "What frames the decision best?", "options": ["Always pay; it is the fastest way to get files back", "Never report an attack to anyone", "Weigh backups, the law, and what paying funds"], "correctIndex": 2, "consequences": ["Paying funds affiliates and guarantees nothing.", "Reporting helps recovery and may be required.", "You show judgment, not a reflex."], "explanation": "The decision depends on backups, legal duties and the business model you would be funding."}, "proReasoning": "Strong candidates lay out the trade-offs instead of a one word answer.", "commonMistake": "Treating paying as the default.", "mentalModel": "Lay out the options before the answer."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold says it paid a ransom and calls the matter closed.", "prompt": "What should you still worry about?", "options": ["It may be targeted again, and data may not return", "Nothing; paying the ransom ends all the risk", "Its stock must double now"], "correctIndex": 0, "consequences": ["Paying funds affiliates and guarantees nothing.", "Paying does not end the risk.", "Nothing in the case supports that."], "explanation": "Paying can mark a company as willing to pay, and recovery is never certain."}, "proReasoning": "Investors ask what changed after an attack, not just how it ended.", "commonMistake": "Taking a closed ransom as a solved problem.", "mentalModel": "Ask what changed after the attack."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells fast, tested backups to mid-size firms.", "prompt": "What is your strongest argument?", "options": ["It lets firms skip all other security", "It gives victims a real choice not to pay", "It guarantees no attack ever happens"], "correctIndex": 1, "consequences": ["Backups are one layer, not the whole defense.", "72% of victims refused in 2025; backups make that safe.", "Backups do not prevent attacks."], "explanation": "Good backups turn refusing to pay into a workable plan. That is what buyers want."}, "proReasoning": "Founders sell the outcome the buyer cares about: options in a crisis.", "commonMistake": "Overpromising that one product stops all attacks.", "mentalModel": "Sell the choice you give the customer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many victims now refuse to pay ransoms.", "prompt": "What's a good answer?", "options": ["Paying ransoms became illegal everywhere", "Gangs stopped asking for money", "Paying funds the gang and guarantees nothing"], "correctIndex": 2, "consequences": ["Paying is not banned everywhere.", "Gangs still collected at least $820 million.", "Only 28% paid in 2025, a record low."], "explanation": "Ransomware is a business. Paying funds the next attack and may not bring data back."}, "proReasoning": "Ask who gets paid and what that money does next.", "commonMistake": "Thinking paying is the only way out.", "mentalModel": "Paying feeds the business."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7b5e70d89478$ml$]::text[]),
($ml$a7cf53fb-4e04-5170-b8ea-116bf89dec0c$ml$::uuid, $ml$cybersecurity$ml$, 3, 1, $ml${"id": "cybersecurity-d3-c1", "title": "Logins bought on the dark web", "lessonTitle": "Who holds the power in cyber", "slot": 1, "type": "apply", "brief": {"headline": "In 2024, Mandiant said as many as 165 Snowflake customers may have had data exposed. Attackers used stolen logins, many harvested by malware since 2020, on accounts without MFA.", "kicker": "Apply the power rule: who controlled access here?", "fullText": "Snowflake runs cloud data storage for more than 9,820 customers. In 2024, Mandiant found that as many as 165 of them may have had their data exposed.\n\nAttackers used customer logins bought on cybercrime forums or stolen by information-stealing malware, some exposed as far back as 2020. Mandiant said a lack of multifactor authentication and rare password changes made the attacks work. Whoever held valid logins held the power.", "sources": [{"url": "https://thehackernews.com/2024/06/snowflake-breach-exposes-165-customers.html", "label": "The Hacker News, Snowflake breach exposes 165 customers"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did the Snowflake customer attacks succeed?", "options": ["Insiders at Snowflake selling data", "Stolen logins on accounts without MFA", "A flaw that crashed Snowflake's servers"], "correctIndex": 1, "explanation": "Mandiant pointed to stolen credentials, a lack of MFA and rare password rotation."}, "numbers": {"kind": "numberSense", "prompt": "About how many Snowflake customers may have had data exposed?", "min": 0, "max": 500, "value": 165, "unit": "", "explanation": "As many as 165, out of more than 9,820 customers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview what the Snowflake attacks teach about cloud security.", "prompt": "Which answer is strongest?", "options": ["Only the vendor is ever responsible", "Customers must protect their own logins", "Cloud platforms make breaches impossible"], "correctIndex": 1, "consequences": ["Customer accounts lacked MFA.", "The attacks used customer logins without MFA.", "Stolen logins still opened the door."], "explanation": "A cloud platform can be sound while customer accounts are weak. Access control is a shared job."}, "proReasoning": "Strong candidates explain who controls which part of access.", "commonMistake": "Assuming the cloud vendor handles all security.", "mentalModel": "Ask who controls each login."}, "invest": {"call": {"kind": "theCall", "situation": "A cloud software company you might invest in leaves MFA optional for customers.", "prompt": "How should Snowflake shape your view?", "options": ["Optional MFA proves strong security", "MFA does not matter in the cloud", "Optional MFA leaves customers exposed"], "correctIndex": 2, "consequences": ["Optional controls often go unused.", "Mandiant named missing MFA as a cause.", "Snowflake attacks hit accounts lacking MFA."], "explanation": "When strong logins are optional, many accounts skip them. That risk can land on the vendor too."}, "proReasoning": "Investors ask whether security controls are on by default or left to customers.", "commonMistake": "Assuming customers will turn on protections themselves.", "mentalModel": "Check what is on by default."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup alerts companies when their logins appear in stolen data.", "prompt": "Why is the timing right?", "options": ["Old stolen logins were used years later", "Logins are never sold online", "Attackers only guess passwords one by one"], "correctIndex": 0, "consequences": ["Some exposed credentials dated back to 2020.", "They were bought on cybercrime forums.", "These attacks used stolen, not guessed, logins."], "explanation": "Stolen logins keep their value until they are changed. Warning companies early closes that window."}, "proReasoning": "Founders target the gap between theft and use.", "commonMistake": "Assuming a leaked password goes stale on its own.", "mentalModel": "Shrink the time a stolen login stays useful."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how hackers got into so many Snowflake accounts.", "prompt": "What's the simple answer?", "options": ["They hacked Snowflake's offices", "They logged in with stolen passwords", "They broke Snowflake's encryption"], "correctIndex": 1, "consequences": ["It was a login problem, not a break-in.", "Stolen credentials on accounts without MFA did it.", "Mandiant traced it to stolen logins, not broken code."], "explanation": "The attackers did not break anything. They used real logins that had been stolen."}, "proReasoning": "Ask how the attacker got access. Often they just logged in.", "commonMistake": "Picturing every hack as a high-tech break-in.", "mentalModel": "Many hacks are just stolen logins."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cdfac405ec68$ml$]::text[]),
($ml$2042d5ec-56c5-59ce-a505-88c596a3de52$ml$::uuid, $ml$cybersecurity$ml$, 3, 2, $ml${"id": "cybersecurity-d3-c2", "title": "Renting power, then losing it", "lessonTitle": "Who holds the power in cyber", "slot": 2, "type": "connect", "brief": {"headline": "LockBit rented its ransomware to 187 affiliates, a business built on access. In February 2024, a UK-led operation seized its servers and leak sites.", "kicker": "Connect day 2 and day 3: governments can take power back.", "fullText": "Day 2 showed how ransomware works as a service: developers rent tools to affiliates and share the ransom. LockBit had 187 registered affiliates.\n\nDay 3 asked who holds the power. Attackers need only one way in, and defenders must cover every door. Yet in February 2024, an international operation led by the UK took down LockBit's servers and leak sites. Governments can hit the business itself.", "sources": [{"url": "https://www.computing.co.uk/news/4177130/operation-cronos-nca-reveals-details-lockbit-affiliates", "label": "Computing, Operation Cronos"}, {"url": "https://www.helpnetsecurity.com/2025/04/23/verizon-2025-data-breach-investigations-report-dbir/", "label": "Help Net Security on Verizon DBIR 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Whose power is this?", "buckets": ["Attacker power", "Defender power"], "items": [{"text": "Needing only one way in", "bucket": 0}, {"text": "Renting tools to 187 affiliates", "bucket": 0}, {"text": "Seizing a gang's servers and leak sites", "bucket": 1}, {"text": "Testing updates before a full rollout", "bucket": 1}], "explanation": "Attackers gain from scale and a single opening. Defenders and police can test, block and seize."}, "numbers": {"kind": "numberSense", "prompt": "How many registered affiliates did LockBit have?", "min": 0, "max": 500, "value": 187, "unit": "", "explanation": "187, revealed during Operation Cronos."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview whether defenders always lose.", "prompt": "Which answer is most balanced?", "options": ["Defenders always win in the end", "Nothing anyone does can ever stop ransomware gangs", "Attackers have an edge, but police can disrupt them"], "correctIndex": 2, "consequences": ["Attackers need only one way in.", "LockBit's servers were seized.", "Operation Cronos took down LockBit's servers."], "explanation": "Attackers hold the edge in getting in. Governments can still strike the business behind them."}, "proReasoning": "Good answers weigh both sides of the power balance.", "commonMistake": "Giving a one sided answer either way.", "mentalModel": "Name the edge, then the counterweight."}, "invest": {"call": {"kind": "theCall", "situation": "You follow security stocks and read about the LockBit takedown.", "prompt": "What does it mean for cyber spending?", "options": ["One takedown does not end the need for defense", "Companies can now stop buying security tools", "Ransomware is now over"], "correctIndex": 0, "consequences": ["Gangs regroup, so defenses still matter.", "Other gangs remain active.", "Payments still topped $820 million in 2025."], "explanation": "Takedowns hurt gangs, but the threat continues. Defense budgets stay."}, "proReasoning": "Investors judge whether an event changes demand or just the headlines.", "commonMistake": "Reading one police win as the end of a market.", "mentalModel": "Ask whether the event changes demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps police map ransomware affiliates.", "prompt": "Why does that matter after Operation Cronos?", "options": ["Gangs have no affiliates", "Affiliates carry out the attacks for the gangs", "Affiliates only write the code, never attack"], "correctIndex": 1, "consequences": ["LockBit had 187 of them.", "They break in and share the ransom.", "Developers write it; affiliates break in."], "explanation": "Affiliates are the hands of the business. Knowing who they are helps disrupt it."}, "proReasoning": "Founders aim at the part of the system that does the damage.", "commonMistake": "Focusing only on the brand name of a gang.", "mentalModel": "Follow the people doing the attacks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if police ever beat ransomware gangs.", "prompt": "What's a fair answer?", "options": ["Never, because gangs are beyond any police reach", "Always, within a day", "Sometimes, like when LockBit's servers were seized"], "correctIndex": 2, "consequences": ["LockBit's servers were seized.", "It takes international work and time.", "A UK-led operation took them down in 2024."], "explanation": "Police can and do disrupt gangs, though it takes time and international work."}, "proReasoning": "Look for who can strike back, not just who attacks.", "commonMistake": "Believing gangs are beyond reach.", "mentalModel": "Police can strike back."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7404adf1273a$ml$]::text[]),
($ml$0892ca07-b86a-5ef3-8d3f-d4601da22b12$ml$::uuid, $ml$cybersecurity$ml$, 3, 3, $ml${"id": "cybersecurity-d3-c3", "title": "How to roll out an update", "lessonTitle": "Who holds the power in cyber", "slot": 3, "type": "decide", "brief": {"headline": "You run IT for a hospital group. A faulty CrowdStrike update once crashed 8.5 million Windows computers, and security tools run deep inside every machine.", "kicker": "Decide: how should deep access be handled?", "fullText": "You run IT for a hospital group. Your security vendor pushes updates straight to every machine.\n\nDay 3 showed the cost of that power. In July 2024, one faulty CrowdStrike update crashed 8.5 million Windows devices, less than 1% of all Windows machines. Security software runs deep inside systems, so a vendor's mistake can stop everyone at once.", "sources": [{"url": "https://blogs.microsoft.com/blog/2024/07/20/helping-our-customers-through-the-crowdstrike-outage/", "label": "Microsoft on the CrowdStrike outage"}]}, "evidence": {"kind": "faceOff", "prompt": "Which rollout reduces your risk most?", "left": {"name": "Update every machine at once", "note": "Fastest protection everywhere"}, "right": {"name": "Test on a small group first", "note": "Catches bad updates before they spread"}, "correctIndex": 1, "explanation": "A small test group catches a bad update before it reaches every machine."}, "numbers": {"kind": "numberSense", "prompt": "About how many Windows devices did the faulty update crash, in millions?", "min": 0, "max": 20, "value": 8.5, "unit": "M", "explanation": "8.5 million, by Microsoft's estimate."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to manage a security vendor's updates.", "prompt": "What do you recommend?", "options": ["Stage updates through a test group", "Block all updates forever", "Let the vendor decide everything"], "correctIndex": 0, "consequences": ["It limits the damage of a bad update.", "That leaves known flaws open.", "Deep access needs a check on your side."], "explanation": "Staging keeps protection current while limiting the blast of a bad update."}, "proReasoning": "Strong candidates balance speed and safety.", "commonMistake": "Treating vendor updates as risk free.", "mentalModel": "Stage updates; never go all at once."}, "invest": {"call": {"kind": "theCall", "situation": "You are weighing a security vendor whose software runs deep inside customer machines.", "prompt": "What is the double edge?", "options": ["Deep access never matters", "Hard to replace, but one mistake hits many", "Easy to replace, and its mistakes stay small"], "correctIndex": 1, "consequences": ["The outage shows it matters a lot.", "8.5 million devices crashed from one update.", "Deep access makes it sticky, not harmless."], "explanation": "Deep access makes a vendor sticky, and also makes its mistakes widespread."}, "proReasoning": "Investors weigh both the moat and the risk of deep access.", "commonMistake": "Seeing only the stickiness, not the risk.", "mentalModel": "Weigh the moat against the blast radius."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tests security updates on sample machines before customers get them.", "prompt": "Who is your best buyer?", "options": ["Households with a single home laptop", "Companies with no computers", "IT teams running thousands of machines"], "correctIndex": 2, "consequences": ["They have little to stage.", "They have nothing to update.", "A bad update could stop all of them at once."], "explanation": "Large fleets have the most to lose from a bad update and the most to gain from testing."}, "proReasoning": "Founders sell where the downside is biggest.", "commonMistake": "Pitching to buyers with little at stake.", "mentalModel": "Sell where one bad update hurts most."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one update could crash millions of computers.", "prompt": "What's the simple answer?", "options": ["Security software runs deep inside each machine", "Every Windows computer shares one hard drive", "Hackers changed the update"], "correctIndex": 0, "consequences": ["Its deep access spread one mistake everywhere.", "They are separate machines.", "It was a faulty update, not a hack."], "explanation": "Security tools need deep access to stop attackers. That same access spreads their mistakes."}, "proReasoning": "Ask how much access a program has. It sets how far a mistake can spread.", "commonMistake": "Assuming only hackers cause outages.", "mentalModel": "Deep access spreads mistakes too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b4279c47e24d$ml$]::text[]),
($ml$95cc7ca0-87ab-501e-b838-ea0651740038$ml$::uuid, $ml$cybersecurity$ml$, 4, 1, $ml${"id": "cybersecurity-d4-c1", "title": "A bleach maker loses a quarter", "lessonTitle": "The numbers that size cyber risk", "slot": 1, "type": "apply", "brief": {"headline": "Clorox found unauthorized activity on its systems in August 2023. In the next quarter, its net sales fell 20%, a $356 million decline it mostly blamed on the attack.", "kicker": "Apply the numbers: how do you size what an attack cost?", "fullText": "Clorox told regulators on August 14, 2023, that it had found unauthorized activity on some of its IT systems. It said the attack was contained by September 18.\n\nWhen it reported its next quarter, net sales had fallen 20%, a $356 million decline it mostly blamed on the cyberattack. The cost of an attack is often lost sales, not just the bill to fix systems.", "sources": [{"url": "https://www.industryweek.com/technology-and-iiot/article/21274431/updated-clorox-cyberattack-cost-356-million", "label": "IndustryWeek, Clorox cyberattack cost $356 million"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Clorox net sales fell 20% in the quarter after.", "The attack cost Clorox nothing in sales.", "Clorox first reported the activity in August 2023."], "fakeIndex": 1, "explanation": "Net sales fell $356 million, most of which Clorox blamed on the attack."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did Clorox net sales fall in the quarter after the attack?", "min": 0, "max": 50, "value": 20, "unit": "%", "explanation": "20%, a $356 million decline."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to explain a breach's cost to executives.", "prompt": "What should you include?", "options": ["Only the IT team's overtime", "Nothing, since attack costs can never be known", "Lost sales and downtime, not just repair bills"], "correctIndex": 2, "consequences": ["That misses most of the cost.", "Clorox measured a clear sales drop.", "Clorox lost $356 million in sales."], "explanation": "Executives care about revenue. Lost sales from downtime are often the biggest cost."}, "proReasoning": "Strong candidates translate attacks into dollars the business feels.", "commonMistake": "Measuring only the cleanup cost.", "mentalModel": "Put the cost in sales and days."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a consumer goods stock. Clorox makes you wonder about cyber risk.", "prompt": "Where would an attack show up first?", "options": ["Missed shipments and lower sales", "Only in the IT budget", "Nowhere that investors could ever see"], "correctIndex": 0, "consequences": ["Clorox net sales fell 20% in a quarter.", "The sales hit dwarfed IT costs.", "It showed up in reported sales."], "explanation": "For a goods maker, an attack that stops production shows up in sales."}, "proReasoning": "Investors look for where an attack would hit revenue.", "commonMistake": "Assuming cyber costs are hidden or small.", "mentalModel": "Look for the hit to sales."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup models the business cost of downtime for manufacturers.", "prompt": "Which fact makes your case?", "options": ["Downtime never costs a manufacturer real money", "Clorox lost $356 million in sales after an attack", "Attacks only affect email"], "correctIndex": 1, "consequences": ["Clorox shows the opposite.", "Clear proof that downtime has a big price.", "Clorox lost production, not just email."], "explanation": "A real company's lost sales give buyers a concrete number to plan around."}, "proReasoning": "Founders anchor value in a real, measured loss.", "commonMistake": "Pitching with vague fear instead of a number.", "mentalModel": "Anchor the pitch in a real loss."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a cyberattack could hurt a company that makes bleach.", "prompt": "What's the answer?", "options": ["Hackers stole the bleach", "It changed the bleach formula to make it weaker", "It stopped production, so fewer products shipped"], "correctIndex": 2, "consequences": ["The attack hit IT systems, not products.", "The products were not changed.", "Sales fell 20% in the next quarter."], "explanation": "Modern factories run on IT. When systems stop, so do shipments and sales."}, "proReasoning": "Ask what the systems control. That is what an attack can stop.", "commonMistake": "Thinking only tech companies have cyber risk.", "mentalModel": "Stopped systems mean stopped sales."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f58f10719067$ml$]::text[]),
($ml$248ed8ba-d5b4-58d7-8572-c7c2b48b2461$ml$::uuid, $ml$cybersecurity$ml$, 4, 2, $ml${"id": "cybersecurity-d4-c2", "title": "Suppliers and the breach bill", "lessonTitle": "The numbers that size cyber risk", "slot": 2, "type": "connect", "brief": {"headline": "Verizon found a third party involved in 30% of breaches. IBM put the average US breach at $10.22 million, and ransomware appeared in 44% of breaches Verizon studied.", "kicker": "Connect day 3 and day 4: supplier risk shows up in the breach bill.", "fullText": "Day 3 showed how power flows through suppliers. In Verizon's 2025 report, breaches involving a third party doubled to 30%.\n\nDay 4 put a price on breaches. IBM found the average US data breach cost $10.22 million in 2025, an all-time high, and Verizon found ransomware in 44% of the breaches it studied. A weak supplier can bring that bill to your door.", "sources": [{"url": "https://www.helpnetsecurity.com/2025/04/23/verizon-2025-data-breach-investigations-report-dbir/", "label": "Help Net Security on Verizon DBIR 2025"}, {"url": "https://cyberscoop.com/ibm-cost-data-breach-2025/", "label": "CyberScoop on IBM Cost of a Data Breach 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What share of breaches involved a third party in Verizon's 2025 report?", "options": ["90%", "30%", "3%"], "correctIndex": 1, "explanation": "Breaches involving a third party doubled to 30%."}, "numbers": {"kind": "numberSense", "prompt": "In what share of breaches did Verizon find ransomware?", "min": 0, "max": 100, "value": 44, "unit": "%", "explanation": "44% of the breaches it studied."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why supplier security matters to the business.", "prompt": "What is the strongest answer?", "options": ["They are in 30% of breaches, which average $10.22M", "Suppliers never cause breaches at the firms they serve", "Only big suppliers matter"], "correctIndex": 0, "consequences": ["You link supplier risk to a dollar cost.", "Verizon found third parties in 30% of breaches.", "Any supplier with access can be the way in."], "explanation": "Putting a supplier figure next to the breach cost turns a vague risk into a business case."}, "proReasoning": "Strong candidates connect two numbers into one argument.", "commonMistake": "Quoting one statistic with no link to cost.", "mentalModel": "Pair the risk with its price."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold relies on hundreds of software suppliers.", "prompt": "How should that affect your view?", "options": ["Supplier risk is the suppliers' problem", "Supplier breaches are a real, costly risk", "More suppliers always means less risk"], "correctIndex": 1, "consequences": ["The breach bill lands on the company.", "Third parties were in 30% of breaches.", "Each supplier with access adds a door."], "explanation": "Each supplier with access is another way in, and breaches are expensive."}, "proReasoning": "Investors ask how a company checks the suppliers it depends on.", "commonMistake": "Assuming supplier risk stays with the supplier.", "mentalModel": "Count the doors suppliers open."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup scores the security of a company's suppliers.", "prompt": "Which numbers make your pitch?", "options": ["Breaches cost only about $10 on average", "Suppliers are never involved in any breaches at all", "Third parties in 30% of breaches; $10.22M average cost"], "correctIndex": 2, "consequences": ["The average US breach cost $10.22 million.", "Verizon found 30% involved a third party.", "Together they size the problem you solve."], "explanation": "A frequent cause with a high cost is a strong case for a product."}, "proReasoning": "Founders size the problem with how often it happens and what it costs.", "commonMistake": "Citing frequency without cost, or cost without frequency.", "mentalModel": "Size it by how often and how much."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders how a company gets hacked through someone else.", "prompt": "What's a simple explanation?", "options": ["A supplier with access can be the way in", "Hackers only attack companies directly", "Suppliers have no access to anything"], "correctIndex": 0, "consequences": ["30% of breaches involved a third party.", "Many attacks go through suppliers.", "Suppliers often have system access."], "explanation": "Companies give suppliers access to their systems. Attackers can use that access."}, "proReasoning": "Ask who else has a key to the building.", "commonMistake": "Thinking a company's security ends at its own walls.", "mentalModel": "Suppliers can be the way in."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c5a85d307308$ml$]::text[]),
($ml$17758cf8-3168-5649-b378-3643e750153c$ml$::uuid, $ml$cybersecurity$ml$, 4, 3, $ml${"id": "cybersecurity-d4-c3", "title": "Where to spend the next dollar", "lessonTitle": "The numbers that size cyber risk", "slot": 3, "type": "decide", "brief": {"headline": "You run security at a consumer fintech app. Americans reported $20.9 billion in cybercrime losses in 2025, and cyber-enabled fraud made up about 85% of it.", "kicker": "Decide: where do the numbers say the money goes?", "fullText": "You run security at a consumer fintech app with a fixed budget for the year.\n\nDay 4 sized the risk in dollars. The FBI's Internet Crime Complaint Center logged $20.877 billion in reported losses in 2025. Cyber-enabled fraud made up $17.7 billion, about 85%, led by investment scams at $8.6 billion. Phishing drew the most complaints, at 191,561.", "sources": [{"url": "https://www.helpnetsecurity.com/2026/04/07/online-crime-financial-losses-fbi-report/", "label": "Help Net Security on FBI IC3 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Where did most reported US cybercrime losses come from in 2025?", "left": {"name": "Cyber-enabled fraud", "note": "Scams that trick people into paying"}, "right": {"name": "Everything else", "note": "All other reported cybercrime"}, "correctIndex": 0, "explanation": "Fraud made up $17.7 billion, about 85% of reported losses."}, "numbers": {"kind": "numberSense", "prompt": "About how much did Americans report losing to cybercrime in 2025, in billions of dollars?", "min": 0, "max": 50, "value": 20.9, "unit": "B", "explanation": "$20.877 billion, up 26% from the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a fintech security role, you're asked what threat matters most.", "prompt": "What do you say?", "options": ["Spies stealing state secrets", "Fraud and scams targeting customers", "Hacktivist website defacements"], "correctIndex": 1, "consequences": ["Not the main threat to a consumer app.", "Fraud was about 85% of reported losses.", "Rare and low cost for a fintech app."], "explanation": "The numbers point to fraud. For a consumer app, that is where losses pile up."}, "proReasoning": "Strong candidates let the data set priorities.", "commonMistake": "Naming the most dramatic threat instead of the costliest.", "mentalModel": "Let the losses set the priority."}, "invest": {"call": {"kind": "theCall", "situation": "You are choosing between two security startups to back.", "prompt": "Which market does the FBI data favor?", "options": ["Website defacement tools", "Fax machine security", "Fraud prevention"], "correctIndex": 2, "consequences": ["A tiny share of losses.", "Not where losses are.", "Fraud was $17.7 billion of $20.9 billion."], "explanation": "The biggest losses point to the biggest market. Fraud dominates."}, "proReasoning": "Investors follow where the losses are, since that is where buyers spend.", "commonMistake": "Backing a market because it sounds technical.", "mentalModel": "Follow the losses to the market."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to protect people from online scams.", "prompt": "Which scam type should you tackle first?", "options": ["Investment scams", "Chain letters by mail", "Fake paper coupons"], "correctIndex": 0, "consequences": ["They led losses at $8.6 billion.", "Not a major online loss.", "Not a major online loss."], "explanation": "Investment scams were the single largest loss category in the FBI report."}, "proReasoning": "Founders start where the pain is biggest.", "commonMistake": "Picking a niche with little real loss.", "mentalModel": "Start with the biggest loss."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks most cybercrime losses come from hackers breaking into systems.", "prompt": "What do the FBI numbers say?", "options": ["Most came from viruses on phones", "Most losses came from fraud and scams", "Most came from stolen hardware"], "correctIndex": 1, "consequences": ["Not what the report shows.", "Fraud was about 85% of reported losses.", "Not what the report shows."], "explanation": "Scams that trick people into paying cost far more than technical hacks."}, "proReasoning": "Look at where the money was lost, not just how dramatic the attack sounds.", "commonMistake": "Assuming the most technical attack is the most costly.", "mentalModel": "Scams cost the most."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0fe6b77ca014$ml$]::text[]),
($ml$9db81c74-9c2a-58b0-a9ac-ea733bd7b338$ml$::uuid, $ml$cybersecurity$ml$, 5, 1, $ml${"id": "cybersecurity-d5-c1", "title": "Thirty eight days to file", "lessonTitle": "The rule that forces disclosure", "slot": 1, "type": "apply", "brief": {"headline": "HPE learned on December 12, 2023, that Russian state hackers had been in its email. It filed a Form 8-K on January 19, 2024. The access dated back as early as May 2023.", "kicker": "Apply the rule: when does the four day clock start?", "fullText": "Hewlett Packard Enterprise learned on December 12, 2023, that the Russian state group Midnight Blizzard had accessed its cloud email. The attackers took data from a small number of mailboxes, and HPE's filing cited access to some SharePoint files as early as May 2023.\n\nHPE filed a Form 8-K on January 19, 2024, 38 days after learning of the intrusion. The SEC's four business days run from when a company decides an incident is material, not from when it first learns of it.", "sources": [{"url": "https://www.darkreading.com/threat-intelligence/midnight-blizzard-breached-hpe-email-before-microsoft-hack", "label": "Dark Reading, Midnight Blizzard breached HPE email"}, {"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the HPE timeline in order.", "steps": ["Attackers access some SharePoint files", "HPE learns of the intrusion on December 12, 2023", "HPE investigates what was taken", "HPE files a Form 8-K on January 19, 2024"], "explanation": "Access came first, then discovery, then investigation, then the filing."}, "numbers": {"kind": "numberSense", "prompt": "About how many days passed between HPE learning of the intrusion and its 8-K filing?", "min": 0, "max": 100, "value": 38, "unit": "days", "explanation": "38 days, from December 12, 2023 to January 19, 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked when a company must disclose a cyberattack under SEC rules.", "prompt": "What is the precise answer?", "options": ["Within four business days of deciding it is material", "Within four calendar days of the very first alert", "Only if customers complain"], "correctIndex": 0, "consequences": ["The clock starts at the materiality decision.", "Discovery alone does not start the clock.", "The rule is about investors, not complaints."], "explanation": "The rule ties the deadline to the materiality decision, which may come after investigation."}, "proReasoning": "Precise wording on the trigger shows you know the rule.", "commonMistake": "Saying four days from discovery.", "mentalModel": "The clock starts at the materiality call."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold files an 8-K about a cyber incident weeks after first spotting it.", "prompt": "Is that automatically a violation?", "options": ["Yes, all incidents must be filed the same day", "No, the clock runs from the materiality decision", "Yes, it had to file within four days of spotting it"], "correctIndex": 1, "consequences": ["No same day rule exists.", "Companies investigate first, then decide.", "Discovery alone does not start the clock."], "explanation": "A gap between discovery and filing can be normal. What matters is when materiality was decided."}, "proReasoning": "Investors read filings carefully before assuming wrongdoing.", "commonMistake": "Treating every delay as a cover up.", "mentalModel": "Check when materiality was decided."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies document how they decide whether an incident is material.", "prompt": "Why is that valuable?", "options": ["Regulators never ask how it was decided", "Every incident is material by default", "The deadline runs from that decision"], "correctIndex": 2, "consequences": ["The decision sets the deadline.", "Materiality must be judged.", "A clear record shows when the clock started."], "explanation": "Since the four day clock runs from the decision, a clear record of it protects the company."}, "proReasoning": "Founders build around the exact trigger in a rule.", "commonMistake": "Missing what actually starts the deadline.", "mentalModel": "Build around the trigger."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why HPE took weeks to report a hack if the rule says four days.", "prompt": "What's the explanation?", "options": ["The four days start once a hack is judged material", "HPE broke the rule", "The rule gives every company a full year to file"], "correctIndex": 0, "consequences": ["Companies investigate before deciding.", "The case does not show a violation.", "The rule is four business days."], "explanation": "The rule gives four business days after a company decides an attack matters to investors."}, "proReasoning": "Ask what starts a deadline, not just how long it is.", "commonMistake": "Assuming the clock starts at the first sign of trouble.", "mentalModel": "The clock starts at the decision."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d139ecef4ef2$ml$]::text[]),
($ml$20884ed3-d349-5397-972a-94403f83d21c$ml$::uuid, $ml$cybersecurity$ml$, 5, 2, $ml${"id": "cybersecurity-d5-c2", "title": "Slow to find, fast to report", "lessonTitle": "The rule that forces disclosure", "slot": 2, "type": "connect", "brief": {"headline": "Breaches took 241 days on average to identify and contain in 2025. Once a US company judges an attack material, it has four business days to file. GDPR gives 72 hours.", "kicker": "Connect day 4 and day 5: the disclosure clock runs after detection.", "fullText": "Day 4 measured risk in days. IBM found breaches took 241 days on average to identify and contain in 2025.\n\nDay 5 set the reporting clock. Under SEC rules, a US public company must file a Form 8-K within four business days of deciding an incident is material. In Europe, GDPR gives companies 72 hours to report a personal data breach to regulators. Detection is slow; reporting, once triggered, is fast.", "sources": [{"url": "https://cyberscoop.com/ibm-cost-data-breach-2025/", "label": "CyberScoop on IBM Cost of a Data Breach 2025"}, {"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://gdpr-text.com/read/article-33/", "label": "GDPR Article 33"}]}, "evidence": {"kind": "multipleChoice", "prompt": "When does the SEC's four business day clock start?", "options": ["When an incident is judged material", "When the attacker first gets in", "When the press reports it"], "correctIndex": 0, "explanation": "The deadline runs from the materiality decision."}, "numbers": {"kind": "numberSense", "prompt": "How many hours does GDPR give to report a personal data breach to regulators?", "min": 0, "max": 200, "value": 72, "unit": "hours", "explanation": "72 hours, under GDPR Article 33."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why fast detection matters if reporting rules exist.", "prompt": "What is the best answer?", "options": ["Rules require every breach be detected in four days", "Reporting deadlines only start once you know", "Fast detection is not needed"], "correctIndex": 1, "consequences": ["The rules set reporting, not detection.", "Slow detection delays everything after it.", "Breaches took 241 days on average."], "explanation": "Rules set how fast you report once you know. Detection decides when you know."}, "proReasoning": "Strong candidates separate detection time from reporting time.", "commonMistake": "Confusing the two clocks.", "mentalModel": "Detection starts the reporting clock."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold says it detects breaches in weeks, not months.", "prompt": "Why might that matter to investors?", "options": ["It removes any duty to report breaches to the SEC", "It has no business value", "It shortens how long attackers stay in"], "correctIndex": 2, "consequences": ["Disclosure rules still apply.", "Faster detection limits damage.", "The 2025 average was 241 days."], "explanation": "Shorter detection limits how much damage builds before the company acts."}, "proReasoning": "Investors value speed because damage grows with time.", "commonMistake": "Seeing detection speed as only a technical detail.", "mentalModel": "Damage grows with time undetected."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup cuts the time to detect a breach.", "prompt": "Which numbers frame your pitch?", "options": ["241 days to contain versus a 72 hour reporting rule", "Breaches are found in an hour", "There are no reporting deadlines in the US or EU"], "correctIndex": 0, "consequences": ["The gap shows why speed matters.", "The average was 241 days.", "GDPR and the SEC set deadlines."], "explanation": "A long detection time next to a short reporting window shows buyers the squeeze."}, "proReasoning": "Founders show the gap their product closes.", "commonMistake": "Ignoring the deadlines that create urgency.", "mentalModel": "Show the gap you close."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some breaches are reported months after they happen.", "prompt": "What's a good answer?", "options": ["Reporting is optional everywhere", "They often take months to find", "Companies always wait a year on purpose"], "correctIndex": 1, "consequences": ["GDPR and the SEC require it.", "Breaches took 241 days on average.", "Rules require quick reporting once known."], "explanation": "Attackers can go unnoticed for months. The reporting clock starts once a company knows."}, "proReasoning": "Ask when the company found out, not just when it was hit.", "commonMistake": "Assuming every delay is deliberate.", "mentalModel": "Finding a breach takes time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f414f8558778$ml$]::text[]),
($ml$149f7e92-1644-5c53-bb3b-7ecf644d9580$ml$::uuid, $ml$cybersecurity$ml$, 5, 3, $ml${"id": "cybersecurity-d5-c3", "title": "The board wants to stay quiet", "lessonTitle": "The rule that forces disclosure", "slot": 3, "type": "decide", "brief": {"headline": "You are CFO of a US public company. Attackers stole data, and the board suggests paying them quietly and skipping any filing.", "kicker": "Decide: what does the SEC rule require next?", "fullText": "You are CFO of a US public company. Attackers stole customer data, and a board member suggests paying them and keeping quiet.\n\nDay 5 set the rule. If the company decides the incident is material, meaning a reasonable investor would likely consider it important, it must file a Form 8-K under Item 1.05 within four business days. Paying a ransom does not remove that duty.", "sources": [{"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://corpgov.law.harvard.edu/2023/08/13/new-sec-cybersecurity-disclosures", "label": "Harvard Law forum on SEC cyber rules"}]}, "evidence": {"kind": "faceOff", "prompt": "Which path follows the SEC rule?", "left": {"name": "Pay quietly and skip filing", "note": "Keeps the attack out of the news"}, "right": {"name": "Assess materiality, then file", "note": "File within four business days if material"}, "correctIndex": 1, "explanation": "If the incident is material, the company must disclose it, whether or not a ransom is paid."}, "numbers": {"kind": "numberSense", "prompt": "How many business days does a company have to file after deciding an incident is material?", "min": 0, "max": 20, "value": 4, "unit": "days", "explanation": "Four business days, under the SEC rule."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a security leadership role, you're asked what you'd tell this board.", "prompt": "What do you say?", "options": ["Pay and keep it quiet", "Wait quietly for the attackers to go away on their own", "Assess materiality now and disclose if required"], "correctIndex": 2, "consequences": ["Paying does not remove the duty to disclose.", "Delay does not change the rule.", "It follows the rule and protects the company."], "explanation": "Leaders who know the rule steer the board toward a fast, honest materiality call."}, "proReasoning": "Strong candidates can brief a board on the rule in plain terms.", "commonMistake": "Treating disclosure as optional.", "mentalModel": "Brief the board on the rule."}, "invest": {"call": {"kind": "theCall", "situation": "You hold this company's stock and later learn of the attack from a filing.", "prompt": "What does the rule give you?", "options": ["Timely notice of material incidents", "A refund of the price you paid for your shares", "Nothing useful"], "correctIndex": 0, "consequences": ["That is the point of the four day rule.", "The rule gives information, not refunds.", "Item 1.05 filings signal real incidents."], "explanation": "The rule exists so investors learn of material attacks quickly."}, "proReasoning": "Investors track Item 1.05 filings as a signal.", "commonMistake": "Ignoring disclosure filings.", "mentalModel": "Watch for Item 1.05 filings."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies run a fast materiality review after an attack.", "prompt": "Which rule creates your demand?", "options": ["A one year reporting window after any attack", "Four business days to file once material", "No rule requires disclosure"], "correctIndex": 1, "consequences": ["The window is four business days.", "The short window needs a fast process.", "The SEC rule requires it."], "explanation": "A short deadline after a judgment call creates demand for a fast, documented process."}, "proReasoning": "Founders build where a rule creates a deadline.", "commonMistake": "Missing the deadline that drives urgency.", "mentalModel": "Build where the deadline bites."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether a company can pay hackers to keep an attack secret.", "prompt": "What's the answer for US public companies?", "options": ["Yes, paying keeps it private", "Yes, if the board agrees", "Not if the attack is material"], "correctIndex": 2, "consequences": ["Paying does not remove the duty.", "The board cannot waive the rule.", "A material attack must be disclosed."], "explanation": "If an attack matters to investors, the company must disclose it within four business days."}, "proReasoning": "Ask whether the attack would matter to investors. That decides disclosure.", "commonMistake": "Thinking money can buy silence.", "mentalModel": "Material attacks must be disclosed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f18366a3bea7$ml$]::text[]),
($ml$0cd0d1ce-4596-59c2-ad6f-fa0465ca1d32$ml$::uuid, $ml$cybersecurity$ml$, 6, 1, $ml${"id": "cybersecurity-d6-c1", "title": "A record fine for a carrier", "lessonTitle": "Inside the phone networks", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, South Korea fined SK Telecom a record ₩134.5 billion, about $97 million, over a breach. About 23 million subscribers were affected.", "kicker": "Apply the idea: what did the regulator say the carrier got wrong?", "fullText": "SK Telecom disclosed a breach in April 2025. South Korea's privacy regulator found that USIM data for almost 27 million records was taken, affecting about 23 million subscribers. In August it imposed a record fine of ₩134.5 billion, about $97 million.\n\nThe regulator found no access controls between SK Telecom's internet-facing and internal networks. It said 4,899 server credentials were stored in plain text and more than 26 million USIM keys were unencrypted. Phone carriers hold data on almost everyone, which makes basic controls matter even more.", "sources": [{"url": "https://www.theregister.com/2025/08/28/sk_telecom_regulator_fine/", "label": "The Register, SK Telecom record fine"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each finding: did it let attackers in, or make the damage worse?", "buckets": ["Opened the way in", "Made the damage worse"], "items": [{"text": "No access controls between outside and inside networks", "bucket": 0}, {"text": "Server credentials stored in plain text", "bucket": 0}, {"text": "More than 26 million USIM keys left unencrypted", "bucket": 1}, {"text": "Data on about 23 million subscribers in reach", "bucket": 1}], "explanation": "Open networks and readable passwords let attackers move; unencrypted keys and huge records raised the cost."}, "numbers": {"kind": "numberSense", "prompt": "About how much was SK Telecom fined, in millions of dollars?", "min": 0, "max": 150, "value": 97, "unit": "M", "explanation": "About $97 million, or ₩134.5 billion, a record for the regulator."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a telecom security role. They ask what the SK Telecom case teaches.", "prompt": "Which lesson do you lead with?", "options": ["Only the phones need protection, never the servers", "Split internal networks off from the internet side", "Carriers are too big to be breached"], "correctIndex": 1, "consequences": ["Attackers got in through servers and stored data.", "The regulator found no such controls at SK Telecom.", "SK Telecom was breached despite its size."], "explanation": "The regulator pointed at missing walls inside the network. Separating systems limits how far an intruder goes."}, "proReasoning": "Strong candidates name the specific control that failed, not just that a breach happened.", "commonMistake": "Talking about hackers instead of the controls that were missing.", "mentalModel": "Name the control that failed."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a phone carrier. The SK Telecom fine makes you rethink regulatory risk.", "prompt": "What does the case show investors?", "options": ["Privacy fines are always tiny and quickly ignored", "Breaches never reach the regulator at all", "Regulators can impose large fines for weak controls"], "correctIndex": 2, "consequences": ["This one was about $97 million.", "The regulator investigated and fined it.", "The fine was a record ₩134.5 billion."], "explanation": "A breach can bring a large fine on top of cleanup and lost trust. That belongs in the risk picture."}, "proReasoning": "Investors watch how strict a regulator is, since it sets the cost of a breach.", "commonMistake": "Assuming fines are a rounding error.", "mentalModel": "Price the fine into the breach cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup encrypts sensitive keys and credentials for telecom companies.", "prompt": "Which finding helps your pitch most?", "options": ["26 million USIM keys and 4,899 logins left exposed", "SK Telecom simply had too many customers to protect", "The breach happened in April"], "correctIndex": 0, "consequences": ["Exactly the gap your product closes.", "Customer count is not the problem you solve.", "The date says nothing about your product."], "explanation": "Unencrypted keys and plain-text passwords are the gap your product closes. The regulator named both."}, "proReasoning": "Founders point to the regulator's own findings. Buyers trust them more than a sales pitch.", "commonMistake": "Pitching with fear instead of a named, specific gap.", "mentalModel": "Pitch with the regulator's findings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a phone company breach matters so much.", "prompt": "What's the best answer?", "options": ["Only the company itself is affected", "Carriers hold data on almost all their users", "Phone companies keep no customer data at all"], "correctIndex": 1, "consequences": ["Millions of customers were affected.", "About 23 million subscribers were affected here.", "SK Telecom held USIM data for millions."], "explanation": "A carrier knows who its customers are and holds their SIM data. One breach reaches millions of people."}, "proReasoning": "Ask how many people a company holds data on. That sets how far a breach spreads.", "commonMistake": "Thinking a breach only hurts the company.", "mentalModel": "Count who the data belongs to."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a3c874ef73f6$ml$]::text[]),
($ml$7c0d2f2c-b723-50a0-b596-7bddb361239f$ml$::uuid, $ml$cybersecurity$ml$, 6, 2, $ml${"id": "cybersecurity-d6-c2", "title": "Two typhoons, one target type", "lessonTitle": "Inside the phone networks", "slot": 2, "type": "connect", "brief": {"headline": "Volt Typhoon hid inside US infrastructure. Salt Typhoon, also linked to China, breached nine US telecoms by December 2024 and took call records.", "kicker": "Connect day 1 and day 6: state attackers want access, not ransom.", "fullText": "Day 1 sorted attackers by motive. CISA warned that Volt Typhoon, linked to China, was quietly settling into US critical infrastructure rather than demanding money.\n\nDay 6 showed a similar pattern in phone networks. By December 2024, officials said Salt Typhoon had breached nine US telecom companies, taking customer call records and reaching the private communications of a limited number of people. The FBI said most targets were involved in government or politics. Neither group asked for a ransom.", "sources": [{"url": "https://cisa.gov/news-events/alerts/2024/02/07/cisa-and-partners-release-advisory-prc-sponsored-volt-typhoon-activity-and-supplemental-living-land", "label": "CISA, Volt Typhoon advisory"}, {"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Salt Typhoon breached nine US telecoms by December 2024.", "Salt Typhoon demanded a ransom from the carriers.", "Most Salt Typhoon targets were in government or politics."], "fakeIndex": 1, "explanation": "This was espionage. The goal was who calls whom, plus chosen targets' communications, not a payout."}, "numbers": {"kind": "numberSense", "prompt": "How many US telecom companies had officials said Salt Typhoon breached by December 2024?", "min": 0, "max": 20, "value": 9, "unit": "", "explanation": "Nine. At least eight were named first, then a ninth."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to spot a state-backed intrusion versus a ransomware attack.", "prompt": "Which clue points to a state group?", "options": ["A ransom note on every screen in the office", "A leak site naming the victim within days", "Quiet access to records with no ransom demand"], "correctIndex": 2, "consequences": ["That is the mark of a money motivated gang.", "Leak sites are a ransomware tactic.", "Salt Typhoon took call records and asked for nothing."], "explanation": "State groups want to stay hidden and keep reading. Gangs want to be noticed so they get paid."}, "proReasoning": "Good answers read the behavior to infer the motive.", "commonMistake": "Assuming every intrusion ends in a ransom note.", "mentalModel": "Read the behavior, infer the motive."}, "invest": {"call": {"kind": "theCall", "situation": "You follow telecom stocks after the Salt Typhoon news.", "prompt": "What risk does it highlight?", "options": ["Pressure for new required security rules", "An end to all government contracts", "Falling demand for phone service"], "correctIndex": 0, "consequences": ["Officials said voluntary practices were inadequate.", "Nothing in the case suggests that.", "People still need phone service."], "explanation": "Officials called voluntary security inadequate and pushed for required rules. That can raise costs."}, "proReasoning": "Investors watch for rules that follow a major breach. They often change spending.", "commonMistake": "Missing the regulatory follow-up to a breach.", "mentalModel": "Watch for rules after a breach."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup hunts for hidden intruders inside telecom networks.", "prompt": "Why is the timing right?", "options": ["Telecom attacks only want ransoms", "Officials said voluntary security was not enough", "Carriers now face no threats from state hackers"], "correctIndex": 1, "consequences": ["Salt Typhoon wanted access, not money.", "That pushes carriers to invest in hunting.", "Salt Typhoon shows the opposite."], "explanation": "Pressure from officials, plus a known patient intruder, gives carriers a reason to buy now."}, "proReasoning": "Founders time a launch to pressure the buyer already feels.", "commonMistake": "Pitching before the buyer feels any pressure.", "mentalModel": "Launch into pressure the buyer already feels."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why spies would hack a phone company.", "prompt": "What's the simple answer?", "options": ["To get free phone service for themselves", "To change customers' monthly bills", "To learn who calls whom and read some messages"], "correctIndex": 2, "consequences": ["Spies are after information, not service.", "Nothing points to billing changes.", "That is what officials said Salt Typhoon was after."], "explanation": "Call records show who talks to whom. That is valuable to a state spying on officials."}, "proReasoning": "Ask what the data reveals. That explains why spies want it.", "commonMistake": "Picturing every hack as a money grab.", "mentalModel": "Ask what the data reveals."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d2142eb9b02d$ml$]::text[]),
($ml$53fa3842-6543-5d09-a88d-2fc4ba27f919$ml$::uuid, $ml$cybersecurity$ml$, 6, 3, $ml${"id": "cybersecurity-d6-c3", "title": "A small carrier and new guidance", "lessonTitle": "Inside the phone networks", "slot": 3, "type": "decide", "brief": {"headline": "You run security at a regional phone carrier. Officials just published guidance on hunting the intruders behind Salt Typhoon, which reached nine US telecoms.", "kicker": "Decide: assume you are clean, or go and look?", "fullText": "You run security at a regional phone carrier. Officials have just published guidance on hunting the intruders behind Salt Typhoon.\n\nDay 6 showed the stakes. Salt Typhoon breached nine US telecom companies by December 2024, taking call records and some officials' communications. Officials said dozens of countries were affected and called voluntary telecom security inadequate.", "sources": [{"url": "https://www.pbs.org/newshour/world/chinese-hacking-campaign-hit-a-9th-u-s-telecom-firm-white-house-says", "label": "PBS NewsHour, Chinese hacking campaign hit a 9th US telecom"}]}, "evidence": {"kind": "faceOff", "prompt": "Which first step fits the guidance best?", "left": {"name": "Assume you are too small to matter", "note": "Saves time and budget this quarter"}, "right": {"name": "Assume you are a target and look", "note": "Hunt your network using the new guidance"}, "correctIndex": 1, "explanation": "Nine carriers were hit and dozens of countries affected. The guidance exists so carriers will look."}, "numbers": {"kind": "numberSense", "prompt": "About how many US telecoms had Salt Typhoon breached by December 2024?", "min": 0, "max": 30, "value": 9, "unit": "", "explanation": "Nine, by officials' count."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview what a small carrier should do after Salt Typhoon.", "prompt": "What do you recommend?", "options": ["Hunt for intruders using the official guidance", "Wait until a customer reports a problem first", "Replace every phone customers own"], "correctIndex": 0, "consequences": ["It follows the guidance written for this threat.", "Quiet intruders do not trigger complaints.", "The intruders were in networks, not handsets."], "explanation": "A patient intruder will not announce itself. Looking is the only way to know."}, "proReasoning": "Strong candidates assume compromise when the threat is known and quiet.", "commonMistake": "Waiting for symptoms from an attacker built to hide.", "mentalModel": "Assume compromise, then look."}, "invest": {"call": {"kind": "theCall", "situation": "A small carrier you might invest in says it is too small for state hackers.", "prompt": "How should that land?", "options": ["As a good reason to buy more of its shares", "As a warning sign about its security culture", "As proof that it is safe"], "correctIndex": 1, "consequences": ["The claim adds risk, not value.", "Nine carriers were breached in one campaign.", "Salt Typhoon hit carriers broadly."], "explanation": "Assuming you are not a target is how quiet intruders stay unnoticed."}, "proReasoning": "Investors listen for how leaders talk about risk. Dismissal is a red flag.", "commonMistake": "Taking \"we are too small\" as reassurance.", "mentalModel": "Treat dismissal of risk as a red flag."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells a threat hunting service sized for small carriers.", "prompt": "What is your opening line to a buyer?", "options": ["Small carriers are never targeted", "We guarantee no state hacker will ever try to get in", "Nine carriers were hit; let us check that you were not"], "correctIndex": 2, "consequences": ["Salt Typhoon makes that claim risky.", "No one can promise that.", "It ties your offer to a real campaign."], "explanation": "A real campaign and new guidance give a small buyer a concrete reason to check now."}, "proReasoning": "Founders open with the buyer's situation, not a promise they cannot keep.", "commonMistake": "Promising that attacks will never happen.", "mentalModel": "Open with the buyer's real situation."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend works at a small phone company and thinks spies only go after big carriers.", "prompt": "What would you tell them?", "options": ["Officials say many carriers and countries were hit", "Spies only care about the very biggest phone carriers", "Phone networks cannot be hacked"], "correctIndex": 0, "consequences": ["Dozens of countries were affected.", "Salt Typhoon spread widely.", "Nine US carriers were breached."], "explanation": "The campaign reached nine US carriers and dozens of countries. Size is no shield."}, "proReasoning": "Ask how wide a campaign went before assuming you were skipped.", "commonMistake": "Thinking small means safe.", "mentalModel": "Small is not safe."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5d6fa51eb730$ml$]::text[]),
($ml$7e41deb0-3538-576a-b950-cd9e691b36fc$ml$::uuid, $ml$cybersecurity$ml$, 7, 1, $ml${"id": "cybersecurity-d7-c1", "title": "A zero-day in a file tool", "lessonTitle": "Vulnerability, exploit, zero-day", "slot": 1, "type": "apply", "brief": {"headline": "In 2023, the Cl0p gang exploited a flaw in the MOVEit file transfer tool before a patch existed. By June 2024, 2,773 organizations and about 96 million people were counted as affected.", "kicker": "Apply the terms: was MOVEit a zero-day?", "fullText": "MOVEit Transfer is software companies use to send files securely. Cl0p began exploiting a flaw in it, CVE-2023-34362, around May 27, 2023. Progress Software released a patch on May 31. The flaw scored 9.8 out of 10.\n\nBecause attackers used the flaw before any fix existed, it was a zero-day. Emsisoft counted 2,773 affected organizations and 95,788,491 people as of June 28, 2024, though some may be double counted.", "sources": [{"url": "https://emsisoft.com/en/blog/44123/unpacking-the-moveit-breach-statistics-and-analysis/", "label": "Emsisoft, unpacking the MOVEit breach"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the MOVEit timeline in order.", "steps": ["A flaw sits unknown in MOVEit Transfer", "Cl0p starts exploiting it around May 27, 2023", "Progress releases a patch on May 31", "Victims are counted for more than a year"], "explanation": "Exploitation came before the patch, which is what made it a zero-day."}, "numbers": {"kind": "numberSense", "prompt": "About how many organizations were counted as affected by MOVEit, by June 2024?", "min": 0, "max": 5000, "value": 2773, "unit": "K", "explanation": "2,773 organizations, per Emsisoft, with possible double counting."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked whether MOVEit was a zero-day.", "prompt": "Which answer is precise?", "options": ["No, because it already had a public CVE number", "No, because it scored below 10", "Yes, it was exploited before a patch existed"], "correctIndex": 2, "consequences": ["Zero-days get CVE numbers too.", "Zero-day is about timing, not score.", "Cl0p used it from about May 27; the patch came May 31."], "explanation": "A zero-day is defined by timing: attacks before a fix. MOVEit fits."}, "proReasoning": "Strong candidates define terms by what they mean, not by labels.", "commonMistake": "Confusing a zero-day with a high score.", "mentalModel": "Zero-day means exploited before a fix."}, "invest": {"call": {"kind": "theCall", "situation": "A software vendor you follow sells a tool that many companies use to move files.", "prompt": "What does MOVEit say about its risk?", "options": ["One flaw can reach thousands of customers", "File tools never hold sensitive data", "A patch always arrives before attacks"], "correctIndex": 0, "consequences": ["2,773 organizations were counted as affected.", "MOVEit moved sensitive files.", "Here attacks came first."], "explanation": "A widely used tool spreads one flaw to every customer, and the vendor carries that risk."}, "proReasoning": "Investors ask how many customers one flaw could touch.", "commonMistake": "Assuming a vendor's flaws stay small.", "mentalModel": "Count who one flaw could reach."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup watches for unusual file transfers and alerts customers.", "prompt": "Why does MOVEit support your pitch?", "options": ["Only small firms used MOVEit", "Attacks began before any patch existed", "Patching alone stopped every attack"], "correctIndex": 1, "consequences": ["Thousands of organizations were hit.", "Patching could not help until May 31.", "Here the attacks came before the patch."], "explanation": "When a zero-day hits, patching is not an option yet. Watching for odd behavior is."}, "proReasoning": "Founders fill the gap that a standard fix cannot cover.", "commonMistake": "Claiming patching solves everything.", "mentalModel": "Fill the gap before the patch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what made MOVEit a zero-day.", "prompt": "What's the simple answer?", "options": ["It was found on the first day of the year", "It took zero days to patch", "Hackers used the flaw before a fix came out"], "correctIndex": 2, "consequences": ["The name is about warning time, not dates.", "It is about the vendor having no warning.", "Cl0p exploited it days before the patch."], "explanation": "Zero-day means the vendor had zero days of warning. Attackers got there first."}, "proReasoning": "Ask whether a fix existed when attacks began.", "commonMistake": "Taking the name literally.", "mentalModel": "Attackers got there first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:523b07b34473$ml$]::text[]),
($ml$1c1a8d3a-04a0-5025-bf35-fd9a42603d07$ml$::uuid, $ml$cybersecurity$ml$, 7, 2, $ml${"id": "cybersecurity-d7-c2", "title": "Many flaws, one door", "lessonTitle": "Vulnerability, exploit, zero-day", "slot": 2, "type": "connect", "brief": {"headline": "In 2024, 40,009 new vulnerabilities got a CVE number. Verizon found exploiting a vulnerability was the way in for 20% of breaches it studied.", "kicker": "Connect day 4 and day 7: flaws become breaches when they are used.", "fullText": "Day 4 sized risk with breach data. Verizon's 2025 report found that exploiting a vulnerability was the initial way in for 20% of breaches, close behind credential abuse at 22%.\n\nDay 7 counted the flaws. In 2024, 40,009 new vulnerabilities got a public CVE number, about 108 a day and almost 39% more than in 2023. A flaw is not an attack until someone uses it, and some clearly are used.", "sources": [{"url": "https://www.helpnetsecurity.com/2025/04/23/verizon-2025-data-breach-investigations-report-dbir/", "label": "Help Net Security on Verizon DBIR 2025"}, {"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}]}, "evidence": {"kind": "multipleChoice", "prompt": "About how many new CVEs were published per day in 2024?", "options": ["About 1,000", "About 108", "About 10"], "correctIndex": 1, "explanation": "40,009 in a year is about 108 a day."}, "numbers": {"kind": "numberSense", "prompt": "How many new vulnerabilities got a CVE number in 2024, in thousands?", "min": 0, "max": 60, "value": 40, "unit": "K", "explanation": "40,009, almost 39% more than in 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how much exploited flaws matter in breaches.", "prompt": "Which answer uses the data best?", "options": ["They opened 20% of breaches, near stolen logins", "They cause almost no breaches today", "They cause every single breach that happens now"], "correctIndex": 0, "consequences": ["Verizon: exploits 20%, credential abuse 22%.", "One in five is not almost none.", "Stolen logins were slightly more common."], "explanation": "Exploits and stolen logins are the two big ways in. Both need attention."}, "proReasoning": "Strong candidates compare causes using the same report.", "commonMistake": "Treating one cause as the whole story.", "mentalModel": "Compare causes in the same data."}, "invest": {"call": {"kind": "theCall", "situation": "You follow a vulnerability management company.", "prompt": "Which trend supports demand for it?", "options": ["Exploits no longer lead to breaches", "CVEs rose almost 39% in 2024 to 40,009", "Fewer flaws are found each year"], "correctIndex": 1, "consequences": ["They opened 20% of breaches.", "More flaws means more to sort and fix.", "The count went up, not down."], "explanation": "Rising flaw counts and real exploitation mean teams need help deciding what to fix."}, "proReasoning": "Investors look for a growing problem the product addresses.", "commonMistake": "Backing a market without checking the trend.", "mentalModel": "Check that the problem is growing."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup ranks vulnerabilities for busy security teams.", "prompt": "What is your core pitch?", "options": ["Teams can easily fix every flaw on day one", "Only perfect 10 scores ever matter", "At 108 new flaws a day, teams must rank them"], "correctIndex": 2, "consequences": ["The volume makes that impossible.", "Lower scores can still be exploited.", "No team can fix them all at once."], "explanation": "Volume forces choices. A tool that ranks by real risk saves scarce time."}, "proReasoning": "Founders turn a volume problem into a ranking product.", "commonMistake": "Promising teams can fix everything.", "mentalModel": "Sell the ranking, not the list."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether all 40,000 flaws a year lead to hacks.", "prompt": "What's the honest answer?", "options": ["No, but some are used, and they open many breaches", "Yes, every single flaw gets used by hackers at once", "No, flaws never lead to breaches"], "correctIndex": 0, "consequences": ["Exploits were the way in for 20% of breaches.", "Most flaws are never exploited.", "Verizon shows they do."], "explanation": "Most flaws are never used. The ones that are open a large share of breaches."}, "proReasoning": "Ask which flaws are actually being used.", "commonMistake": "Treating every flaw as equally dangerous.", "mentalModel": "Watch the flaws in use."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2671153ef3c1$ml$]::text[]),
($ml$b445fc71-2d0f-5542-bb95-b5cacdb9989e$ml$::uuid, $ml$cybersecurity$ml$, 7, 3, $ml${"id": "cybersecurity-d7-c3", "title": "Where to start on 108 a day", "lessonTitle": "Vulnerability, exploit, zero-day", "slot": 3, "type": "decide", "brief": {"headline": "You run vulnerability management for a mid-size company. About 108 new CVEs arrive each day, and 231 flaws scored a perfect 10 in 2024.", "kicker": "Decide: patch by score alone, or by what attackers use?", "fullText": "You run vulnerability management at a mid-size company. Your team can fix a few dozen issues a week.\n\nDay 7 showed the scale. In 2024, 40,009 new CVEs were published, about 108 a day, and 231 scored a perfect 10. The average score was 6.67. Mandiant tracked 138 flaws disclosed in 2023 that attackers exploited in the wild.", "sources": [{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}, {"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Which rule should rank your queue first?", "left": {"name": "Highest score first", "note": "Severity alone decides the order"}, "right": {"name": "Exploited and exposed first", "note": "Flaws in use on systems you run"}, "correctIndex": 1, "explanation": "A flaw already used by attackers on a system you run beats a high score on one you do not."}, "numbers": {"kind": "numberSense", "prompt": "How many flaws scored a perfect 10 in 2024?", "min": 0, "max": 500, "value": 231, "unit": "", "explanation": "231, out of 40,009 published."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how you'd rank thousands of open flaws.", "prompt": "What is your rule?", "options": ["Fix only the ones with a perfect 10", "Fix flaws attackers use on our systems first", "Fix them strictly in the order they were found"], "correctIndex": 1, "consequences": ["231 tens is still too many, and lower ones get used.", "It aims scarce time at real risk.", "Order found says nothing about risk."], "explanation": "Exploitation and exposure tell you what is likely to hurt you soon."}, "proReasoning": "Strong candidates rank by likelihood and impact, not one number.", "commonMistake": "Ranking by score alone.", "mentalModel": "Rank by use and exposure."}, "invest": {"call": {"kind": "theCall", "situation": "A security vendor claims its product scores flaws better than anyone.", "prompt": "What should you ask?", "options": ["How many colors does its dashboard use?", "Does it list every flaw ever found?", "Does it show which flaws attackers are using?"], "correctIndex": 2, "consequences": ["Design does not cut risk.", "A longer list does not help teams choose.", "Exploitation is the signal teams need."], "explanation": "With 108 flaws a day, the value is in knowing which ones are being used."}, "proReasoning": "Investors ask whether a product changes what customers do.", "commonMistake": "Being impressed by a longer list.", "mentalModel": "Ask what the product helps customers skip."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup feeds live exploitation data into patching tools.", "prompt": "Who is your best first customer?", "options": ["Small teams buried under thousands of flaws", "Teams running only a single test server", "Firms that never patch anything"], "correctIndex": 0, "consequences": ["They need help choosing what to fix.", "They have little to rank.", "They are not yet buying patch tools."], "explanation": "Teams with far more flaws than time feel this pain most."}, "proReasoning": "Founders sell to buyers who already struggle with the problem.", "commonMistake": "Selling to buyers who do not yet patch.", "mentalModel": "Sell where the queue is longest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders how anyone keeps up with 108 new flaws a day.", "prompt": "What's the answer?", "options": ["They ignore flaws completely", "They rank by risk and fix the urgent ones first", "They fix every single flaw on the same day it appears"], "correctIndex": 1, "consequences": ["Ignoring them leaves doors open.", "No team can fix them all at once.", "The volume makes that impossible."], "explanation": "Teams rank flaws by how likely and how damaging an attack would be."}, "proReasoning": "Ask how a team decides, not just how much it fixes.", "commonMistake": "Assuming the goal is fixing everything.", "mentalModel": "Rank, then fix."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6afc082210aa$ml$]::text[]),
($ml$2b3e955f-90b1-558c-b617-38b896508848$ml$::uuid, $ml$cybersecurity$ml$, 8, 1, $ml${"id": "cybersecurity-d8-c1", "title": "Microsoft pays $16.6 million", "lessonTitle": "Paying hackers to find flaws first", "slot": 1, "type": "apply", "brief": {"headline": "From July 2023 to June 2024, Microsoft paid about $16.6 million in bug bounties to 343 researchers in 55 countries. Its largest single award was $200,000.", "kicker": "Apply the idea: what does Microsoft buy with that money?", "fullText": "Microsoft runs 18 bug bounty programs. Between July 1, 2023 and June 30, 2024, it paid about $16.6 million to 343 security researchers from 55 countries. The largest single award was $200,000.\n\nThe researchers reported flaws privately so Microsoft could fix them before attackers found them. For a company of Microsoft's size, that is a small price for flaws found first.", "sources": [{"url": "https://www.securityweek.com/microsoft-bug-bounty-payouts-increase-to-16-6m-in-past-year/", "label": "SecurityWeek, Microsoft bug bounty payouts rise to $16.6M"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Microsoft paid about $16.6 million in a year.", "Researchers from 55 countries were paid.", "Microsoft paid one researcher the full amount."], "fakeIndex": 2, "explanation": "The money went to 343 researchers; the largest single award was $200,000."}, "numbers": {"kind": "numberSense", "prompt": "About how much did Microsoft pay per researcher on average, in thousands of dollars?", "min": 0, "max": 80, "value": 48, "unit": "K", "explanation": "$16.6 million across 343 researchers is about $48,000 each, though a few big awards pull that up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a software company. They ask why it should run a bug bounty.", "prompt": "What is your strongest case?", "options": ["It finds flaws before attackers do, for less", "It removes the need for internal testing", "It guarantees the product has no flaws"], "correctIndex": 0, "consequences": ["Microsoft paid $16.6 million to find flaws first.", "Bounties add to testing, they do not replace it.", "No program can promise that."], "explanation": "Bounties pay outsiders to report flaws privately. That is cheaper than an attack."}, "proReasoning": "Strong candidates frame a bounty as cost versus a breach.", "commonMistake": "Overselling a bounty as complete protection.", "mentalModel": "Compare the bounty to the breach."}, "invest": {"call": {"kind": "theCall", "situation": "A software company you hold expands its bug bounty budget.", "prompt": "How might you read that?", "options": ["As money with no possible return", "As paying to find flaws before attackers do", "As proof that its software is badly built"], "correctIndex": 1, "consequences": ["Flaws found first avoid costly attacks.", "That is how Microsoft frames its spending.", "Large, mature firms run big programs too."], "explanation": "A growing bounty can be a sign of a company that takes its flaws seriously."}, "proReasoning": "Investors judge security spending by what it prevents.", "commonMistake": "Reading bounty spending as a weakness.", "mentalModel": "Judge spending by what it prevents."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup runs bug bounty programs for mid-size software firms.", "prompt": "Which fact helps your pitch?", "options": ["Only tiny firms need outside testers", "Researchers will keep working for free forever", "Even Microsoft pays outsiders to find its flaws"], "correctIndex": 2, "consequences": ["Microsoft shows large firms use them too.", "Microsoft paid $16.6 million.", "A giant still finds value in outside researchers."], "explanation": "If the largest software firms pay for outside eyes, mid-size firms have a clear model to follow."}, "proReasoning": "Founders point to respected buyers already doing it.", "commonMistake": "Assuming researchers will help for nothing.", "mentalModel": "Point to who already pays."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Microsoft pays hackers.", "prompt": "What's the simple answer?", "options": ["So they report flaws privately instead of selling them", "Because Microsoft lost a lawsuit and had to pay them", "To make its software slower"], "correctIndex": 0, "consequences": ["Private reports let Microsoft fix flaws first.", "Nothing in the case points to a lawsuit.", "The goal is fixing flaws."], "explanation": "Paying for private reports turns would-be attackers into paid testers."}, "proReasoning": "Ask what the payment buys. Here, it buys early warning.", "commonMistake": "Assuming paying hackers rewards crime.", "mentalModel": "It buys early warning."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:508d82821859$ml$]::text[]),
($ml$40f7e060-9750-56ff-bec0-cd2f35caa1a4$ml$::uuid, $ml$cybersecurity$ml$, 8, 2, $ml${"id": "cybersecurity-d8-c2", "title": "A bounty versus a breach", "lessonTitle": "Paying hackers to find flaws first", "slot": 2, "type": "connect", "brief": {"headline": "Google paid $11.8 million to 660 researchers in 2024. The average US data breach cost $10.22 million in 2025, about the same as Google's whole year of bounties.", "kicker": "Connect day 4 and day 8: bounties look cheap next to breach costs.", "fullText": "Day 4 priced a breach. IBM found the average US data breach cost $10.22 million in 2025, an all-time high.\n\nDay 8 priced finding flaws first. Google paid $11.8 million to 660 researchers in 2024, with a top reward of $110,000, and has paid $65 million since 2010. A whole year of bounties for one of the world's largest software makers cost about as much as one average US breach.", "sources": [{"url": "https://cyberscoop.com/ibm-cost-data-breach-2025/", "label": "CyberScoop on IBM Cost of a Data Breach 2025"}, {"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which cost more?", "left": {"name": "Google's 2024 bounties", "note": "$11.8 million to 660 researchers"}, "right": {"name": "One average US breach", "note": "$10.22 million in 2025"}, "correctIndex": 0, "explanation": "Google's bounties cost a bit more, yet covered a year of flaws across huge products."}, "numbers": {"kind": "numberSense", "prompt": "How much did Google pay researchers in 2024, in millions of dollars?", "min": 0, "max": 30, "value": 11.8, "unit": "M", "explanation": "$11.8 million to 660 researchers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to justify a bug bounty budget.", "prompt": "Which comparison is strongest?", "options": ["Breaches usually cost less than a cup of coffee", "A year of bounties near the cost of one breach", "Bounties cost nothing at all"], "correctIndex": 1, "consequences": ["The average US breach cost $10.22 million.", "$11.8 million versus $10.22 million per breach.", "Google paid $11.8 million."], "explanation": "Putting a bounty budget next to a single breach makes the case concrete."}, "proReasoning": "Strong candidates compare the cost to the loss it prevents.", "commonMistake": "Arguing for a budget without a comparison.", "mentalModel": "Compare it to the loss avoided."}, "invest": {"call": {"kind": "theCall", "situation": "You are comparing two software firms. One runs a bug bounty and one does not.", "prompt": "What does the comparison suggest?", "options": ["The firm without one must be safer", "Bounties always lose investors money in the end", "The bounty firm may find flaws before attackers"], "correctIndex": 2, "consequences": ["No bounty means fewer outside eyes.", "One breach can cost more than a year of bounties.", "That is what the money buys."], "explanation": "A bounty is a modest, steady cost against a large, uncertain loss."}, "proReasoning": "Investors weigh small steady costs against rare big losses.", "commonMistake": "Treating any security spending as waste.", "mentalModel": "Weigh steady cost against rare loss."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies price a bug bounty.", "prompt": "Which number anchors your model?", "options": ["The $10.22 million cost of an average breach", "The color and style of the company logo", "The number of office floors"], "correctIndex": 0, "consequences": ["It sets what a bounty is worth.", "Irrelevant to risk.", "Irrelevant to risk."], "explanation": "The cost of a breach sets the ceiling on what finding flaws early is worth."}, "proReasoning": "Founders anchor pricing in the loss the customer avoids.", "commonMistake": "Pricing on cost to serve instead of value.", "mentalModel": "Anchor price in loss avoided."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks $11.8 million for bug bounties is a lot.", "prompt": "How would you put it in context?", "options": ["Bug bounties are all paid for by the government", "One average US breach costs about $10.22 million", "It is more than Google earns in a year"], "correctIndex": 1, "consequences": ["Google paid it.", "A year of bounties is about one breach.", "Google earns far more than that."], "explanation": "Next to the cost of one breach, a year of bounties looks small for a company Google's size."}, "proReasoning": "Compare a cost to what it prevents.", "commonMistake": "Judging a number without context.", "mentalModel": "Compare cost to what it prevents."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a560acd3abcb$ml$]::text[]),
($ml$b1e5fa54-40ab-514e-9cc6-1cc79d1288b1$ml$::uuid, $ml$cybersecurity$ml$, 8, 3, $ml${"id": "cybersecurity-d8-c3", "title": "Launch a bounty, or wait?", "lessonTitle": "Paying hackers to find flaws first", "slot": 3, "type": "decide", "brief": {"headline": "You run a growing SaaS company. Google paid an average of about $18,000 per researcher in 2024, and its top reward was $110,000.", "kicker": "Decide: is a bug bounty worth it now?", "fullText": "You run a growing software company with a small security team. Your board asks whether to launch a bug bounty.\n\nDay 8 gave the benchmarks. Google paid $11.8 million to 660 researchers in 2024, about $18,000 each on average, with a top reward of $110,000. Chrome alone paid $3.4 million to 137 researchers. Paying for a private report usually costs far less than a breach.", "sources": [{"url": "https://www.techradar.com/pro/security/google-bug-bounty-payments-hit-nearly-usd12-million-in-2024", "label": "TechRadar, Google bug bounty payments in 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does a researcher do in a bug bounty?", "options": ["Publishes the flaw before telling anyone", "Reports a flaw privately, then gets paid", "Sells the flaw to the highest bidder"], "correctIndex": 1, "explanation": "Researchers report privately, the company fixes the flaw, then pays."}, "numbers": {"kind": "numberSense", "prompt": "About how much did Chrome pay researchers in 2024, in millions of dollars?", "min": 0, "max": 10, "value": 3.4, "unit": "M", "explanation": "$3.4 million to 137 researchers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how to start a bug bounty at a small company.", "prompt": "What is a sensible first step?", "options": ["Offer $1 million for every single report received", "Skip fixing reports to save time", "Start with a scoped program and clear rewards"], "correctIndex": 2, "consequences": ["Google's top reward was $110,000.", "The point is fixing what is reported.", "It keeps costs and workload manageable."], "explanation": "A scoped start lets a small team handle reports and fix them quickly."}, "proReasoning": "Strong candidates match the program to the team's capacity.", "commonMistake": "Launching wide open with no plan to fix reports.", "mentalModel": "Start scoped, then grow."}, "invest": {"call": {"kind": "theCall", "situation": "A startup you might back launched a bug bounty before its first big customer.", "prompt": "How should you read it?", "options": ["As early attention to security", "As proof it has no flaws", "As wasted money for sure"], "correctIndex": 0, "consequences": ["Finding flaws early is cheaper.", "Bounties find flaws; they do not prove none exist.", "A private report costs less than a breach."], "explanation": "Early bounties can show a team that wants to find its flaws first."}, "proReasoning": "Investors look for habits that lower risk as a company grows.", "commonMistake": "Reading security effort as a sign of weakness.", "mentalModel": "Look for habits that lower risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the SaaS company. Your small team can fix about ten reports a month.", "prompt": "How should you launch?", "options": ["Skip it, since flaws never cost a company money", "Open a small, scoped program you can keep up with", "Open everything to everyone at once"], "correctIndex": 1, "consequences": ["A breach costs millions.", "It matches reports to what you can fix.", "You could drown in reports you cannot fix."], "explanation": "A program is only useful if you fix what comes in. Scope it to your team."}, "proReasoning": "Founders size commitments to their capacity.", "commonMistake": "Promising more than the team can deliver.", "mentalModel": "Size it to what you can fix."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether only giant companies run bug bounties.", "prompt": "What's a good answer?", "options": ["Yes, only Google is allowed to", "Yes, they cost at least $1 billion a year", "No, smaller firms can run scoped programs"], "correctIndex": 2, "consequences": ["Many companies run them.", "Google paid $11.8 million in 2024.", "Scope and rewards can match the company's size."], "explanation": "Any company can pay for private reports. The size of rewards can match the company."}, "proReasoning": "Ask what the program covers and pays, not just who runs it.", "commonMistake": "Assuming bounties are only for giants.", "mentalModel": "Bounties can scale down."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6851e35ce795$ml$]::text[]),
($ml$17693cb6-c7e3-522e-b37a-792b97ff9b01$ml$::uuid, $ml$cybersecurity$ml$, 9, 1, $ml${"id": "cybersecurity-d9-c1", "title": "A patched flaw still in use", "lessonTitle": "The list that sets the patching clock", "slot": 1, "type": "apply", "brief": {"headline": "Citrix patched the Citrix Bleed flaw in early October 2023. By the end of the month it was under mass exploitation, and LockBit used it against Boeing's parts business.", "kicker": "Apply the idea: why does a list of exploited flaws matter after a patch exists?", "fullText": "Citrix Bleed, CVE-2023-4966, affected Citrix NetScaler devices. Attackers had used it as a zero-day since August 2023, and Citrix released a patch in early October. By the end of October, exploitation was widespread.\n\nThe flaw let attackers take over logged-in sessions, getting around passwords and multifactor checks. LockBit affiliates used it against Boeing's parts and distribution business, and ICBC is also listed among victims. A patch only helps once it is installed.", "sources": [{"url": "https://www.helpnetsecurity.com/2023/11/22/lockbit-citrix-bleed/", "label": "Help Net Security, LockBit exploiting Citrix Bleed"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Citrix Bleed story in order.", "steps": ["Attackers use the flaw as a zero-day from August 2023", "Citrix releases a patch in early October", "Exploitation spreads widely by the end of October", "LockBit affiliates hit unpatched victims"], "explanation": "The patch came out, but unpatched devices kept being hit."}, "numbers": {"kind": "numberSense", "prompt": "In what month of 2023 did attackers start using Citrix Bleed as a zero-day?", "min": 1, "max": 12, "value": 8, "unit": "", "explanation": "August 2023, about two months before the patch."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what Citrix Bleed teaches about patching.", "prompt": "Which answer is strongest?", "options": ["Only zero-days are ever dangerous", "Exploited flaws need patching fast, even after release", "Once a patch exists, the risk is gone for everyone"], "correctIndex": 1, "consequences": ["It stayed dangerous after the patch.", "Unpatched devices kept getting hit.", "Victims were hit after the patch."], "explanation": "A flaw under active use is urgent until every device is patched."}, "proReasoning": "Strong candidates separate releasing a patch from installing it.", "commonMistake": "Assuming a released patch means protected.", "mentalModel": "A patch helps only once installed."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold uses network devices from a vendor with an exploited flaw.", "prompt": "What question matters most?", "options": ["Did the vendor recently change its logo?", "Is the device the newest model?", "Has the company installed the patch yet?"], "correctIndex": 2, "consequences": ["Branding does not matter.", "Patch status matters more than model.", "Unpatched devices were the ones hit."], "explanation": "Exposure depends on whether the fix is in place, not on the vendor's announcement."}, "proReasoning": "Investors ask about actions taken, not announcements made.", "commonMistake": "Assuming the vendor's patch protects every customer.", "mentalModel": "Ask if the fix is installed."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup checks whether customers' devices have urgent patches installed.", "prompt": "Why does Citrix Bleed help your pitch?", "options": ["Victims were hit after a patch was out", "Patches install themselves everywhere", "Only Boeing used Citrix devices"], "correctIndex": 0, "consequences": ["The gap was installing, not releasing.", "Many devices stayed unpatched.", "Many organizations used them."], "explanation": "Citrix Bleed shows the danger lives in the gap between release and install."}, "proReasoning": "Founders target the gap the standard process leaves open.", "commonMistake": "Assuming customers patch on their own.", "mentalModel": "Close the gap after release."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how hackers hit companies with a flaw that was already fixed.", "prompt": "What's the answer?", "options": ["The hackers wrote the fix", "The companies had not installed the fix", "The fix made the flaw even worse than before"], "correctIndex": 1, "consequences": ["Citrix released it.", "Unpatched devices were the targets.", "The patch closed the flaw."], "explanation": "A fix only protects devices it is installed on. Attackers look for the ones left behind."}, "proReasoning": "Ask whether the fix was installed, not just released.", "commonMistake": "Thinking a released fix protects everyone.", "mentalModel": "Unpatched devices get hit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:952b5c7cb397$ml$]::text[]),
($ml$4ef18203-22ae-59f4-8f84-4caa490d7dff$ml$::uuid, $ml$cybersecurity$ml$, 9, 2, $ml${"id": "cybersecurity-d9-c2", "title": "From 40,000 flaws to a short list", "lessonTitle": "The list that sets the patching clock", "slot": 2, "type": "connect", "brief": {"headline": "In 2024, 40,009 new CVEs were published. CISA's Known Exploited Vulnerabilities catalog lists only flaws with reliable evidence of exploitation, and agencies get two weeks for most.", "kicker": "Connect day 7 and day 9: the list turns volume into priority.", "fullText": "Day 7 counted 40,009 new CVEs in 2024, about 108 a day. No team can fix them all at once.\n\nDay 9 showed how one agency cuts that down. CISA's Known Exploited Vulnerabilities catalog lists a flaw only with a CVE ID, clear fix guidance and reliable evidence of exploitation in the wild. Under BOD 22-01, US civilian agencies must fix most listed flaws within two weeks.", "sources": [{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}, {"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each flaw belong on the catalog?", "buckets": ["Goes on the list", "Stays off the list"], "items": [{"text": "A CVE with clear fix guidance and attacks seen in the wild", "bucket": 0}, {"text": "A flaw attackers are using with a known remedy and CVE ID", "bucket": 0}, {"text": "A high score flaw with no evidence of exploitation", "bucket": 1}, {"text": "A suspected flaw with no CVE ID yet", "bucket": 1}], "explanation": "The list needs a CVE ID, clear guidance and reliable evidence of exploitation."}, "numbers": {"kind": "numberSense", "prompt": "How many weeks do US civilian agencies get to fix most listed flaws?", "min": 0, "max": 10, "value": 2, "unit": "weeks", "explanation": "Two weeks for most, six months for CVEs from before 2021."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview why CISA's catalog helps defenders.", "prompt": "What is the best answer?", "options": ["It lists every CVE ever published, in full", "It replaces the need to patch", "It cuts 40,000 flaws to those actually in use"], "correctIndex": 2, "consequences": ["It lists only exploited flaws.", "It tells you what to patch first.", "Exploitation is the filter."], "explanation": "Exploitation in the wild is the signal. The list turns a flood into a short queue."}, "proReasoning": "Strong candidates explain why a filter beats a full list.", "commonMistake": "Treating more data as more useful.", "mentalModel": "A good filter beats a long list."}, "invest": {"call": {"kind": "theCall", "situation": "A security vendor highlights that its tool flags flaws on CISA's catalog.", "prompt": "Why might customers value that?", "options": ["It points to flaws attackers really use", "It means the tool lists fewer flaws", "It means CISA endorses the vendor"], "correctIndex": 0, "consequences": ["That is the catalog's signal.", "Fewer is not the goal; relevance is.", "Using the list is not an endorsement."], "explanation": "Customers want to know what to fix first. The catalog is a trusted signal for that."}, "proReasoning": "Investors look for features tied to trusted, free signals buyers already respect.", "commonMistake": "Mistaking use of a public list for an endorsement.", "mentalModel": "Tie features to trusted signals."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup alerts companies when a flaw they run lands on CISA's catalog.", "prompt": "Who is your clearest buyer?", "options": ["Companies with no computers", "Teams that must fix listed flaws within two weeks", "People who never use any software at all at work"], "correctIndex": 1, "consequences": ["They have nothing to patch.", "The deadline makes timely alerts valuable.", "They have nothing to patch."], "explanation": "A hard deadline makes knowing quickly worth paying for."}, "proReasoning": "Founders sell where a deadline creates urgency.", "commonMistake": "Selling to buyers without a deadline.", "mentalModel": "Sell where the deadline bites."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how agencies decide which of 40,000 flaws to fix first.", "prompt": "What's a simple answer?", "options": ["They always start with the oldest flaw on record", "They pick flaws at random", "They start with ones attackers are already using"], "correctIndex": 2, "consequences": ["Age does not set urgency.", "There is a clear list.", "That is what the catalog lists."], "explanation": "CISA lists flaws with evidence of exploitation, and agencies fix those first."}, "proReasoning": "Ask which flaws are in use.", "commonMistake": "Assuming every flaw is equally urgent.", "mentalModel": "Fix what is in use first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e2f045544fa6$ml$]::text[]),
($ml$0509ff42-8005-579f-b1f5-1ab2bf7b23d0$ml$::uuid, $ml$cybersecurity$ml$, 9, 3, $ml${"id": "cybersecurity-d9-c3", "title": "A flaw lands on the catalog", "lessonTitle": "The list that sets the patching clock", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a US civilian agency. A flaw in your VPN just landed on CISA's catalog. Under BOD 22-01, most listed flaws must be fixed within two weeks.", "kicker": "Decide: what does the directive require next?", "fullText": "You run IT at a US civilian agency. A flaw in your remote access gear just went on CISA's Known Exploited Vulnerabilities catalog.\n\nDay 9 set the clock. Under BOD 22-01, agencies get two weeks for most listed flaws and six months for those with CVE IDs from before 2021. Agencies must report their progress, and CISA can shorten deadlines in cases of grave risk.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan meets the directive?", "left": {"name": "Patch within two weeks and report it", "note": "Follows BOD 22-01 for a new listing"}, "right": {"name": "Add it to the next quarterly cycle", "note": "Keeps the usual patch schedule"}, "correctIndex": 0, "explanation": "Most listed flaws must be fixed within two weeks, and progress must be reported."}, "numbers": {"kind": "numberSense", "prompt": "How many months do agencies get for listed flaws with CVE IDs from before 2021?", "min": 0, "max": 18, "value": 6, "unit": "months", "explanation": "Six months, versus two weeks for most other listed flaws."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a federal IT role, you're asked what happens when a flaw is listed.", "prompt": "What do you say?", "options": ["Fix it within the deadline and report status", "Wait for the vendor to call you about it first", "Ignore it if it scores below 9"], "correctIndex": 0, "consequences": ["That is what BOD 22-01 requires.", "The clock starts at listing.", "The list is about exploitation, not score."], "explanation": "Listing starts a clock. Agencies fix within the deadline and report progress."}, "proReasoning": "Strong candidates know both the deadline and the reporting duty.", "commonMistake": "Treating the catalog as advice, not a requirement.", "mentalModel": "Listing starts the clock."}, "invest": {"call": {"kind": "theCall", "situation": "A company selling to federal agencies says its patching is quarterly.", "prompt": "Why might agencies push back?", "options": ["Federal rules ban patching", "They must fix most listed flaws in two weeks", "Agencies generally prefer slower patching cycles"], "correctIndex": 1, "consequences": ["The directive requires it.", "A quarterly cycle can miss the deadline.", "The directive pushes speed."], "explanation": "Vendors whose products are slow to patch can make it hard for agencies to meet deadlines."}, "proReasoning": "Investors check whether a product fits buyers' rules.", "commonMistake": "Ignoring the buyer's compliance clock.", "mentalModel": "Fit the buyer's rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup automates patch reporting for agencies.", "prompt": "Which feature matters most?", "options": ["A dark mode and new icons for the dashboard", "A list of every CVE ever", "Tracking each listed flaw against its deadline"], "correctIndex": 2, "consequences": ["Nice, but not the need.", "Too broad to help.", "That is what agencies must report."], "explanation": "Agencies must show progress against deadlines. Tracking that directly is the job."}, "proReasoning": "Founders build the feature the rule requires.", "commonMistake": "Building features the rule does not ask for.", "mentalModel": "Build what the rule requires."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether US agencies can take their time fixing known flaws.", "prompt": "What's the answer?", "options": ["No, most listed flaws must be fixed in two weeks", "Yes, there is no deadline at all for any agency", "Yes, they get ten years"], "correctIndex": 0, "consequences": ["BOD 22-01 sets that deadline.", "The directive sets deadlines.", "Most get two weeks."], "explanation": "For flaws on CISA's catalog, agencies face firm deadlines and must report progress."}, "proReasoning": "Ask whether a rule sets a deadline.", "commonMistake": "Assuming government moves slowly by default.", "mentalModel": "Listed flaws have a deadline."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:39635af88b63$ml$]::text[]),
($ml$bfda8245-a03d-5294-bdde-4cf563b90e2b$ml$::uuid, $ml$cybersecurity$ml$, 10, 1, $ml${"id": "cybersecurity-d10-c1", "title": "Exploits lead, dwell time shrinks", "lessonTitle": "Five days to exploit", "slot": 1, "type": "apply", "brief": {"headline": "Mandiant's M-Trends 2025 found exploits were the most common way in, at 33% of intrusions. Median dwell time was 11 days.", "kicker": "Apply the idea: speed matters on both sides.", "fullText": "Mandiant's M-Trends 2025 report covered its 2024 investigations. Exploits were the most common way in, at 33%. Stolen credentials came second at 16%, the first time they ranked that high.\n\nThe median dwell time, how long attackers stayed before being found, was 11 days, up from 10 the year before. It was 26 days when an outside party told the victim, 10 when the victim found it, and 5 when attackers announced themselves, usually with ransomware.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/m-trends-2025/", "label": "Google Cloud (Mandiant), M-Trends 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What was the most common way in, according to M-Trends 2025?", "options": ["Exploits", "Stolen credentials", "Email phishing"], "correctIndex": 0, "explanation": "Exploits led at 33%; stolen credentials were second at 16%."}, "numbers": {"kind": "numberSense", "prompt": "What was the median dwell time in days, per M-Trends 2025?", "min": 0, "max": 40, "value": 11, "unit": "days", "explanation": "11 days, up from 10 the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why exploits lead initial access.", "prompt": "Which point fits the data best?", "options": ["Exploits are rare and very hard for attackers to use", "Logins are never stolen", "Attackers use new flaws faster than teams patch"], "correctIndex": 2, "consequences": ["They were the most common way in.", "Stolen logins were second, at 16%.", "Exploits led at 33% of intrusions."], "explanation": "When flaws are used within days, slow patching leaves doors open."}, "proReasoning": "Strong candidates connect speed of exploitation to patch speed.", "commonMistake": "Treating exploits as rare.", "mentalModel": "Patch speed decides exposure."}, "invest": {"call": {"kind": "theCall", "situation": "A detection company you follow claims it finds intruders faster.", "prompt": "Which number puts that claim in context?", "options": ["Median dwell time was 11 days", "Exploits were 100% of cases", "Dwell time is always one year"], "correctIndex": 0, "consequences": ["A vendor should beat that benchmark.", "They were 33%.", "The median was 11 days."], "explanation": "A benchmark like 11 days lets you judge whether a speed claim means much."}, "proReasoning": "Investors compare claims to an independent benchmark.", "commonMistake": "Accepting a speed claim with no baseline.", "mentalModel": "Compare claims to a benchmark."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies detect intruders themselves.", "prompt": "Which finding supports your pitch?", "options": ["Attackers never stay hidden", "Dwell time was 26 days when outsiders told victims", "Victims usually found attackers within one hour"], "correctIndex": 1, "consequences": ["Dwell time shows they do.", "Finding it yourself cut that to 10 days.", "The median was 11 days."], "explanation": "Self-detection beat outside notice by more than two weeks. That is the value you sell."}, "proReasoning": "Founders show the gap their product closes.", "commonMistake": "Pitching without the gap in numbers.", "mentalModel": "Show the gap you close."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how long hackers usually stay before being caught.", "prompt": "What's a good answer?", "options": ["Always less than a minute after they get in", "Usually around ten years", "About 11 days at the median, per Mandiant"], "correctIndex": 2, "consequences": ["Much longer than that.", "Far shorter than that.", "M-Trends 2025 put it at 11 days."], "explanation": "The median was 11 days, longer when someone else spotted it."}, "proReasoning": "Ask who found the intruder. It changes the answer.", "commonMistake": "Assuming attacks are caught instantly.", "mentalModel": "About 11 days, at the median."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:27bf123a7d86$ml$]::text[]),
($ml$5d6f6e32-019d-56cc-aecd-ba8ca5a971ca$ml$::uuid, $ml$cybersecurity$ml$, 10, 2, $ml${"id": "cybersecurity-d10-c2", "title": "Two weeks versus five days", "lessonTitle": "Five days to exploit", "slot": 2, "type": "connect", "brief": {"headline": "CISA gives agencies two weeks to fix most known exploited flaws. Mandiant found attackers in 2023 exploited new flaws within five days on average.", "kicker": "Connect day 9 and day 10: the clock and the race do not match.", "fullText": "Day 9 set the federal patching clock. Under BOD 22-01, US civilian agencies must fix most flaws on CISA's catalog within two weeks.\n\nDay 10 timed the attackers. Mandiant found the average time-to-exploit fell from 63 days in 2018 and 2019 to 32 days in 2021 and 2022, then five days in 2023. About 70% of the exploited flaws it tracked were zero-days. A two-week deadline can still trail the attackers.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Which is shorter?", "left": {"name": "Average time-to-exploit, 2023", "note": "Mandiant's measured average"}, "right": {"name": "BOD 22-01 deadline", "note": "For most listed flaws"}, "correctIndex": 0, "explanation": "Five days is well under two weeks, so attackers can move before the deadline."}, "numbers": {"kind": "numberSense", "prompt": "What was the average time-to-exploit in 2023, in days?", "min": 0, "max": 40, "value": 5, "unit": "days", "explanation": "Five days, down from 63 in 2018 and 2019."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked whether meeting a two-week deadline is enough.", "prompt": "What is the best answer?", "options": ["It is a floor; attackers can move in five days", "Yes, attackers always wait at least two weeks", "Deadlines do not matter at all"], "correctIndex": 0, "consequences": ["Time-to-exploit averaged five days in 2023.", "They moved faster on average.", "They set a minimum standard."], "explanation": "A deadline is the minimum. The attackers' pace sets what is actually safe."}, "proReasoning": "Strong candidates treat compliance as a floor, not the goal.", "commonMistake": "Treating compliance as safety.", "mentalModel": "Compliance is the floor."}, "invest": {"call": {"kind": "theCall", "situation": "A company says it meets all patch deadlines, so it is secure.", "prompt": "What should you think?", "options": ["Deadlines are only for show", "Deadlines can trail how fast attackers move", "Meeting every deadline means zero risk"], "correctIndex": 1, "consequences": ["They do push action.", "Five days versus two weeks.", "Attackers can move first."], "explanation": "Meeting a deadline is good, but attackers often move faster."}, "proReasoning": "Investors question claims that equate compliance with safety.", "commonMistake": "Taking \"we meet deadlines\" as proof of safety.", "mentalModel": "Compliance is not safety."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup patches critical flaws within 48 hours.", "prompt": "Which contrast sells it?", "options": ["Attackers take months to act", "Deadlines are already much faster than attackers move", "Attackers move in five days; deadlines allow two weeks"], "correctIndex": 2, "consequences": ["They now take days.", "They are not.", "Your speed beats both."], "explanation": "The gap between the deadline and the attackers' pace is the space you sell into."}, "proReasoning": "Founders show where the standard falls short.", "commonMistake": "Using outdated numbers on attacker speed.", "mentalModel": "Sell into the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why two weeks to fix a known flaw might be too slow.", "prompt": "What's the answer?", "options": ["Attackers in 2023 averaged five days to exploit", "Two weeks is faster than any attack ever happens", "Flaws expire on their own"], "correctIndex": 0, "consequences": ["Five days beats two weeks.", "Many attacks come sooner.", "They stay open until fixed."], "explanation": "Attackers have sped up. Five days on average means some move even faster."}, "proReasoning": "Compare the deadline to the attackers' pace.", "commonMistake": "Assuming attackers wait.", "mentalModel": "Attackers move in days."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e1d98557d2be$ml$]::text[]),
($ml$8b1e9ee2-7462-5024-b168-0645a43f9572$ml$::uuid, $ml$cybersecurity$ml$, 10, 3, $ml${"id": "cybersecurity-d10-c3", "title": "The monthly patch cycle", "lessonTitle": "Five days to exploit", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a retailer that patches once a month. Mandiant found attackers exploited new flaws within five days on average in 2023, and about 70% were zero-days.", "kicker": "Decide: keep the monthly cycle, or change it?", "fullText": "You run IT at a mid-size retailer. Your team installs patches on one day each month.\n\nDay 10 timed the race. Mandiant found the average time-to-exploit fell to five days in 2023. Of 138 exploited flaws it tracked, 97 were zero-days, about 70%. It also noted that leaving out 15 outliers changed the average: with them, it rises to 47 days.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Average time-to-exploit was five days in 2023.", "About 70% of exploited flaws were zero-days.", "Attackers waited a month on average in 2023."], "fakeIndex": 2, "explanation": "The average was five days, excluding 15 outliers."}, "numbers": {"kind": "numberSense", "prompt": "Of 138 exploited flaws Mandiant tracked from 2023, how many were zero-days?", "min": 0, "max": 150, "value": 97, "unit": "", "explanation": "97, about 70%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to fix a monthly patch cycle.", "prompt": "What do you suggest?", "options": ["Stop patching to avoid downtime", "Add a fast lane for exploited, exposed flaws", "Move to once a year to save the team time"], "correctIndex": 1, "consequences": ["That leaves every door open.", "Urgent flaws get fixed in days.", "That widens the gap."], "explanation": "Keep the monthly cycle for routine fixes, but rush flaws attackers are using."}, "proReasoning": "Strong candidates add a fast path instead of tearing everything up.", "commonMistake": "Treating all patches the same.", "mentalModel": "Add a fast lane for urgent flaws."}, "invest": {"call": {"kind": "theCall", "situation": "A retailer you hold patches monthly and has internet-facing systems.", "prompt": "What risk should you note?", "options": ["Monthly patching means there is zero risk", "Retailers are never targeted", "Exploited flaws may stay open for weeks"], "correctIndex": 2, "consequences": ["The gap leaves exposure.", "Retailers hold payment data.", "Attackers averaged five days in 2023."], "explanation": "A month-long gap is far longer than five days."}, "proReasoning": "Investors ask how fast a company closes urgent gaps.", "commonMistake": "Assuming a schedule equals safety.", "mentalModel": "Ask how fast urgent gaps close."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tests patches overnight so retailers can deploy them faster.", "prompt": "Which fact supports your pitch?", "options": ["Average time-to-exploit fell to five days", "Attackers slowed down a lot during 2023", "Patching is never risky"], "correctIndex": 0, "consequences": ["Faster testing closes the gap.", "They sped up.", "Testing exists because it can be."], "explanation": "Retailers fear breaking systems with untested patches. Faster testing removes that excuse."}, "proReasoning": "Founders remove the reason buyers delay.", "commonMistake": "Ignoring why buyers wait.", "mentalModel": "Remove the reason to wait."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some companies patch more than once a month.", "prompt": "What's a good answer?", "options": ["Hackers only work on weekends, so a week is plenty", "Attackers often move within days of a flaw going public", "Patches expire after a week"], "correctIndex": 1, "consequences": ["Attackers work anytime.", "Five days on average in 2023.", "Patches do not expire."], "explanation": "When attackers move in days, a monthly cycle can leave a door open for weeks."}, "proReasoning": "Compare patch timing to attack timing.", "commonMistake": "Thinking a monthly routine is always enough.", "mentalModel": "Attackers move in days."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b9476641f48c$ml$]::text[]),
($ml$308b1ff7-ae1d-5cf6-a69c-4356b93ff9e4$ml$::uuid, $ml$cybersecurity$ml$, 11, 1, $ml${"id": "cybersecurity-d11-c1", "title": "A script on 100,000 websites", "lessonTitle": "The flaw hiding in everything", "slot": 1, "type": "apply", "brief": {"headline": "In 2024, a script loaded by more than 100,000 websites from polyfill.io began sending some mobile visitors to scam sites. A new owner had bought the domain in February.", "kicker": "Apply the idea: one shared piece of code reached every site that used it.", "fullText": "Polyfill.io served a small piece of JavaScript that many websites loaded so older browsers could run modern code. In February 2024, a Chinese company called Funnull bought the domain and its GitHub account.\n\nSecurity researchers later found the script had been changed to redirect some mobile visitors to scam sites. It activated only on certain devices and at certain hours, which made it harder to spot. More than 100,000 sites were affected, because each one loaded the code from the same place.", "sources": [{"url": "https://www.bleepingcomputer.com/news/security/polyfillio-javascript-supply-chain-attack-impacts-over-100K-sites/", "label": "BleepingComputer, polyfill.io supply chain attack hits 100K+ sites"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the polyfill.io story in order.", "steps": ["Many sites load a shared script from polyfill.io", "A new owner buys the domain and GitHub account", "The script starts sending some mobile visitors to scams", "Researchers trace it to the shared script"], "explanation": "A change at one source reached every site that loaded from it."}, "numbers": {"kind": "numberSense", "prompt": "About how many websites were affected, in thousands?", "min": 0, "max": 300, "value": 100, "unit": "K", "explanation": "More than 100,000 sites, per BleepingComputer."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what polyfill.io teaches about third-party code.", "prompt": "Which lesson do you lead with?", "options": ["Know what outside code you load and who owns it", "Outside scripts are always safe to load", "Only big sites need to check their scripts"], "correctIndex": 0, "consequences": ["Ownership changed, and so did the code.", "This script turned malicious.", "Over 100,000 sites of all sizes were hit."], "explanation": "Every outside script is a dependency. If its owner changes, so can its behavior."}, "proReasoning": "Strong candidates think about who controls each dependency.", "commonMistake": "Treating code from a familiar source as safe forever.", "mentalModel": "Know who controls your dependencies."}, "invest": {"call": {"kind": "theCall", "situation": "An online retailer you hold loads many scripts from outside sources.", "prompt": "What risk does polyfill.io highlight?", "options": ["Scripts cannot affect what customers see", "Someone else's change can hit its customers", "Outside scripts make checkout faster always"], "correctIndex": 1, "consequences": ["This one sent visitors to scams.", "A changed script redirected visitors.", "Speed is not the risk here."], "explanation": "A company can be hurt by code it did not write and does not control."}, "proReasoning": "Investors ask how much a business relies on parts it does not control.", "commonMistake": "Assuming a website only runs its own code.", "mentalModel": "Count the parts you do not control."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup alerts websites when a script they load changes behavior.", "prompt": "Why does polyfill.io support your pitch?", "options": ["It affected only one small website", "It never changed at all after it was sold", "It hid by activating only at certain times"], "correctIndex": 2, "consequences": ["More than 100,000 sites were hit.", "It was changed after the sale.", "That makes it hard to catch without monitoring."], "explanation": "A script that misbehaves only sometimes slips past casual checks. Monitoring catches it."}, "proReasoning": "Founders point to the hard part their product solves.", "commonMistake": "Pitching a problem a quick manual check would catch.", "mentalModel": "Solve the hard-to-see part."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one script could affect 100,000 websites at once.", "prompt": "What's the simple answer?", "options": ["They all loaded it from the same place", "Each site was hacked one at a time", "The browsers themselves were broken"], "correctIndex": 0, "consequences": ["One change reached every site.", "One source was changed, not each site.", "The script was the problem."], "explanation": "Shared code means shared risk. Change the source and every user gets the change."}, "proReasoning": "Ask where the code comes from. Many sites may share it.", "commonMistake": "Picturing each site being hacked separately.", "mentalModel": "Shared code spreads one change."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:702d148784e8$ml$]::text[]),
($ml$cc6eef35-19bb-5f7f-912d-f25eba22efb6$ml$::uuid, $ml$cybersecurity$ml$, 11, 2, $ml${"id": "cybersecurity-d11-c2", "title": "A CVE you cannot find", "lessonTitle": "The flaw hiding in everything", "slot": 2, "type": "connect", "brief": {"headline": "In 2024, 40,009 CVEs were published. Log4j showed the harder problem: a US board said unpatched copies may linger for a decade, and firms often did not know where it ran.", "kicker": "Connect day 7 and day 11: a CVE names a flaw, not where it lives.", "fullText": "Day 7 showed how flaws get named. Each public flaw gets a CVE number so everyone can refer to the same bug, and 40,009 were published in 2024.\n\nDay 11 showed what a number cannot tell you. Log4j's flaw had a fix, but the library was buried inside so many products that companies often did not know they used it. In July 2022, the Cyber Safety Review Board called it endemic and warned unpatched copies would remain for a decade or longer.", "sources": [{"url": "https://jerrygamblin.com/2025/01/05/2024-cve-data-review/", "label": "Jerry Gamblin, 2024 CVE data review"}, {"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did Log4j stay dangerous after a fix existed?", "options": ["Firms did not know where it was used", "The fix made the flaw worse", "No CVE number was ever assigned"], "correctIndex": 0, "explanation": "You cannot patch what you do not know you run."}, "numbers": {"kind": "numberSense", "prompt": "How many recommendations did the review board make?", "min": 0, "max": 30, "value": 19, "unit": "", "explanation": "19 recommendations, including better security for open source."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what to do first when a flaw like Log4j is announced.", "prompt": "What do you say?", "options": ["Patch only the newest servers that you own", "Find every place the library runs, then patch", "Wait for each vendor to email you"], "correctIndex": 1, "consequences": ["Old copies were the problem.", "An inventory makes the patch possible.", "Many vendors did not know either."], "explanation": "Inventory first. A CVE tells you what is broken, not where it is."}, "proReasoning": "Strong candidates know the hard part is finding the flaw.", "commonMistake": "Jumping to patching without knowing where to patch.", "mentalModel": "Inventory before patching."}, "invest": {"call": {"kind": "theCall", "situation": "A software company you follow says it can list every library inside its products.", "prompt": "Why might that matter?", "options": ["It means its products have no flaws", "It matters only to its lawyers", "It can find and fix buried flaws faster"], "correctIndex": 2, "consequences": ["A list does not remove flaws.", "It matters to customers and security.", "Log4j showed how hard finding them can be."], "explanation": "Knowing what is inside a product cuts the time from announcement to fix."}, "proReasoning": "Investors value companies that can answer \"are we affected?\" quickly.", "commonMistake": "Seeing an inventory as paperwork.", "mentalModel": "Value fast answers to \"are we affected?\""}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a list of every library inside a company's software.", "prompt": "Which fact makes your case?", "options": ["Unpatched Log4j may linger for a decade", "Log4j was fixed everywhere in a week", "Libraries never contain flaws"], "correctIndex": 0, "consequences": ["Because firms could not find it.", "The board said the opposite.", "Log4j shows they do."], "explanation": "If old copies linger because nobody can find them, a reliable inventory has lasting value."}, "proReasoning": "Founders build for problems expected to last.", "commonMistake": "Building for a problem that has already passed.", "mentalModel": "Build for the lasting problem."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Log4j is still a problem years later.", "prompt": "What's the answer?", "options": ["It only affects old phones", "Old copies hide inside many products", "Nobody ever released a fix for it"], "correctIndex": 1, "consequences": ["It was in software of all kinds.", "The board expects them to linger for a decade.", "A fix exists."], "explanation": "A fix exists, but finding every copy is the hard part."}, "proReasoning": "Ask whether people know where a flaw lives.", "commonMistake": "Assuming a fix ends a flaw.", "mentalModel": "Finding copies is the hard part."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1f0adbd5b8d9$ml$]::text[]),
($ml$25077b4d-01ee-5234-bdab-b521cf81dcee$ml$::uuid, $ml$cybersecurity$ml$, 11, 3, $ml${"id": "cybersecurity-d11-c3", "title": "A flaw in a library you may use", "lessonTitle": "The flaw hiding in everything", "slot": 3, "type": "decide", "brief": {"headline": "You run security at an insurer. A flaw like Log4j has just been announced in a widely used library, and you are not sure where it runs in your company.", "kicker": "Decide: patch what you know, or find out what you have?", "fullText": "You run security at an insurer with hundreds of applications, some built by vendors. A serious flaw has just been announced in a widely used free library.\n\nDay 11 showed why this is hard. Log4j sat inside countless products, and companies often did not know it was there. The Cyber Safety Review Board said open-source developers are thinly resourced and that unpatched copies would remain for a decade or longer.", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}]}, "evidence": {"kind": "faceOff", "prompt": "Which first move makes patching possible?", "left": {"name": "Patch the systems you know about", "note": "Fast, but may miss hidden copies"}, "right": {"name": "Inventory where the library runs", "note": "Slower start, but finds hidden copies"}, "correctIndex": 1, "explanation": "You cannot patch what you do not know you run."}, "numbers": {"kind": "numberSense", "prompt": "For about how many years did the board say unpatched copies may remain?", "min": 0, "max": 25, "value": 10, "unit": "years", "explanation": "A decade, if not longer."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how to handle a Log4j-style flaw at a large firm.", "prompt": "What do you recommend?", "options": ["Patch one server and call the job done", "Wait a year for things to settle", "Inventory first, then patch and ask vendors"], "correctIndex": 2, "consequences": ["Copies hide across many systems.", "Attackers do not wait a year.", "It finds hidden copies and vendor products."], "explanation": "Knowing where the library runs, including in vendor products, comes before any fix."}, "proReasoning": "Strong candidates lay out a sequence, not just an action.", "commonMistake": "Patching the obvious and missing the hidden.", "mentalModel": "Sequence: find, fix, confirm."}, "invest": {"call": {"kind": "theCall", "situation": "An insurer you hold took weeks to say whether it was affected by a major flaw.", "prompt": "What does that suggest?", "options": ["It may not know what software it runs", "It has excellent security for sure", "The flaw cannot affect insurers"], "correctIndex": 0, "consequences": ["Slow answers often mean no inventory.", "Slowness suggests the opposite.", "Log4j was everywhere."], "explanation": "A slow answer to \"are we affected?\" often points to missing inventory."}, "proReasoning": "Investors read response speed as a sign of maturity.", "commonMistake": "Reading silence as safety.", "mentalModel": "Read slow answers as a gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup asks vendors to list the libraries inside their products.", "prompt": "Who is your best first customer?", "options": ["Firms that use no software", "Firms that rely on many vendor applications", "People who run one simple personal website"], "correctIndex": 1, "consequences": ["Nothing to inventory.", "They cannot see inside vendor products alone.", "Little to inventory."], "explanation": "Large buyers of vendor software cannot see inside it on their own."}, "proReasoning": "Founders sell where visibility is weakest.", "commonMistake": "Selling to buyers with nothing to inventory.", "mentalModel": "Sell where visibility is weakest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company cannot just update the broken library.", "prompt": "What's the answer?", "options": ["Updating software is not allowed", "Libraries can never be updated", "It may not know where the library is"], "correctIndex": 2, "consequences": ["Updates are allowed.", "A fix existed.", "Log4j was buried inside many products."], "explanation": "Libraries are often buried inside other products. Finding them is the first job."}, "proReasoning": "Ask whether the company knows what it runs.", "commonMistake": "Assuming every company knows its software.", "mentalModel": "First find it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4ba6f92808ab$ml$]::text[]),
($ml$021115e6-2cbc-5d01-ad0a-1abbb4885fba$ml$::uuid, $ml$cybersecurity$ml$, 12, 1, $ml${"id": "cybersecurity-d12-c1", "title": "A new hire who was not real", "lessonTitle": "The backdoor found by accident", "slot": 1, "type": "apply", "brief": {"headline": "In July 2024, KnowBe4 found that a remote engineer it had just hired was a North Korean fake IT worker. He had passed background checks and four video interviews.", "kicker": "Apply the idea: trust can be earned on purpose.", "fullText": "KnowBe4, a security training company, hired a remote software engineer for an internal IT team. The person passed background checks, had verified references and completed four video interviews.\n\nOn July 15, 2024, malware was loaded onto the company Mac sent to the new hire, and KnowBe4's security software flagged it. The company contained the device that evening and said no data was lost. The worker turned out to be a fake IT worker from North Korea. Like the XZ attacker, he got in by passing as trustworthy.", "sources": [{"url": "https://cyberscoop.com/cyber-firm-knowbe4-hired-a-fake-it-worker-from-north-korea/", "label": "CyberScoop, KnowBe4 hired a fake IT worker from North Korea"}, {"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The hire passed four video interviews.", "KnowBe4 said no data was lost.", "The hire failed the background check."], "fakeIndex": 2, "explanation": "The person passed background checks and had verified references."}, "numbers": {"kind": "numberSense", "prompt": "How many video interviews did the fake worker pass?", "min": 0, "max": 10, "value": 4, "unit": "", "explanation": "Four, plus background checks and verified references."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a security role, you're asked what KnowBe4 teaches.", "prompt": "Which lesson is best?", "options": ["Remote workers should never be hired", "Limit new hires' access and watch their devices", "Background checks catch every fake worker"], "correctIndex": 1, "consequences": ["Far too blunt; monitoring worked.", "Monitoring caught it the same day.", "This one passed the checks."], "explanation": "Hiring checks can be fooled. Limited access and monitoring catch what checks miss."}, "proReasoning": "Strong candidates add layers instead of trusting one gate.", "commonMistake": "Relying on a single check to stop a determined attacker.", "mentalModel": "Layer checks after the hire."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold hires many remote engineers.", "prompt": "What does the KnowBe4 case suggest?", "options": ["Remote hiring has no security risk", "Only small firms ever get fake applicants", "Hiring itself can be a way in for attackers"], "correctIndex": 2, "consequences": ["This case shows a real risk.", "KnowBe4 is a security firm.", "A fake worker passed every hiring step."], "explanation": "Insider access can come through hiring. Controls after hiring matter."}, "proReasoning": "Investors ask how a company limits new hires' early access.", "commonMistake": "Assuming hiring is outside security.", "mentalModel": "Treat hiring as an access decision."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup verifies remote job candidates' identities.", "prompt": "Which fact makes your case?", "options": ["A fake passed checks and four interviews", "Fake workers never pass interviews", "Only junior roles are targeted"], "correctIndex": 0, "consequences": ["Standard steps were not enough.", "This one passed four.", "This was an engineering role."], "explanation": "If standard checks and interviews can be fooled, stronger identity checks have value."}, "proReasoning": "Founders point to where existing checks failed.", "commonMistake": "Ignoring how the existing process failed.", "mentalModel": "Show where current checks fail."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a fake worker got hired by a security company.", "prompt": "What's the answer?", "options": ["The company hired him knowingly", "He passed the checks most firms rely on", "He broke into the office at night"], "correctIndex": 1, "consequences": ["KnowBe4 was fooled.", "Background checks, references, four interviews.", "He was hired remotely."], "explanation": "He looked like a normal candidate on every step. Trust was the way in."}, "proReasoning": "Ask what each check actually proves.", "commonMistake": "Assuming checks prove identity.", "mentalModel": "Trust can be faked."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:60b733632912$ml$]::text[]),
($ml$ec7c009a-15f1-57f5-bd9b-a3d6ad052f1d$ml$::uuid, $ml$cybersecurity$ml$, 12, 2, $ml${"id": "cybersecurity-d12-c2", "title": "Few hands, big targets", "lessonTitle": "The backdoor found by accident", "slot": 2, "type": "connect", "brief": {"headline": "A US board said open-source developers behind tools like Log4j are thinly resourced. In 2024, an attacker spent years earning trust in XZ Utils before planting a backdoor.", "kicker": "Connect day 11 and day 12: thin maintainer teams draw attackers.", "fullText": "Day 11 showed the Cyber Safety Review Board warning that open-source developers are thinly resourced, even though software everywhere depends on them.\n\nDay 12 showed someone exploiting that. In XZ Utils, a compression tool used in Linux, an account contributed for several years, earned trust, then signed versions 5.6.0 and 5.6.1 containing a backdoor. Engineer Andres Freund caught it in March 2024 after noticing SSH logins taking 500 milliseconds longer.", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}, {"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each fact by what it shows.", "buckets": ["Why attackers aim here", "How it was caught"], "items": [{"text": "Key tools rely on a handful of volunteers", "bucket": 0}, {"text": "Few safeguards check who earns commit rights", "bucket": 0}, {"text": "An engineer noticed logins were half a second slow", "bucket": 1}, {"text": "The bad versions were mostly in early test releases", "bucket": 1}], "explanation": "Thin teams make a tempting target; curiosity and luck caught this one early."}, "numbers": {"kind": "numberSense", "prompt": "How many milliseconds longer were the SSH logins?", "min": 0, "max": 2000, "value": 500, "unit": "ms", "explanation": "About 500 milliseconds, half a second."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why open source is a supply chain risk.", "prompt": "What is the best answer?", "options": ["Open source is always less secure than paid", "Nobody uses open source in production", "Critical tools rely on a few thinly funded people"], "correctIndex": 2, "consequences": ["The issue is resourcing, not openness.", "It runs almost everywhere.", "The board and XZ both show this."], "explanation": "The risk is not open code itself. It is critical code kept up by few people."}, "proReasoning": "Strong candidates name the real weak point precisely.", "commonMistake": "Blaming openness instead of resourcing.", "mentalModel": "Name the real weak point."}, "invest": {"call": {"kind": "theCall", "situation": "A company you follow funds the open-source projects it depends on.", "prompt": "How might you read that?", "options": ["As reducing supply chain risk", "As charity with no business value", "As proof its own code is weak"], "correctIndex": 0, "consequences": ["Thin teams were the weak point.", "It protects tools the company relies on.", "It says nothing about that."], "explanation": "Supporting critical maintainers can lower the risk of another XZ."}, "proReasoning": "Investors look for spending that protects what the business relies on.", "commonMistake": "Dismissing support for dependencies as goodwill.", "mentalModel": "Fund what you depend on."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup flags risky changes in open-source projects.", "prompt": "Which XZ detail supports your pitch?", "options": ["It shipped in every Linux release", "It was caught by luck, not by a tool", "A security tool caught it right away"], "correctIndex": 1, "consequences": ["Mostly early test releases.", "A tool could catch the next one sooner.", "It was caught by one curious engineer."], "explanation": "If curiosity caught it, a tool that looks for odd changes fills a real gap."}, "proReasoning": "Founders aim at what relied on luck last time.", "commonMistake": "Claiming the problem was already solved.", "mentalModel": "Replace luck with a process."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an attacker would spend years on a free tool.", "prompt": "What's the answer?", "options": ["Because the tool pays its volunteers a lot", "Because free tools are never used", "Because the tool runs inside countless systems"], "correctIndex": 2, "consequences": ["The board said they are thinly resourced.", "XZ is used in Linux.", "One backdoor could reach many machines."], "explanation": "One trusted change to a widely used tool can reach a huge number of systems."}, "proReasoning": "Ask how far one change would spread.", "commonMistake": "Thinking free means unimportant.", "mentalModel": "Reach makes it worth the wait."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ae03318a597d$ml$]::text[]),
($ml$546db283-2dc1-5db9-bc1e-c2aefbad8403$ml$::uuid, $ml$cybersecurity$ml$, 12, 3, $ml${"id": "cybersecurity-d12-c3", "title": "Who gets commit rights?", "lessonTitle": "The backdoor found by accident", "slot": 3, "type": "decide", "brief": {"headline": "You run engineering at a startup that depends on a small open-source library kept up by one volunteer. A helpful new contributor has asked to become a maintainer.", "kicker": "Decide: how should trust be granted?", "fullText": "You run engineering at a startup. Your product depends on a small open-source library kept up by one tired volunteer. A friendly new contributor has offered to help maintain it.\n\nDay 12 showed the risk. In XZ Utils, an account contributed for several years, earned trust, then signed releases containing a backdoor. Few safeguards check who earns commit rights. It was caught in March 2024 because one engineer noticed a 500 millisecond delay.", "sources": [{"url": "https://www.elastic.co/cn/security-labs/500ms-to-midnight", "label": "Elastic Security Labs, the xz backdoor"}]}, "evidence": {"kind": "faceOff", "prompt": "Which approach lowers your exposure more?", "left": {"name": "Pin versions and review updates", "note": "Check changes before you take them"}, "right": {"name": "Always pull the latest release", "note": "Get new code as soon as it ships"}, "correctIndex": 0, "explanation": "The XZ backdoor shipped in new releases; reviewing updates gives you a chance to catch odd changes."}, "numbers": {"kind": "numberSense", "prompt": "How many backdoored XZ versions shipped?", "min": 0, "max": 10, "value": 2, "unit": "", "explanation": "Two: versions 5.6.0 and 5.6.1."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to manage risky open-source dependencies.", "prompt": "What do you suggest?", "options": ["Pin versions, review changes, and support maintainers", "Always take the newest release at once", "Trust any contributor who seems helpful and kind"], "correctIndex": 0, "consequences": ["It adds checks where XZ had few.", "The backdoor came in new releases.", "The XZ attacker seemed helpful too."], "explanation": "Pinning and review slow down a bad change, and support reduces burnout."}, "proReasoning": "Strong candidates add checks without abandoning open source.", "commonMistake": "Treating helpfulness as proof of good intent.", "mentalModel": "Add checks to trust."}, "invest": {"call": {"kind": "theCall", "situation": "A startup you might back depends heavily on one volunteer-run library.", "prompt": "What should you ask?", "options": ["Whether it uses the newest version always", "How it reviews updates to that library", "Whether the library has a nice logo"], "correctIndex": 1, "consequences": ["Newest is how the backdoor spread.", "That is where XZ-style risk enters.", "Branding does not matter."], "explanation": "A critical dependency with one maintainer is a risk worth asking about."}, "proReasoning": "Investors ask about single points of failure.", "commonMistake": "Ignoring dependencies because they are free.", "mentalModel": "Ask about single points of failure."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the startup and the new contributor wants maintainer rights now.", "prompt": "What should you push for?", "options": ["Give full rights today to save time", "Fork the library and never take an update again", "Earn rights over time, with code review on releases"], "correctIndex": 2, "consequences": ["XZ shows trust can be faked.", "Never updating leaves known flaws open.", "Review makes a quiet backdoor harder."], "explanation": "Gradual trust plus review on every release makes a planted change harder."}, "proReasoning": "Founders protect the parts their product depends on.", "commonMistake": "Handing out access to the first helpful person.", "mentalModel": "Grant trust gradually, with review."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a backdoor got into a trusted tool.", "prompt": "What's the simple answer?", "options": ["A contributor earned trust for years, then abused it", "A virus jumped in from the internet", "The tool was always meant to be a hidden backdoor"], "correctIndex": 0, "consequences": ["That is what happened with XZ.", "It was signed by a trusted account.", "It was a long-trusted tool."], "explanation": "The attacker played the long game: years of help, then a poisoned release."}, "proReasoning": "Ask who can change the code, and how they earned that right.", "commonMistake": "Assuming trusted means safe.", "mentalModel": "Trust can be a long con."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ccb98c40c790$ml$]::text[]),
($ml$f8555459-3ae9-5689-84a4-bd1458d36fa4$ml$::uuid, $ml$cybersecurity$ml$, 13, 1, $ml${"id": "cybersecurity-d13-c1", "title": "A label for smart devices", "lessonTitle": "Three ways to prove you are secure", "slot": 1, "type": "apply", "brief": {"headline": "In January 2025, the US launched the Cyber Trust Mark, a label for smart devices backed by testing against NIST criteria. A QR code links to details like how long updates last.", "kicker": "Apply the idea: a label is one more way to prove security.", "fullText": "The FCC launched the US Cyber Trust Mark on January 7, 2025. It is a shield logo on devices like home cameras, smart appliances, fitness trackers and baby monitors.\n\nProducts are tested against NIST criteria by accredited labs recognized by the FCC. A QR code links to a registry with details such as how long the device will get support and whether it updates automatically. Medical devices, vehicles and enterprise gear are excluded.", "sources": [{"url": "https://thehackernews.com/2025/01/fcc-launches-cyber-trust-mark-for-iot.html", "label": "The Hacker News, FCC launches the Cyber Trust Mark"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each device in scope for the Cyber Trust Mark?", "buckets": ["Covered", "Excluded"], "items": [{"text": "A home security camera", "bucket": 0}, {"text": "A baby monitor", "bucket": 0}, {"text": "A fitness tracker", "bucket": 0}, {"text": "A car", "bucket": 1}, {"text": "A medical device", "bucket": 1}], "explanation": "The mark covers consumer smart devices; medical devices, vehicles and enterprise gear are excluded."}, "numbers": {"kind": "numberSense", "prompt": "On what day of January 2025 was the Cyber Trust Mark launched?", "min": 1, "max": 31, "value": 7, "unit": "", "explanation": "January 7, 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a smart camera maker. They ask what the Cyber Trust Mark means for them.", "prompt": "What do you say?", "options": ["It is a logo they can print without any lab testing", "It applies only to cars and medical devices", "Test against NIST criteria and publish support details"], "correctIndex": 2, "consequences": ["Testing by accredited labs is required.", "Those are excluded.", "Accredited labs test, and the QR code shows support."], "explanation": "The mark rests on lab testing and public details. Both take work."}, "proReasoning": "Strong candidates know what a label requires, not just that it exists.", "commonMistake": "Treating a label as marketing alone.", "mentalModel": "Know what the label requires."}, "invest": {"call": {"kind": "theCall", "situation": "A smart device maker you hold earns the Cyber Trust Mark.", "prompt": "How might that matter?", "options": ["It gives buyers a simple signal of security", "It removes all future security risk", "It means the device never needs updates"], "correctIndex": 0, "consequences": ["A label helps buyers compare.", "It is a signal, not a guarantee.", "The registry shows update support."], "explanation": "A trusted label can help a product stand out to buyers."}, "proReasoning": "Investors watch for labels that shape buying choices.", "commonMistake": "Treating a label as a guarantee.", "mentalModel": "A label is a signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps smart device makers prepare for lab testing.", "prompt": "Which fact supports your pitch?", "options": ["The program covers only vehicles and medical gear", "Testing is done by accredited labs on NIST criteria", "Makers can just print the logo"], "correctIndex": 1, "consequences": ["Vehicles are excluded.", "Makers need to pass a real test.", "Testing is required."], "explanation": "A required test creates demand for help passing it."}, "proReasoning": "Founders build around a step buyers must clear.", "commonMistake": "Building around an optional step.", "mentalModel": "Build around a required step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees the Cyber Trust Mark on a baby monitor.", "prompt": "What does it tell them?", "options": ["It can never be hacked", "It is made and sold by the US government itself", "It was tested, and the QR code shows support details"], "correctIndex": 2, "consequences": ["No label guarantees that.", "It is a label, not a maker.", "Accredited labs test against NIST criteria."], "explanation": "The mark means testing happened and support details are public."}, "proReasoning": "Ask what a label tests and what it promises.", "commonMistake": "Reading a label as a promise of no risk.", "mentalModel": "Read what the label proves."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:42440ad4cba6$ml$]::text[]),
($ml$c58e53f4-ce07-541f-aedf-5f3365ee1d47$ml$::uuid, $ml$cybersecurity$ml$, 13, 2, $ml${"id": "cybersecurity-d13-c2", "title": "Disclosure meets governance", "lessonTitle": "Three ways to prove you are secure", "slot": 2, "type": "connect", "brief": {"headline": "US public companies must file within four business days once they judge a cyberattack material. In 2024, NIST added a Govern function to its framework.", "kicker": "Connect day 5 and day 13: leaders now own security decisions.", "fullText": "Day 5 set a disclosure clock. Under SEC rules, a US public company must file a Form 8-K within four business days of deciding a cyber incident is material. That decision is made by company leaders.\n\nDay 13 showed frameworks catching up. In February 2024, NIST released version 2.0 of its Cybersecurity Framework and added a sixth function, Govern, which covers how leaders make security decisions. Both point the same way: security is a leadership job.", "sources": [{"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did NIST add in Cybersecurity Framework 2.0?", "options": ["A required audit by a CPA", "A Govern function", "A ban on cloud services"], "correctIndex": 1, "explanation": "Govern joined Identify, Protect, Detect, Respond and Recover."}, "numbers": {"kind": "numberSense", "prompt": "How many functions does NIST CSF 2.0 have?", "min": 0, "max": 15, "value": 6, "unit": "", "explanation": "Six: Govern, Identify, Protect, Detect, Respond and Recover."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why NIST added Govern.", "prompt": "What is the best answer?", "options": ["Security decisions now sit with leadership", "To replace all of the five other functions", "To make the framework a legal rule"], "correctIndex": 0, "consequences": ["It covers how leaders decide.", "It joined them.", "The framework stays voluntary."], "explanation": "Govern makes leadership decisions part of the framework, matching rules like the SEC's."}, "proReasoning": "Strong candidates connect frameworks to the rules leaders face.", "commonMistake": "Thinking frameworks are only technical.", "mentalModel": "Tie frameworks to leadership."}, "invest": {"call": {"kind": "theCall", "situation": "You read a company's annual report and look for how it governs cyber risk.", "prompt": "Why does that matter now?", "options": ["The SEC removed its disclosure rule", "Leaders must make fast materiality calls", "Cyber risk is only an IT matter"], "correctIndex": 1, "consequences": ["The rule is in force.", "Four business days once judged material.", "The rules put it on leaders."], "explanation": "With a fast disclosure clock, how leaders decide matters to investors."}, "proReasoning": "Investors look at how a company decides, not only what it spends.", "commonMistake": "Treating governance as boilerplate.", "mentalModel": "Read how decisions get made."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps boards track cyber risk using NIST CSF 2.0.", "prompt": "Which feature fits the Govern function best?", "options": ["A faster antivirus scanner", "A tool that blocks spam email for the board", "A record of leaders' security decisions"], "correctIndex": 2, "consequences": ["That is Protect or Detect.", "That is Protect.", "Govern is about how leaders decide."], "explanation": "Govern is about decisions and oversight. A decision record fits it."}, "proReasoning": "Founders map features to the part of a framework buyers care about.", "commonMistake": "Selling a technical tool as governance.", "mentalModel": "Map features to the framework."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why company leaders now care about cybersecurity frameworks.", "prompt": "What's a good answer?", "options": ["Rules and frameworks now put decisions on them", "Leaders now write most of the security code", "Frameworks pay leaders bonuses"], "correctIndex": 0, "consequences": ["SEC materiality and NIST Govern both do.", "Engineers write code.", "They do not."], "explanation": "Disclosure rules and the new Govern function both make security a leadership job."}, "proReasoning": "Ask who has to make the call.", "commonMistake": "Assuming security stays in IT.", "mentalModel": "Security is a leadership job."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f06ab1a1b5db$ml$]::text[]),
($ml$2bb0ad90-2dce-53e5-940f-1bb511144aef$ml$::uuid, $ml$cybersecurity$ml$, 13, 3, $ml${"id": "cybersecurity-d13-c3", "title": "Proof for a year of controls", "lessonTitle": "Three ways to prove you are secure", "slot": 3, "type": "decide", "brief": {"headline": "You sell software to large firms. A customer wants proof your security controls worked over the past year. You could show NIST CSF, ISO 27001 or a SOC 2 report.", "kicker": "Decide: which proof answers the question asked?", "fullText": "You run a software company. A large customer wants proof that your security controls actually worked over the past year.\n\nDay 13 laid out three proofs. NIST CSF 2.0 is a voluntary framework. ISO/IEC 27001 sets requirements for a security management system, and companies can be certified. A SOC 2 is an audit by a CPA under AICPA criteria: Type I checks the design of controls, and Type II tests how they work over a period.", "sources": [{"url": "https://www.huntonprivacyblog.com/2024/03/04/nist-releases-cybersecurity-framework-2-0/", "label": "Hunton, NIST releases Cybersecurity Framework 2.0"}, {"url": "https://webcf.waybackmachine.org/web/20230531192221/https://www.iso.org/isoiec-27001-information-security.html", "label": "ISO, ISO/IEC 27001 information security management"}, {"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}]}, "evidence": {"kind": "faceOff", "prompt": "Which proof shows controls worked over time?", "left": {"name": "SOC 2 Type I", "note": "Checks the design of controls"}, "right": {"name": "SOC 2 Type II", "note": "Tests controls over a period"}, "correctIndex": 1, "explanation": "Type II tests how controls operate over time; Type I only checks their design."}, "numbers": {"kind": "numberSense", "prompt": "How many trust criteria can a SOC 2 cover?", "min": 0, "max": 12, "value": 5, "unit": "", "explanation": "Up to five. Security is always included; the other four are optional."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked which proof fits a customer asking about the past year.", "prompt": "What do you say?", "options": ["A SOC 2 Type I report", "A SOC 2 Type II report", "A printout of NIST CSF"], "correctIndex": 1, "consequences": ["It only checks design.", "It tests controls over a period.", "A framework is guidance, not proof."], "explanation": "The question is about operation over time. Type II answers it."}, "proReasoning": "Strong candidates match the proof to the question.", "commonMistake": "Offering the wrong proof because it is easier.", "mentalModel": "Match the proof to the question."}, "invest": {"call": {"kind": "theCall", "situation": "A software vendor you hold has only a SOC 2 Type I report.", "prompt": "What might large customers ask?", "options": ["For nothing more; Type I proves everything", "For a NIST CSF certificate", "For a Type II showing controls worked over time"], "correctIndex": 2, "consequences": ["It does not test operation.", "NIST CSF is not a certificate.", "Type I checks design only."], "explanation": "Large buyers often want evidence over time. Type I may not close the deal."}, "proReasoning": "Investors check whether a vendor's proof matches what buyers ask for.", "commonMistake": "Assuming any audit satisfies every buyer.", "mentalModel": "Check the proof buyers want."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing which proof to pursue first for enterprise sales.", "prompt": "What should guide the choice?", "options": ["What your target customers ask for", "Whichever proof is quickest to print", "Whatever a competitor in another field uses"], "correctIndex": 0, "consequences": ["Buyers decide what counts.", "Speed alone may not satisfy buyers.", "Different buyers want different proofs."], "explanation": "The right proof is the one your buyers trust. Ask them first."}, "proReasoning": "Founders let customer demand set compliance priorities.", "commonMistake": "Picking a proof that no buyer asked for.", "mentalModel": "Let buyers set the priority."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks the difference between NIST CSF, ISO 27001 and SOC 2.", "prompt": "What's the short version?", "options": ["Three laws every company must follow", "A guide, a certificate, and an audit report", "Three different names for the same exact thing"], "correctIndex": 1, "consequences": ["They are voluntary or market driven.", "That is how the lesson split them.", "They are different proofs."], "explanation": "NIST CSF guides, ISO 27001 certifies, and SOC 2 reports an audit."}, "proReasoning": "Ask what kind of proof each one is.", "commonMistake": "Lumping them together.", "mentalModel": "Guide, certificate, audit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8408ab9345a1$ml$]::text[]),
($ml$2de22e5c-d5a3-59f3-9c82-a0071fc90cdc$ml$::uuid, $ml$cybersecurity$ml$, 14, 1, $ml${"id": "cybersecurity-d14-c1", "title": "Drata's $200 million round", "lessonTitle": "Why startups pay for SOC 2", "slot": 1, "type": "apply", "brief": {"headline": "In December 2022, Drata raised $200 million at a $2 billion valuation, about two and a half years after it was founded. Its core product automates SOC 2.", "kicker": "Apply the idea: compliance is a business because buyers demand proof.", "fullText": "Drata was founded in mid-2020 to automate compliance work. Its core product helps companies get SOC 2 ready, and it added GDPR support in March 2022. Customers included Notion and Lemonade.\n\nOn December 7, 2022, Drata raised a $200 million Series C at a $2 billion valuation, co-led by Iconiq Growth and GGV. Investors were betting that the demand for proof in sales would keep growing.", "sources": [{"url": "https://techcrunch.com/2022/12/07/security-compliance-and-automation-platform-drata-nabs-200m-at-2b-valuation", "label": "TechCrunch, Drata raises $200M at a $2B valuation"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Drata's story in order.", "steps": ["Drata is founded in mid-2020", "It builds its product around SOC 2", "It adds GDPR support in March 2022", "It raises $200 million at $2 billion in December 2022"], "explanation": "A SOC 2 product came first, then expansion, then a large round."}, "numbers": {"kind": "numberSense", "prompt": "At what valuation did Drata raise its Series C, in billions of dollars?", "min": 0, "max": 5, "value": 2, "unit": "B", "explanation": "$2 billion, in December 2022."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a compliance software company. They ask why the market exists.", "prompt": "What do you say?", "options": ["Buyers demand proof before they sign deals", "Laws force every startup to buy software", "Audits are a fun team activity"], "correctIndex": 0, "consequences": ["That demand is what Drata sells into.", "SOC 2 is driven by buyers, not law.", "They are costly work."], "explanation": "Business buyers ask vendors for proof. Automating that proof saves time and wins deals."}, "proReasoning": "Strong candidates explain who creates the demand.", "commonMistake": "Assuming compliance is mainly legal.", "mentalModel": "Name who creates the demand."}, "invest": {"call": {"kind": "theCall", "situation": "You are comparing compliance automation companies.", "prompt": "What does Drata's round suggest?", "options": ["SOC 2 had been banned", "Investors saw lasting demand for audit proof", "Compliance software was shrinking fast"], "correctIndex": 1, "consequences": ["SOC 2 is in wide use.", "$200 million at $2 billion in 2022.", "The round shows the opposite."], "explanation": "A large round signals investors expect buyers to keep demanding proof."}, "proReasoning": "Investors read funding rounds as a view on demand.", "commonMistake": "Ignoring the demand driver behind a round.", "mentalModel": "Read what a round bets on."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to software firms that need SOC 2.", "prompt": "Which Drata detail fits your plan?", "options": ["It started with every framework at once", "It never added any new framework", "It started with SOC 2, then expanded"], "correctIndex": 2, "consequences": ["It began with SOC 2.", "It added GDPR in 2022.", "A focused start, then GDPR."], "explanation": "Starting with one demanded proof, then adding others, is a path you can follow."}, "proReasoning": "Founders start narrow where demand is clearest.", "commonMistake": "Trying to cover every framework on day one.", "mentalModel": "Start narrow, then expand."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a compliance startup could be worth $2 billion.", "prompt": "What's a good answer?", "options": ["Companies need proof of security to win deals", "Compliance software makes computers faster", "Governments buy all of it"], "correctIndex": 0, "consequences": ["That is the demand Drata serves.", "It automates audits, not speed.", "Businesses are the buyers."], "explanation": "Proof of security wins sales. Software that speeds it up is valuable."}, "proReasoning": "Ask what the product helps customers win.", "commonMistake": "Assuming compliance is a cost with no upside.", "mentalModel": "Proof wins sales."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:38b95e74dae8$ml$]::text[]),
($ml$0a96c2c7-508d-53d3-aad0-e2ba707d20b4$ml$::uuid, $ml$cybersecurity$ml$, 14, 2, $ml${"id": "cybersecurity-d14-c2", "title": "From audit type to platform", "lessonTitle": "Why startups pay for SOC 2", "slot": 2, "type": "connect", "brief": {"headline": "A SOC 2 Type II tests how controls work over time. In July 2024, Vanta, which automates that work, raised $150 million at a $2.45 billion valuation.", "kicker": "Connect day 13 and day 14: audits over time need proof over time.", "fullText": "Day 13 showed that a SOC 2 Type II tests how controls operate over a period, not just their design. That means collecting evidence for months.\n\nDay 14 showed a business built on that. Vanta collects proof from a company's systems so audits take less manual work. In July 2024 it raised $150 million at a $2.45 billion valuation, up from $1.6 billion in 2022, and had more than 8,000 customers.", "sources": [{"url": "https://cpl.thalesgroup.com/insights/cybersecurity/what-is-soc-2-compliance", "label": "Thales, what is SOC 2 compliance"}, {"url": "https://techcrunch.com/2024/07/24/trust-management-platform-vanta-raises-150m-series-c-now-valued-at-2-45b", "label": "TechCrunch, Vanta raises $150M at $2.45B"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Vanta had more than 8,000 customers.", "A Type II checks design only, at one moment.", "Vanta was valued at $2.45 billion in 2024."], "fakeIndex": 1, "explanation": "Type I checks design; Type II tests controls over a period."}, "numbers": {"kind": "numberSense", "prompt": "By about what percent did Vanta's value rise from 2022 to 2024?", "min": 0, "max": 80, "value": 53, "unit": "%", "explanation": "$2.45 billion is about 53% more than $1.6 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why a Type II audit is hard without automation.", "prompt": "What is the best answer?", "options": ["It requires no real evidence at all", "It needs evidence collected over months", "It takes only one afternoon"], "correctIndex": 1, "consequences": ["Evidence is the whole point.", "Proof over time is a lot of manual work.", "It covers a period."], "explanation": "Testing over time means gathering evidence continuously. That is what platforms automate."}, "proReasoning": "Strong candidates link the audit type to the work it creates.", "commonMistake": "Thinking an audit is a one-day event.", "mentalModel": "Link the audit to the work."}, "invest": {"call": {"kind": "theCall", "situation": "You are judging Vanta's business.", "prompt": "What drives its recurring revenue?", "options": ["Customers buy it once and never return", "Audits are only needed at founding", "Proof must be collected again every year"], "correctIndex": 2, "consequences": ["Proof is ongoing.", "Buyers keep asking.", "Type II covers a period, then repeats."], "explanation": "Audits repeat, so the need for proof recurs."}, "proReasoning": "Investors like needs that come back every year.", "commonMistake": "Missing what makes revenue recur.", "mentalModel": "Find what makes revenue recur."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup competes with Vanta for small software firms.", "prompt": "Which angle is most realistic?", "options": ["Serve a niche Vanta covers less well", "Promise audits are no longer needed", "Match Vanta's 8,000 customers at once"], "correctIndex": 0, "consequences": ["A focused niche is winnable.", "Buyers still require them.", "Unrealistic at the start."], "explanation": "Against a large player, a focused niche beats a head-on fight."}, "proReasoning": "Founders pick a corner the leader underserves.", "commonMistake": "Attacking the leader head-on with no edge.", "mentalModel": "Win a corner first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why companies pay for software just to pass audits.", "prompt": "What's a good answer?", "options": ["Audits are illegal without it", "It saves months of collecting proof by hand", "The software takes the audit for them"], "correctIndex": 1, "consequences": ["Audits do not require software.", "Type II needs proof over time.", "A CPA still does the audit."], "explanation": "Collecting proof over time is tedious. Software does much of it automatically."}, "proReasoning": "Ask what work the software replaces.", "commonMistake": "Thinking the software is the audit.", "mentalModel": "It replaces manual proof gathering."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5c66e1ba7473$ml$]::text[]),
($ml$18e708a6-1ce3-55cc-b3f9-704c3ddbf952$ml$::uuid, $ml$cybersecurity$ml$, 14, 3, $ml${"id": "cybersecurity-d14-c3", "title": "The bank wants a SOC 2", "lessonTitle": "Why startups pay for SOC 2", "slot": 3, "type": "decide", "brief": {"headline": "Your startup is close to a deal with a large bank. Its security team asks for a SOC 2 report you do not have. Vanta, which helps firms answer that ask, had more than 8,000 customers.", "kicker": "Decide: what do you offer the bank today?", "fullText": "You run a startup close to signing a large bank. The bank's security team asks for your SOC 2 report, and you do not have one.\n\nDay 14 showed why buyers ask. Business buyers want to know a vendor can be trusted with their data, and audits are how vendors answer. Vanta, which automates SOC 2 and ISO 27001 work, had more than 8,000 customers in 2024. Its CEO said earning credit for security work really means revenue.", "sources": [{"url": "https://techcrunch.com/2024/07/24/trust-management-platform-vanta-raises-150m-series-c-now-valued-at-2-45b", "label": "TechCrunch, Vanta raises $150M at $2.45B"}]}, "evidence": {"kind": "faceOff", "prompt": "Which answer keeps the deal alive best?", "left": {"name": "Start an audit and share the plan", "note": "Real evidence, with a date"}, "right": {"name": "Promise you are secure", "note": "No evidence, just assurance"}, "correctIndex": 0, "explanation": "Buyers want evidence. A real audit underway beats assurances."}, "numbers": {"kind": "numberSense", "prompt": "How many customers did Vanta have in 2024, in thousands?", "min": 0, "max": 20, "value": 8, "unit": "K", "explanation": "More than 8,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how you'd answer a buyer asking for SOC 2.", "prompt": "What do you suggest?", "options": ["Say SOC 2 does not matter for a firm like yours", "Send a long essay on your values", "Start the audit and share progress and dates"], "correctIndex": 2, "consequences": ["The buyer decided it matters.", "Values are not evidence.", "Evidence moves security reviews forward."], "explanation": "Buyers want proof. A real audit with dates is the strongest answer you can give now."}, "proReasoning": "Strong candidates respond with evidence, not assurances.", "commonMistake": "Arguing with the buyer's requirement.", "mentalModel": "Answer with evidence."}, "invest": {"call": {"kind": "theCall", "situation": "A startup you might back keeps losing large deals at the security review.", "prompt": "What fix should you look for?", "options": ["A plan to get audited soon", "A bigger sales team alone", "Lower prices for every buyer"], "correctIndex": 0, "consequences": ["Reviews stall without proof.", "Sales cannot replace proof.", "Price does not answer security."], "explanation": "If deals stall at security review, the missing piece is proof."}, "proReasoning": "Investors find the real blocker in a sales funnel.", "commonMistake": "Treating a proof gap as a sales gap.", "mentalModel": "Find the real blocker."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the startup. The bank deal is worth more than an audit costs.", "prompt": "What do you do?", "options": ["Buy a fake report from a stranger", "Start the SOC 2 now and tell the bank the timeline", "Skip the bank and hope other buyers never ask"], "correctIndex": 1, "consequences": ["Dishonest and could end the company.", "Evidence plus a date keeps the deal alive.", "Large buyers often ask the same thing."], "explanation": "If one deal pays for the audit, start it now. Other buyers will ask too."}, "proReasoning": "Founders invest in what opens a whole class of customers.", "commonMistake": "Hoping the requirement goes away.", "mentalModel": "Invest in what opens a market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a bank would refuse a startup without a SOC 2.", "prompt": "What's the answer?", "options": ["Banks dislike all startups", "SOC 2 is a law that every company must follow", "It needs proof the vendor can protect its data"], "correctIndex": 2, "consequences": ["Banks buy from startups that prove trust.", "It is driven by buyers.", "Audits are how vendors answer that question."], "explanation": "Banks handle sensitive data. They want independent proof before sharing it."}, "proReasoning": "Ask what the buyer is risking.", "commonMistake": "Taking the refusal personally.", "mentalModel": "Buyers want independent proof."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0bc09d1da2f4$ml$]::text[]),
($ml$4a6d9b6a-851c-59a7-9849-59cc358b244b$ml$::uuid, $ml$cybersecurity$ml$, 15, 1, $ml${"id": "cybersecurity-d15-c1", "title": "The first 20x approvals", "lessonTitle": "The gatekeeper of federal cloud", "slot": 1, "type": "apply", "brief": {"headline": "FedRAMP granted its first 20x Low pilot authorizations in July 2025, under four months after launching the program. Vanta was among the first four.", "kicker": "Apply the idea: the gatekeeper is trying to open faster.", "fullText": "FedRAMP launched 20x in March 2025 to speed up cloud approvals using automation. In July 2025 it announced its first 20x Low pilot authorizations, under four months after launch.\n\nThe first four were Flock Safety, Infusion Points, Meridian Knowledge Solutions and Vanta. FedRAMP said it had about a dozen formal submissions, and agency review typically took under five weeks.", "sources": [{"url": "https://www.fedramp.gov/2025-07-30-fedramp-20x-four-months-in-and-authorizing/", "label": "FedRAMP, 20x four months in and authorizing"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which company was among the first 20x Low pilot authorizations?", "options": ["Snowflake", "Vanta", "Drata"], "correctIndex": 1, "explanation": "The first four were Flock Safety, Infusion Points, Meridian Knowledge Solutions and Vanta."}, "numbers": {"kind": "numberSense", "prompt": "About how many weeks did agency review typically take for 20x submissions?", "min": 0, "max": 20, "value": 5, "unit": "weeks", "explanation": "Typically under five weeks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a cloud company that sells to government. They ask about 20x.", "prompt": "What is the key point?", "options": ["It applies only to hardware", "It uses automation to speed approvals", "It removes the need for any review"], "correctIndex": 1, "consequences": ["It is for cloud services.", "First approvals came within four months.", "Review still happens."], "explanation": "20x keeps the bar but tries to clear more services, faster, with automation."}, "proReasoning": "Strong candidates explain what changed and what stayed.", "commonMistake": "Thinking faster means no review.", "mentalModel": "Faster, but still reviewed."}, "invest": {"call": {"kind": "theCall", "situation": "You follow a cloud startup aiming at federal customers.", "prompt": "Why does 20x matter to its outlook?", "options": ["It bans startups from all federal cloud work", "It makes FedRAMP optional", "Faster approval can mean faster federal sales"], "correctIndex": 2, "consequences": ["Startups were among the first.", "The bar still applies.", "Under five weeks of agency review."], "explanation": "A faster path through the gatekeeper can shorten the time to federal revenue."}, "proReasoning": "Investors watch for changes that shorten sales cycles.", "commonMistake": "Ignoring how approval speed affects revenue.", "mentalModel": "Watch the approval clock."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells cloud software and wants federal customers.", "prompt": "What does the first 20x round suggest?", "options": ["Smaller firms can get through, and quickly", "Only huge firms are ever approved by it", "The program has stopped approving"], "correctIndex": 0, "consequences": ["Several smaller firms were among the first four.", "Not in this round.", "It just started approving."], "explanation": "The first approvals included smaller companies, under four months from launch."}, "proReasoning": "Founders look for new paths into hard markets.", "commonMistake": "Assuming the old slow path is the only one.", "mentalModel": "Look for the new path in."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why it matters that FedRAMP approved some companies quickly.", "prompt": "What's a good answer?", "options": ["Companies no longer need security controls", "Agencies can adopt new cloud tools sooner", "Agencies stop checking security"], "correctIndex": 1, "consequences": ["They still must meet the bar.", "Faster approval, same bar.", "Review still happens."], "explanation": "Faster approvals let agencies use newer tools without dropping the security check."}, "proReasoning": "Ask what the speed changes and what it keeps.", "commonMistake": "Assuming speed means lower standards.", "mentalModel": "Speed without dropping the bar."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:78a9da4bd4a3$ml$]::text[]),
($ml$c9ad2b97-1ed2-57f8-a497-7856311012d4$ml$::uuid, $ml$cybersecurity$ml$, 15, 2, $ml${"id": "cybersecurity-d15-c2", "title": "Proof for business, proof for government", "lessonTitle": "The gatekeeper of federal cloud", "slot": 2, "type": "connect", "brief": {"headline": "Vanta grew by helping firms prove security to business buyers. In March 2026, FedRAMP listed 502 authorized cloud services for federal agencies, with 75 more in progress.", "kicker": "Connect day 14 and day 15: each market has its own gatekeeper.", "fullText": "Day 14 showed that business buyers ask vendors for proof, often a SOC 2 report. Vanta built a $2.45 billion company helping firms produce it.\n\nDay 15 showed the federal version. FedRAMP, run by the General Services Administration, gives agencies one standard way to assess and authorize cloud products. In March 2026, its marketplace listed 502 authorized services, with 75 more in progress. Selling to agencies means clearing FedRAMP.", "sources": [{"url": "https://techcrunch.com/2024/07/24/trust-management-platform-vanta-raises-150m-series-c-now-valued-at-2-45b", "label": "TechCrunch, Vanta raises $150M at $2.45B"}, {"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which gatekeeper fits each buyer?", "buckets": ["SOC 2 report", "FedRAMP authorization"], "items": [{"text": "A large bank reviewing a software vendor", "bucket": 0}, {"text": "A retailer checking a payments startup", "bucket": 0}, {"text": "A federal agency buying a cloud service", "bucket": 1}, {"text": "A US department moving email to the cloud", "bucket": 1}], "explanation": "Business buyers often ask for SOC 2; federal agencies rely on FedRAMP for cloud."}, "numbers": {"kind": "numberSense", "prompt": "How many cloud services did FedRAMP list as authorized in March 2026?", "min": 0, "max": 800, "value": 502, "unit": "", "explanation": "502, with 75 more in progress."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how security proof differs by customer.", "prompt": "What is the best answer?", "options": ["Every buyer, public or private, accepts the same proof", "Government buyers need no proof", "Business buyers ask for audits; agencies require FedRAMP"], "correctIndex": 2, "consequences": ["They differ.", "FedRAMP sets the bar for agencies.", "Each market has its own gatekeeper."], "explanation": "Knowing which proof each buyer trusts shapes the whole sales plan."}, "proReasoning": "Strong candidates match the proof to the market.", "commonMistake": "Assuming one proof opens every door.", "mentalModel": "Match proof to market."}, "invest": {"call": {"kind": "theCall", "situation": "A cloud company you hold has SOC 2 but no FedRAMP authorization.", "prompt": "What does that limit?", "options": ["Its ability to sell cloud services to agencies", "Its ability to sell to any business buyer at all", "Nothing at all"], "correctIndex": 0, "consequences": ["Agencies rely on FedRAMP.", "SOC 2 serves business buyers.", "It limits federal sales."], "explanation": "Without FedRAMP, the federal cloud market stays largely closed."}, "proReasoning": "Investors check which markets a company can actually sell into.", "commonMistake": "Assuming SOC 2 covers government.", "mentalModel": "Check which doors are open."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has SOC 2 and wants to add federal customers.", "prompt": "What is the next proof to plan for?", "options": ["A new logo for the website", "FedRAMP authorization", "A second SOC 2 from the same year"], "correctIndex": 1, "consequences": ["It does not count as proof.", "Agencies rely on it for cloud.", "It does not open federal doors."], "explanation": "Each market has its own gate. For agencies buying cloud, it is FedRAMP."}, "proReasoning": "Founders plan proof market by market.", "commonMistake": "Collecting proofs no target buyer asked for.", "mentalModel": "Plan proof by market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why selling to the government is different from selling to companies.", "prompt": "What's a good answer?", "options": ["The government buys nothing online, ever", "Agencies never check vendors", "Agencies use one standard for cloud security"], "correctIndex": 2, "consequences": ["502 cloud services are authorized.", "FedRAMP is the check.", "FedRAMP is that standard."], "explanation": "Agencies rely on FedRAMP instead of each one running its own review."}, "proReasoning": "Ask who sets the bar for each buyer.", "commonMistake": "Assuming all buyers check the same way.", "mentalModel": "Each buyer has a gatekeeper."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8d28cfec54ab$ml$]::text[]),
($ml$49d092b9-7d08-5f1e-964a-26091efc18e4$ml$::uuid, $ml$cybersecurity$ml$, 15, 3, $ml${"id": "cybersecurity-d15-c3", "title": "Chasing a federal contract", "lessonTitle": "The gatekeeper of federal cloud", "slot": 3, "type": "decide", "brief": {"headline": "You run a cloud startup with a pilot at a federal agency. To grow, you need FedRAMP. The marketplace lists 502 authorized services, and 20x aims to speed approvals.", "kicker": "Decide: how do you approach the gatekeeper?", "fullText": "You run a cloud software startup with an interested federal agency. To sell widely to agencies, you need FedRAMP authorization.\n\nDay 15 set the scene. FedRAMP gives agencies one standard way to assess and authorize cloud products. In March 2026 it listed 502 authorized services, with 75 more in progress. FedRAMP 20x, launched in March 2025, leans on automation to speed approvals, with the goal of thousands of authorized services.", "sources": [{"url": "https://www.meritalk.com/articles/fedramp-hits-500-authorized-cloud-services/", "label": "MeriTalk, FedRAMP hits 500 authorized cloud services"}]}, "evidence": {"kind": "faceOff", "prompt": "Who holds more power in this sale?", "left": {"name": "Your startup", "note": "Has a product an agency wants"}, "right": {"name": "FedRAMP", "note": "Sets the bar agencies rely on"}, "correctIndex": 1, "explanation": "FedRAMP sets the bar agencies rely on. The startup has to clear it."}, "numbers": {"kind": "numberSense", "prompt": "How many more services were in progress in March 2026?", "min": 0, "max": 200, "value": 75, "unit": "", "explanation": "75, on top of 502 authorized."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how a startup should approach FedRAMP.", "prompt": "What do you recommend?", "options": ["Plan for it early and use the faster 20x path", "Ignore it and sell directly to agencies", "Wait until agencies drop the requirement"], "correctIndex": 0, "consequences": ["It is the gate, and 20x aims to speed it.", "Agencies rely on FedRAMP.", "The program is growing."], "explanation": "FedRAMP is the gate. Planning early and using faster paths shortens the wait."}, "proReasoning": "Strong candidates treat the gatekeeper as part of the plan.", "commonMistake": "Hoping to route around the gatekeeper.", "mentalModel": "Plan for the gate."}, "invest": {"call": {"kind": "theCall", "situation": "A startup you might back says federal sales are its main growth plan.", "prompt": "What should you ask?", "options": ["Whether it has a mascot and a catchy slogan", "Where it stands on FedRAMP authorization", "How many offices it has"], "correctIndex": 1, "consequences": ["Irrelevant.", "That sets when federal revenue can start.", "Offices do not open federal doors."], "explanation": "For a federal cloud plan, FedRAMP status is the key milestone."}, "proReasoning": "Investors ask about the gate before the forecast.", "commonMistake": "Taking a federal forecast at face value.", "mentalModel": "Ask about the gate first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the startup. Your pilot agency loves the product.", "prompt": "What is your next step?", "options": ["Assume one fan replaces authorization", "Sell the same pilot price forever", "Pursue FedRAMP so more agencies can buy"], "correctIndex": 2, "consequences": ["Agencies rely on FedRAMP.", "Pricing is not the blocker.", "Authorization opens the wider market."], "explanation": "One agency's interest is a start. Authorization lets the rest buy."}, "proReasoning": "Founders turn a single win into a repeatable channel.", "commonMistake": "Mistaking one fan for a market.", "mentalModel": "Turn one win into a channel."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a great cloud product cannot just sell to every agency.", "prompt": "What's the answer?", "options": ["Agencies rely on FedRAMP to judge cloud security", "Agencies only buy hardware", "Cloud products are banned in all of government"], "correctIndex": 0, "consequences": ["It is the shared standard.", "They buy cloud too.", "502 services are authorized."], "explanation": "FedRAMP sets one bar for the whole government. Products clear it first."}, "proReasoning": "Ask who decides what buyers may use.", "commonMistake": "Assuming a good product sells itself.", "mentalModel": "Clear the gate first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8ef2eddf39cd$ml$]::text[]),
($ml$a10c7401-c56c-51c3-abbc-9f1ee369508a$ml$::uuid, $ml$cybersecurity$ml$, 16, 1, $ml${"id": "cybersecurity-d16-c1", "title": "A university settles for $1.25M", "lessonTitle": "110 controls to keep defense work", "slot": 1, "type": "apply", "brief": {"headline": "In October 2024, Penn State agreed to pay $1.25 million to settle claims that it misstated its security compliance on 15 defense contracts. A former insider raised the alarm.", "kicker": "Apply the idea: claiming the controls is not the same as having them.", "fullText": "Penn State held defense contracts that required it to protect sensitive government information. On October 22, 2024, it agreed to pay $1.25 million under the False Claims Act to settle allegations covering 15 contracts and subcontracts.\n\nThe government alleged Penn State misstated when it would put the required controls in place, against an expected score of 110, did not document its plan properly, and used a cloud provider that was not FedRAMP authorized. The case began with a whistleblower: the former chief information officer of its Applied Research Laboratory, who filed in October 2022.", "sources": [{"url": "https://www.crowell.com/en/insights/client-alerts/allegations-of-a-litany-of-lyin-penn-state-settles-claims-of-cybersecurity-noncompliance", "label": "Crowell & Moring, Penn State settles cybersecurity claims"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each allegation by what went wrong.", "buckets": ["What it claimed", "What it used"], "items": [{"text": "Misstated when required controls would be in place", "bucket": 0}, {"text": "Did not properly document its plan to meet them", "bucket": 0}, {"text": "Stored data with a cloud provider lacking FedRAMP", "bucket": 1}], "explanation": "Some claims did not match its progress, and one tool did not meet the federal cloud bar."}, "numbers": {"kind": "numberSense", "prompt": "How many defense contracts and subcontracts did the settlement cover?", "min": 0, "max": 40, "value": 15, "unit": "", "explanation": "15 contracts and subcontracts, settled for $1.25 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a defense contractor. They ask what the Penn State case teaches.", "prompt": "Which lesson do you lead with?", "options": ["Universities never have to follow defense rules", "Only Level 3 contractors face any enforcement", "Report your real progress on controls, not a goal"], "correctIndex": 2, "consequences": ["Penn State held defense contracts.", "This was about the 110 control standard.", "Misstated dates were at the heart of the case."], "explanation": "The case turned on claims that did not match reality. Honest reporting is the protection."}, "proReasoning": "Strong candidates know that a false compliance claim is its own risk.", "commonMistake": "Thinking compliance is about paperwork, not truth.", "mentalModel": "Make claims match reality."}, "invest": {"call": {"kind": "theCall", "situation": "A defense supplier you hold says it fully meets its security requirements.", "prompt": "What does Penn State suggest you ask?", "options": ["How it checks that the claim is accurate", "Whether it has ever been to Pennsylvania", "Whether its logo appears on its contracts"], "correctIndex": 0, "consequences": ["False claims led to a settlement here.", "Location does not matter.", "Branding does not matter."], "explanation": "A compliance claim that is wrong can become a legal problem, not just a security gap."}, "proReasoning": "Investors ask how claims are verified, especially when a whistleblower could challenge them.", "commonMistake": "Taking a compliance claim at face value.", "mentalModel": "Ask how claims are verified."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps contractors track progress on the 110 controls.", "prompt": "Which Penn State detail supports your pitch?", "options": ["Its contracts were all with NASA", "Its plan was not properly documented", "It had too many students on campus"], "correctIndex": 1, "consequences": ["They were defense contracts.", "Tracking and documenting progress is your product.", "Students were not the issue."], "explanation": "Missing documentation was part of the allegations. Tracking and recording progress fills that gap."}, "proReasoning": "Founders point to the specific failure their product prevents.", "commonMistake": "Pitching with general fear of fines.", "mentalModel": "Point to the specific failure."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a university got in trouble over cybersecurity.", "prompt": "What's the simple answer?", "options": ["Its students hacked into the Pentagon one night", "It refused to use any computers at all", "It was accused of misstating its security progress"], "correctIndex": 2, "consequences": ["The case was about compliance claims.", "It used computers and a cloud provider.", "The claims covered 15 defense contracts."], "explanation": "Defense contracts require security controls. Claiming progress that was not real led to the settlement."}, "proReasoning": "Ask whether what was claimed matched what was done.", "commonMistake": "Thinking only hacks cause cyber trouble.", "mentalModel": "False claims are a risk too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1898ada9c559$ml$]::text[]),
($ml$de3ca45d-966a-53f9-b129-6211118fa97a$ml$::uuid, $ml$cybersecurity$ml$, 16, 2, $ml${"id": "cybersecurity-d16-c2", "title": "From optional proof to required proof", "lessonTitle": "110 controls to keep defense work", "slot": 2, "type": "connect", "brief": {"headline": "SOC 2 spread because business buyers asked for it, and Vanta had 8,000+ customers. CMMC is different: the Pentagon requires it of more than 337,000 contractors.", "kicker": "Connect day 14 and day 16: when the buyer is the government, proof becomes a rule.", "fullText": "Day 14 showed proof driven by buyers. Business customers ask vendors for SOC 2 reports, and Vanta grew to more than 8,000 customers helping firms produce them.\n\nDay 16 showed proof written into contracts. The Pentagon's final CMMC rule, published in September 2025, sets Level 1 at 15 requirements, Level 2 at 110 and Level 3 at 24 more. Requirements phase in from November 2025 and apply to all relevant contracts from November 10, 2028. DoD estimates more than 337,000 contractors and subcontractors are affected.", "sources": [{"url": "https://techcrunch.com/2024/07/24/trust-management-platform-vanta-raises-150m-series-c-now-valued-at-2-45b", "label": "TechCrunch, Vanta raises $150M at $2.45B"}, {"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, "evidence": {"kind": "faceOff", "prompt": "Which is required by contract rather than asked for by buyers?", "left": {"name": "SOC 2 report", "note": "Requested by business customers"}, "right": {"name": "CMMC Level 2", "note": "Written into defense contracts"}, "correctIndex": 1, "explanation": "CMMC is a Pentagon requirement; SOC 2 spreads because buyers ask for it."}, "numbers": {"kind": "numberSense", "prompt": "About how many contractors and subcontractors does DoD say CMMC affects, in thousands?", "min": 0, "max": 500, "value": 337, "unit": "K", "explanation": "More than 337,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how CMMC differs from SOC 2.", "prompt": "What is the best answer?", "options": ["CMMC is a contract rule; SOC 2 is buyer driven", "They are exactly the same proof with new names", "SOC 2 is required by the Pentagon"], "correctIndex": 0, "consequences": ["Different drivers, different stakes.", "They differ in who requires them.", "CMMC is the Pentagon rule."], "explanation": "Knowing who requires a proof tells you what happens if you lack it."}, "proReasoning": "Strong candidates separate market pressure from legal requirement.", "commonMistake": "Treating all compliance as the same.", "mentalModel": "Ask who requires the proof."}, "invest": {"call": {"kind": "theCall", "situation": "A compliance software company you follow wants to enter defense.", "prompt": "Why might CMMC be a large market?", "options": ["It applies only to the largest primes", "More than 337,000 firms must meet it", "Only a few hundred firms are affected"], "correctIndex": 1, "consequences": ["Small firms face the same rules.", "DoD's own estimate.", "The estimate is far higher."], "explanation": "A required standard for hundreds of thousands of firms is a large, steady market."}, "proReasoning": "Investors size markets by who must buy, not who might.", "commonMistake": "Underestimating a required market.", "mentalModel": "Size by who must buy."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells SOC 2 automation and wants to add CMMC.", "prompt": "Which fact supports the move?", "options": ["CMMC was quietly cancelled by the Pentagon in 2025", "CMMC applies only outside the US", "Requirements apply to all relevant contracts by 2028"], "correctIndex": 2, "consequences": ["The final rule was published.", "It is a US defense rule.", "A deadline drives demand."], "explanation": "A firm deadline for a huge group of firms creates demand you can plan around."}, "proReasoning": "Founders expand where a deadline guarantees buyers.", "commonMistake": "Expanding into a market with no forcing event.", "mentalModel": "Expand toward the deadline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why defense suppliers must prove their security.", "prompt": "What's a good answer?", "options": ["The Pentagon writes it into their contracts", "Their customers just like reading audits", "It is optional for anyone who asks"], "correctIndex": 0, "consequences": ["That is CMMC.", "It is required, not a preference.", "It is required for relevant contracts."], "explanation": "For defense work, proof of security is a contract requirement, not a sales tool."}, "proReasoning": "Ask whether a proof is required or requested.", "commonMistake": "Thinking all security proof is voluntary.", "mentalModel": "Some proof is required."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4b536f4dc35a$ml$]::text[]),
($ml$af9f2594-af87-59d1-85fa-ea1d7df2709b$ml$::uuid, $ml$cybersecurity$ml$, 16, 3, $ml${"id": "cybersecurity-d16-c3", "title": "A small machine shop and CMMC", "lessonTitle": "110 controls to keep defense work", "slot": 3, "type": "decide", "brief": {"headline": "You run a 40-person machine shop that makes parts for a defense prime and handles controlled unclassified information. CMMC Level 2 requires 110 controls.", "kicker": "Decide: start now, or wait for 2028?", "fullText": "You run a small machine shop that makes parts for a large defense contractor. You handle controlled unclassified information, so you will need CMMC Level 2.\n\nDay 16 set the rules. Level 2 has 110 requirements. They phase in from November 2025 and apply to all relevant contracts from November 10, 2028. DoD says nearly 230,000 small businesses are among the more than 337,000 affected, and small firms face the same rules as large ones.", "sources": [{"url": "https://www.faegredrinker.com/en/insights/publications/2025/9/department-of-defense-publishes-final-rule-to-implement-and-enforce-cybersecurity-standards-for-contractors", "label": "Faegre Drinker, DoD final CMMC rule"}]}, "evidence": {"kind": "multipleChoice", "prompt": "How many requirements does CMMC Level 2 include?", "options": ["15", "24", "110"], "correctIndex": 2, "explanation": "Level 2 has 110. Level 1 has 15, and Level 3 adds 24 more."}, "numbers": {"kind": "numberSense", "prompt": "About how many small businesses are affected, in thousands?", "min": 0, "max": 400, "value": 230, "unit": "K", "explanation": "Nearly 230,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at a small supplier, you're asked how to prepare for CMMC.", "prompt": "What do you recommend?", "options": ["Assume small shops get an exemption", "Start a gap review against the 110 controls now", "Wait until November 2028 before looking at it"], "correctIndex": 1, "consequences": ["Small firms face the same rules.", "Requirements phase in from November 2025.", "Some contracts can require it sooner."], "explanation": "Phase-in has started. Knowing your gaps early leaves time to close them."}, "proReasoning": "Strong candidates plan backward from the deadline.", "commonMistake": "Treating the final date as the start date.", "mentalModel": "Plan backward from the deadline."}, "invest": {"call": {"kind": "theCall", "situation": "A small defense supplier you might back has not started on CMMC.", "prompt": "How should that affect your view?", "options": ["It has nothing to worry about until 2028", "It means it has no defense customers", "It risks losing contracts as rules phase in"], "correctIndex": 2, "consequences": ["The phase-in has begun.", "It may still have them today.", "Program offices can add it from November 2025."], "explanation": "A supplier without a plan could be locked out of contracts."}, "proReasoning": "Investors check readiness for rules that gate revenue.", "commonMistake": "Ignoring a rule that controls access to customers.", "mentalModel": "Check readiness for revenue gates."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the shop. Your prime asks when you will be ready.", "prompt": "What do you tell them?", "options": ["Share a dated plan against the 110 controls", "Promise you are already fully compliant", "Say small shops should not be asked"], "correctIndex": 0, "consequences": ["An honest, dated plan builds trust.", "Penn State shows the risk of false claims.", "Small firms face the same rules."], "explanation": "Primes need suppliers who will be ready. A real plan with dates keeps the relationship."}, "proReasoning": "Founders answer customer risk with evidence and dates.", "commonMistake": "Overclaiming readiness to calm a customer.", "mentalModel": "Answer with a dated plan."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend runs a tiny parts shop and thinks CMMC is only for big defense firms.", "prompt": "What would you tell them?", "options": ["CMMC applies only to software companies", "Small firms face the same rules as large ones", "Only firms with 10,000 staff are covered"], "correctIndex": 1, "consequences": ["It covers contractors handling the data.", "Nearly 230,000 small businesses are affected.", "Size does not exempt you."], "explanation": "If you handle the covered data, the rules apply regardless of size."}, "proReasoning": "Ask what data you handle, not how big you are.", "commonMistake": "Assuming size sets the rules.", "mentalModel": "Data, not size, sets the rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:08c5edff8248$ml$]::text[]),
($ml$042aad33-a1e8-553a-802c-d5516d0dd3ba$ml$::uuid, $ml$cybersecurity$ml$, 17, 1, $ml${"id": "cybersecurity-d17-c1", "title": "Brussels chases 23 countries", "lessonTitle": "Europe's 24-hour rule", "slot": 1, "type": "apply", "brief": {"headline": "NIS2 had to be written into national law by October 17, 2024. On November 28, the European Commission sent formal notices to 23 member states that had not fully done so.", "kicker": "Apply the idea: an EU rule only bites once each country adopts it.", "fullText": "NIS2 is an EU directive, which means each member state must write it into its own national law. The deadline was October 17, 2024.\n\nOn November 28, 2024, the European Commission sent letters of formal notice to 23 member states for failing to fully do so. They had two months to respond, after which the Commission could issue a reasoned opinion, the next step in the EU's infringement process.", "sources": [{"url": "https://digital-strategy.ec.europa.eu/en/news/commission-calls-23-member-states-fully-transpose-nis2-directive", "label": "European Commission, 23 member states called to transpose NIS2"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the NIS2 steps in order.", "steps": ["The EU adopts the NIS2 directive", "Member states must write it into law by October 17, 2024", "The Commission notifies 23 states on November 28, 2024", "States have two months to respond"], "explanation": "A directive needs national laws; the Commission chases states that are late."}, "numbers": {"kind": "numberSense", "prompt": "How many member states received formal notices?", "min": 0, "max": 27, "value": 23, "unit": "", "explanation": "23 of the EU's 27 member states."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an EU company. They ask why NIS2 rules differ by country.", "prompt": "What is the best answer?", "options": ["Each state writes the directive into its own law", "The EU wrote one identical law for all states", "NIS2 applies only in Brussels itself"], "correctIndex": 0, "consequences": ["That is how directives work.", "A directive needs national laws.", "It applies across member states."], "explanation": "A directive sets goals; each country writes its own law. Timing and details can differ."}, "proReasoning": "Strong candidates know how EU directives become national law.", "commonMistake": "Assuming one text applies everywhere on the same day.", "mentalModel": "Directives need national laws."}, "invest": {"call": {"kind": "theCall", "situation": "A European company you hold operates in several EU states.", "prompt": "What does the late transposition mean for it?", "options": ["Every state applied it on one day", "Rules and timing may differ by country", "It can ignore NIS2 entirely forever"], "correctIndex": 1, "consequences": ["They did not.", "23 states were behind in late 2024.", "The Commission is pushing states to act."], "explanation": "A multi-country firm may face a patchwork of national rules for a while."}, "proReasoning": "Investors watch for uneven rules that raise compliance costs.", "commonMistake": "Assuming a directive applies uniformly at once.", "mentalModel": "Watch for patchworks."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps EU firms track NIS2 rules country by country.", "prompt": "Which fact supports your product?", "options": ["Every member state adopted it early, ahead of time", "NIS2 was repealed in 2024", "23 states had not fully adopted it on time"], "correctIndex": 2, "consequences": ["Most were late.", "The Commission is enforcing it.", "A patchwork needs tracking."], "explanation": "Uneven adoption across 27 countries creates a tracking problem firms will pay to solve."}, "proReasoning": "Founders turn regulatory messiness into a product.", "commonMistake": "Assuming rules are simple and uniform.", "mentalModel": "Sell clarity in a patchwork."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the EU is chasing its own members over a cyber law.", "prompt": "What's the answer?", "options": ["Most states missed the deadline to adopt it", "The states all asked to be fined", "NIS2 is a law only for the Commission"], "correctIndex": 0, "consequences": ["23 were notified.", "Notices follow missed deadlines.", "It applies to companies in each state."], "explanation": "A directive only works once each country turns it into law. The Commission enforces that."}, "proReasoning": "Ask who must act for a rule to take effect.", "commonMistake": "Thinking an EU rule applies automatically.", "mentalModel": "Directives need national action."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f72e020413f7$ml$]::text[]),
($ml$76489e44-8676-556e-a035-8c2f831be330$ml$::uuid, $ml$cybersecurity$ml$, 17, 2, $ml${"id": "cybersecurity-d17-c2", "title": "Three clocks, three rules", "lessonTitle": "Europe's 24-hour rule", "slot": 2, "type": "connect", "brief": {"headline": "A US public company files within four business days once it judges an attack material. GDPR gives 72 hours to report a data breach. NIS2 wants an early warning in 24.", "kicker": "Connect day 5 and day 17: each rule starts and runs its own clock.", "fullText": "Day 5 set the US clock. Under SEC rules, a public company must file a Form 8-K within four business days of deciding a cyber incident is material.\n\nDay 17 set a faster European one. Under NIS2, in force since October 2024, covered companies must send an early warning within 24 hours of a significant incident, a fuller notification within 48 hours of that warning, and a final report within a month. A company in both places may run more than one clock at once.", "sources": [{"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which clock is shortest?", "options": ["NIS2 early warning", "SEC Form 8-K filing", "NIS2 final report"], "correctIndex": 0, "explanation": "The NIS2 early warning is due within 24 hours of a significant incident."}, "numbers": {"kind": "numberSense", "prompt": "Within how many hours must a NIS2 early warning be sent?", "min": 0, "max": 72, "value": 24, "unit": "hours", "explanation": "24 hours, with a fuller notification within 48 more."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how a US company with EU operations should plan incident reporting.", "prompt": "What do you recommend?", "options": ["Report only after the full investigation", "Map each rule's trigger and deadline in advance", "Follow only the slowest deadline you face"], "correctIndex": 1, "consequences": ["NIS2 wants a warning in 24 hours.", "Different triggers, different clocks.", "The fastest rule sets the pace."], "explanation": "Each rule starts its clock differently. Mapping them ahead avoids missing one."}, "proReasoning": "Strong candidates plan for overlapping rules.", "commonMistake": "Assuming one rule covers everything.", "mentalModel": "Map every clock ahead."}, "invest": {"call": {"kind": "theCall", "situation": "A US software company you hold sells cloud services in the EU.", "prompt": "What reporting risk should you note?", "options": ["EU rules never apply to US firms", "It only ever reports to the SEC", "It may face a 24-hour EU warning rule"], "correctIndex": 2, "consequences": ["NIS2 widened scope to cloud.", "It may report in the EU too.", "NIS2 covers cloud providers."], "explanation": "Operating in the EU can bring much faster reporting duties than US rules."}, "proReasoning": "Investors check which rules apply where a company sells.", "commonMistake": "Assuming US rules are the only ones that matter.", "mentalModel": "Rules follow where you sell."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds incident reporting tools.", "prompt": "Which feature matters most for multinational buyers?", "options": ["Tracking several reporting clocks at once", "A single four-day reminder for everyone", "A form for one country only"], "correctIndex": 0, "consequences": ["Buyers face SEC, GDPR and NIS2 together.", "Some rules run far faster.", "Buyers operate in many places."], "explanation": "Overlapping rules are the hard part. A tool that runs every clock helps most."}, "proReasoning": "Founders build for the messy case buyers actually have.", "commonMistake": "Building for a single simple rule.", "mentalModel": "Handle overlapping clocks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why companies seem to report hacks at different speeds.", "prompt": "What's a good answer?", "options": ["Companies pick any deadline they like", "Different rules set different deadlines", "Every country uses the same deadline"], "correctIndex": 1, "consequences": ["Rules set them.", "24 hours, 72 hours, four business days.", "They differ."], "explanation": "Each rule has its own trigger and deadline, so timing varies by place and law."}, "proReasoning": "Ask which rule applies.", "commonMistake": "Assuming one global deadline.", "mentalModel": "Different rules, different clocks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:55b0741c52a8$ml$]::text[]),
($ml$d5212a39-79c9-5b53-9d39-19bc374c6825$ml$::uuid, $ml$cybersecurity$ml$, 17, 3, $ml${"id": "cybersecurity-d17-c3", "title": "9 a.m., facts unclear", "lessonTitle": "Europe's 24-hour rule", "slot": 3, "type": "decide", "brief": {"headline": "You run an EU cloud company covered by NIS2. At 9 a.m. you find a significant intrusion, and the facts are still unclear. An early warning is due within 24 hours.", "kicker": "Decide: wait for the facts, or warn now?", "fullText": "You run security at an EU cloud provider covered by NIS2. At 9 a.m. your team confirms a significant intrusion, but you do not know its scope yet.\n\nDay 17 set the rule. An early warning is due within 24 hours, a fuller notification within 48 hours of that, and a final report with the root cause within a month. Essential entities face fines of up to €10 million or 2% of worldwide annual turnover, whichever is greater.", "sources": [{"url": "https://wsgr.com/en/insights/nis2-preparing-for-eus-new-cybersecurity-rules.html", "label": "Wilson Sonsini, preparing for the EU's NIS2 rules"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan fits NIS2?", "left": {"name": "Warn within 24 hours, details later", "note": "Early warning, then fuller reports"}, "right": {"name": "Wait until the facts are clear", "note": "One complete report at the end"}, "correctIndex": 0, "explanation": "The early warning is designed to come fast, with details to follow."}, "numbers": {"kind": "numberSense", "prompt": "An essential entity has €2 billion in turnover. What is its maximum NIS2 fine, in millions of euros?", "min": 0, "max": 60, "value": 40, "unit": "M", "explanation": "2% of €2 billion is €40 million, more than €10 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what to do at 9 a.m. with an unclear intrusion.", "prompt": "What do you say?", "options": ["Wait for a full picture before saying anything", "Report only if customers notice it", "Send the early warning, then follow up with detail"], "correctIndex": 2, "consequences": ["The 24-hour clock does not wait.", "Reporting is required.", "That is how the NIS2 clock is built."], "explanation": "The rule expects a fast warning with what you know, then fuller reports."}, "proReasoning": "Strong candidates know that early reports can be incomplete by design.", "commonMistake": "Waiting for certainty that the rule does not require.", "mentalModel": "Warn early, fill in later."}, "invest": {"call": {"kind": "theCall", "situation": "An EU company you hold has €2 billion in turnover and is an essential entity.", "prompt": "What is its maximum NIS2 fine?", "options": ["€40 million, 2% of turnover", "€10 million, the fixed amount", "€2 million, a tenth of a percent"], "correctIndex": 0, "consequences": ["2% beats €10 million here.", "The greater of the two applies.", "The rule says 2%."], "explanation": "For large firms, the 2% figure can far exceed €10 million."}, "proReasoning": "Investors scale fines to company size.", "commonMistake": "Reading the €10 million as a cap for everyone.", "mentalModel": "Scale the fine to turnover."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the cloud provider. Your lawyer wants to wait a day for more facts.", "prompt": "What do you decide?", "options": ["Skip reporting since scope is unknown", "Send the warning now with what you know", "Wait two days until the facts are clear"], "correctIndex": 1, "consequences": ["The rule still applies.", "It meets the 24-hour clock.", "That misses the deadline."], "explanation": "The warning is meant to be early and partial. Waiting risks missing the clock."}, "proReasoning": "Founders know which rules are about speed over completeness.", "commonMistake": "Letting perfect be the enemy of on time.", "mentalModel": "Meet the clock first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company can report a hack it barely understands yet.", "prompt": "What's the answer?", "options": ["It must report every detail in an hour", "It does not need to report at all", "The first report is a short early warning"], "correctIndex": 2, "consequences": ["Details follow within 48 hours and a month.", "NIS2 requires it.", "Details come in later reports."], "explanation": "NIS2 splits reporting into stages so the first warning can be quick."}, "proReasoning": "Ask what each report must contain.", "commonMistake": "Thinking the first report must be complete.", "mentalModel": "Report in stages."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b82fde0589dd$ml$]::text[]),
($ml$be0a7624-081c-52b3-8961-fe9b82434ff8$ml$::uuid, $ml$cybersecurity$ml$, 18, 1, $ml${"id": "cybersecurity-d18-c1", "title": "A security chief convicted", "lessonTitle": "When the security chief was sued", "slot": 1, "type": "apply", "brief": {"headline": "Uber's former security chief, Joe Sullivan, was convicted in 2022 over how he handled a breach. In May 2023, he was sentenced to three years of probation.", "kicker": "Apply the idea: personal liability for security leaders is not just theory.", "fullText": "Hackers took data on 57 million Uber users and drivers. Uber paid them $100,000 to destroy it.\n\nJoe Sullivan, Uber's chief security officer at the time, was convicted in 2022 of obstructing a Federal Trade Commission proceeding and of misprision of felony, meaning concealing a crime. In May 2023, he was sentenced to three years of probation and 200 hours of community service. The case, like SolarWinds, put a security leader personally in the spotlight.", "sources": [{"url": "https://www.helpnetsecurity.com/2023/05/05/joe-sullivan-sentenced/", "label": "Help Net Security, Joe Sullivan sentenced"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Sullivan was sentenced to three years of probation.", "The hackers took data on 57 million people.", "Sullivan was sentenced to ten years in prison."], "fakeIndex": 2, "explanation": "He got three years of probation and 200 hours of community service."}, "numbers": {"kind": "numberSense", "prompt": "How many hours of community service was Sullivan sentenced to?", "min": 0, "max": 500, "value": 200, "unit": "hours", "explanation": "200 hours, plus three years of probation."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a CISO role. They ask what the Sullivan case means for the job.", "prompt": "Which answer shows judgment?", "options": ["Only CEOs are ever held responsible for breaches", "How you handle and report a breach can carry personal risk", "Security chiefs can never face personal consequences"], "correctIndex": 1, "consequences": ["A CSO was convicted here.", "He was convicted personally.", "This case shows they can."], "explanation": "Concealing a breach turned a company problem into a personal one."}, "proReasoning": "Strong candidates see disclosure as part of the job, not a choice.", "commonMistake": "Assuming the company always absorbs the risk.", "mentalModel": "Disclosure is part of the job."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold paid hackers to stay quiet about a breach years ago.", "prompt": "What risk should you note?", "options": ["No risk once the hackers were paid", "A guaranteed rise in its share price", "Legal and leadership risk if it comes out"], "correctIndex": 2, "consequences": ["Paying did not end the matter.", "Nothing supports that.", "Uber's case led to a conviction."], "explanation": "Hiding a breach can create legal exposure later, for the company and its leaders."}, "proReasoning": "Investors weigh how a company has handled past incidents.", "commonMistake": "Treating a hidden incident as closed.", "mentalModel": "Hidden incidents can resurface."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies document breach decisions as they happen.", "prompt": "Why does the Sullivan case support your pitch?", "options": ["How a breach was handled became the legal question", "The breach itself was never looked into by anyone", "Only the hackers faced any charges"], "correctIndex": 0, "consequences": ["A clear record shows what leaders knew and did.", "It was, and led to charges.", "Sullivan was convicted."], "explanation": "When handling becomes the issue, a clear record of decisions protects people acting in good faith."}, "proReasoning": "Founders build around the question regulators ask afterward.", "commonMistake": "Building for the attack and not the aftermath.", "mentalModel": "Build for the aftermath."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a security chief could be convicted over a hack he did not do.", "prompt": "What's the answer?", "options": ["He was convicted for using a weak password", "He was convicted over how he handled it", "He was found to be the hacker himself"], "correctIndex": 1, "consequences": ["The charges were about concealment.", "Obstruction and concealing a crime.", "Others did the hack."], "explanation": "The conviction was about concealing the breach, not committing it."}, "proReasoning": "Ask what someone did after the attack.", "commonMistake": "Assuming only attackers face charges.", "mentalModel": "Handling can be the crime."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3eb4342e390d$ml$]::text[]),
($ml$ac53fcf8-c37f-5b81-a961-2e3541113d40$ml$::uuid, $ml$cybersecurity$ml$, 18, 2, $ml${"id": "cybersecurity-d18-c2", "title": "Disclosure rules and the CISO", "lessonTitle": "When the security chief was sued", "slot": 2, "type": "connect", "brief": {"headline": "The SEC's new rule took effect in December 2023, requiring material attacks to be disclosed in four business days. Two months earlier, it had sued SolarWinds' security chief.", "kicker": "Connect day 5 and day 18: what companies say about security is under scrutiny.", "fullText": "Day 5 set the disclosure rule. Since December 18, 2023, US public companies must report material cyber incidents within four business days.\n\nDay 18 showed how far the SEC was willing to go. In October 2023, it sued SolarWinds and its security chief, Tim Brown, saying they hid cybersecurity weaknesses from the 2018 IPO until the Sunburst hack came to light in December 2020. A judge dismissed most claims in July 2024, and in November 2025 the SEC said it would drop the case.", "sources": [{"url": "https://sec.gov/news/press-release/2023-139", "label": "SEC press release 2023-139"}, {"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the events in order.", "steps": ["SolarWinds goes public in 2018", "The Sunburst hack comes to light in December 2020", "The SEC sues SolarWinds and its CISO in October 2023", "A judge dismisses most claims in July 2024", "The SEC says it will drop the case in November 2025"], "explanation": "IPO, hack, suit, ruling, then dismissal."}, "numbers": {"kind": "numberSense", "prompt": "How many months passed between the October 2023 suit and the July 2024 ruling?", "min": 0, "max": 24, "value": 9, "unit": "months", "explanation": "Nine months, from October 2023 to July 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what the SolarWinds case means for security leaders.", "prompt": "What is the most accurate answer?", "options": ["It settled that CISOs are always personally liable", "It proved CISOs can never be sued at all", "It raised personal liability, but ended without a ruling"], "correctIndex": 2, "consequences": ["No such ruling was made.", "The SEC did sue one.", "The SEC dropped it in November 2025."], "explanation": "The case raised the question of personal liability without answering it."}, "proReasoning": "Strong candidates describe unsettled law as unsettled.", "commonMistake": "Overstating what a dropped case decided.", "mentalModel": "Call unsettled law unsettled."}, "invest": {"call": {"kind": "theCall", "situation": "You read a company's public security statement while researching it.", "prompt": "Why does SolarWinds make that statement matter?", "options": ["Statements that do not match reality draw scrutiny", "Security statements are never read by regulators", "Only financial numbers can mislead investors"], "correctIndex": 0, "consequences": ["That was the SEC's claim.", "The SEC read this one.", "The SEC treated security claims as material."], "explanation": "Public claims about security can be judged against reality, like any other claim."}, "proReasoning": "Investors compare security claims with known incidents.", "commonMistake": "Treating security statements as marketing.", "mentalModel": "Test claims against reality."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup checks that public security claims match internal reality.", "prompt": "Which fact supports your pitch?", "options": ["Security claims cannot be checked at all", "The SEC sued over claims not matching reality", "The SEC never looks at security claims"], "correctIndex": 1, "consequences": ["Your tool checks them.", "That gap is what you close.", "It did here."], "explanation": "When regulators compare claims with reality, closing that gap has value."}, "proReasoning": "Founders target the gap regulators focus on.", "commonMistake": "Assuming nobody checks public claims.", "mentalModel": "Close the claim gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether security chiefs can be sued for what their companies say.", "prompt": "What's a fair answer?", "options": ["Yes, and they always lose", "No, it has never been tried by anyone", "The SEC tried, but dropped the case"], "correctIndex": 2, "consequences": ["Most claims were dismissed.", "The SEC sued Tim Brown.", "SolarWinds ended without a ruling."], "explanation": "It has been tried. The SolarWinds case was dropped, so the law is still unsettled."}, "proReasoning": "Ask how a case ended, not just how it began.", "commonMistake": "Treating a lawsuit as a verdict.", "mentalModel": "A suit is not a verdict."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d0dd1f7b5454$ml$]::text[]),
($ml$92a116a6-0e9c-590c-b891-78c25fb31457$ml$::uuid, $ml$cybersecurity$ml$, 18, 3, $ml${"id": "cybersecurity-d18-c3", "title": "Sign the security statement?", "lessonTitle": "When the security chief was sued", "slot": 3, "type": "decide", "brief": {"headline": "You are CISO of a public company. Marketing wants you to approve a security statement saying you follow practices you have not fully put in place.", "kicker": "Decide: what do you sign?", "fullText": "You are the chief information security officer of a US public company. Marketing has drafted a website statement saying you follow strict security practices, some of which are not fully in place.\n\nDay 18 showed the stakes. The SEC sued SolarWinds and its CISO, Tim Brown, in October 2023, saying public security statements did not match reality. Only claims about the pre-hack Security Statement survived a July 2024 ruling, and the SEC dropped the case in November 2025.", "sources": [{"url": "https://www.nextgov.com/cybersecurity/2025/11/sec-drop-high-profile-solarwinds-hack-lawsuit/409684/", "label": "Nextgov, SEC to drop SolarWinds lawsuit"}]}, "evidence": {"kind": "faceOff", "prompt": "Which statement should you approve?", "left": {"name": "Describe practices as they really are", "note": "Accurate, less impressive"}, "right": {"name": "Approve the draft as written", "note": "Impressive, partly untrue"}, "correctIndex": 0, "explanation": "The SolarWinds claims that survived concerned a public statement that did not match reality."}, "numbers": {"kind": "numberSense", "prompt": "About how many years after its 2018 IPO did the Sunburst hack come to light?", "min": 0, "max": 10, "value": 2, "unit": "years", "explanation": "About two: the IPO was in 2018 and the hack came to light in December 2020."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a CISO role, you're asked about approving public security claims.", "prompt": "What is your rule?", "options": ["Only approve claims that match what is in place", "Approve whatever marketing writes", "Refuse to allow any public security statement"], "correctIndex": 0, "consequences": ["That avoids the SolarWinds gap.", "That invites the same claim.", "Customers need some information."], "explanation": "Public claims should describe reality. That protects the company and you."}, "proReasoning": "Strong candidates hold the line on accuracy without blocking communication.", "commonMistake": "Signing claims you know are not true.", "mentalModel": "Claims must match reality."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold publishes bold security claims but has had breaches.", "prompt": "What should you watch for?", "options": ["A ban on publishing claims", "A gap between its claims and its record", "Nothing, since claims are just marketing"], "correctIndex": 1, "consequences": ["No such ban exists.", "That gap drew the SEC in SolarWinds.", "The SEC treated them as more."], "explanation": "A gap between claims and reality can become a legal and trust problem."}, "proReasoning": "Investors compare promises to track records.", "commonMistake": "Ignoring the gap between words and deeds.", "mentalModel": "Compare claims to the record."}, "build_startup": {"call": {"kind": "theCall", "situation": "You lead security at a startup preparing to go public. Marketing wants bold claims.", "prompt": "What do you push for?", "options": ["The boldest claims to impress investors", "No security claims, ever, in any filing", "Accurate claims you can back with evidence"], "correctIndex": 2, "consequences": ["SolarWinds shows the risk from the IPO on.", "Some disclosure is required.", "Evidence-backed claims hold up."], "explanation": "Claims made at an IPO can be judged for years. Make them true."}, "proReasoning": "Founders know early claims follow the company.", "commonMistake": "Overclaiming for a short-term win.", "mentalModel": "Make early claims true."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a CISO would refuse to sign a nice-sounding security statement.", "prompt": "What's the answer?", "options": ["It might not match reality, which carries risk", "CISOs dislike all marketing on principle", "Statements are illegal for public firms"], "correctIndex": 0, "consequences": ["That was the SEC's claim against SolarWinds.", "The issue is accuracy.", "They are allowed if true."], "explanation": "A statement that overstates security can become evidence against the company and its leaders."}, "proReasoning": "Ask whether a claim is true, not whether it sounds good.", "commonMistake": "Thinking a statement is harmless because it sounds good.", "mentalModel": "True beats impressive."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:20dae535b5d7$ml$]::text[]),
($ml$60a83b99-98b6-5a0e-9c6d-a3c1e7b703fb$ml$::uuid, $ml$cybersecurity$ml$, 19, 1, $ml${"id": "cybersecurity-d19-c1", "title": "A £2.31M fine for missing MFA", "lessonTitle": "Who you are versus what you can do", "slot": 1, "type": "apply", "brief": {"headline": "In June 2025, the UK privacy regulator fined 23andMe £2.31 million. Attackers used reused passwords over five months in 2023, and the regulator said MFA was not required.", "kicker": "Apply the idea: weak authentication let attackers log in as customers.", "fullText": "From April to September 2023, attackers ran a credential stuffing attack on 23andMe: trying usernames and passwords leaked from other sites. They reached data on 155,592 UK residents. The company found out when an employee saw the data offered for sale online, and only began a full investigation in October 2023.\n\nIn June 2025, the UK's Information Commissioner's Office fined 23andMe £2.31 million. It said the company lacked mandatory multifactor authentication, secure password rules and proper monitoring.", "sources": [{"url": "https://ico.org.uk/about-the-ico/media-centre/news-and-blogs/2025/06/23andme-fined-for-failing-to-protect-uk-users-genetic-data", "label": "ICO, 23andMe fined for failing to protect UK users"}]}, "evidence": {"kind": "sortSignal", "prompt": "Was each gap about authentication or monitoring?", "buckets": ["Authentication", "Monitoring"], "items": [{"text": "No mandatory multifactor authentication", "bucket": 0}, {"text": "Weak password protections", "bucket": 0}, {"text": "Attack ran for months before it was noticed", "bucket": 1}, {"text": "Found when an employee saw data for sale", "bucket": 1}], "explanation": "Weak login checks let attackers in; weak monitoring let them stay for months."}, "numbers": {"kind": "numberSense", "prompt": "How many UK residents were affected, in thousands?", "min": 0, "max": 250, "value": 156, "unit": "K", "explanation": "155,592 UK residents."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked what stopped 23andMe from catching reused passwords.", "prompt": "Which answer fits the regulator's findings?", "options": ["Its servers were hit by a new zero-day flaw", "An employee handed attackers the database", "MFA was not required and monitoring was weak"], "correctIndex": 2, "consequences": ["This was credential stuffing, not an exploit.", "Attackers logged in as customers.", "The ICO named both."], "explanation": "Reused passwords work when there is no second check and nobody notices odd logins."}, "proReasoning": "Strong candidates tie a breach to the specific control that was missing.", "commonMistake": "Assuming every breach is a software flaw.", "mentalModel": "Name the missing control."}, "invest": {"call": {"kind": "theCall", "situation": "A consumer app you hold lets users log in without MFA.", "prompt": "What does 23andMe suggest about its risk?", "options": ["Reused passwords can expose users, with fines to follow", "Optional MFA has no effect at all on account risk", "Regulators never fine consumer apps"], "correctIndex": 0, "consequences": ["The ICO fined 23andMe £2.31 million.", "Missing MFA was a named failing.", "This one was fined."], "explanation": "Without a second check, leaked passwords from elsewhere can open accounts."}, "proReasoning": "Investors ask how consumer apps protect logins.", "commonMistake": "Treating MFA as a minor feature.", "mentalModel": "Ask how logins are protected."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup detects credential stuffing on login pages.", "prompt": "Which fact supports your pitch?", "options": ["It needed insiders to work at all", "The attack ran for months before anyone noticed", "It was spotted and stopped within the first hour"], "correctIndex": 1, "consequences": ["Attackers used leaked logins.", "Detection is the gap you fill.", "It ran April to September."], "explanation": "Months of undetected logins show the value of spotting stuffing early."}, "proReasoning": "Founders point to how long the problem went unseen.", "commonMistake": "Ignoring the detection gap.", "mentalModel": "Show how long it went unseen."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how hackers got into 23andMe accounts.", "prompt": "What's the simple answer?", "options": ["They broke the company's encryption with a supercomputer", "They stole the company's servers", "They reused passwords leaked from other sites"], "correctIndex": 2, "consequences": ["They logged in.", "They used customer logins.", "That is credential stuffing."], "explanation": "People reuse passwords. Attackers try leaked ones until some work."}, "proReasoning": "Ask whether attackers broke in or logged in.", "commonMistake": "Assuming hacks always involve breaking code.", "mentalModel": "Many attackers log in."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:945cd99b81a3$ml$]::text[]),
($ml$6f33389d-91d2-5b79-9f7b-3559cf293935$ml$::uuid, $ml$cybersecurity$ml$, 19, 2, $ml${"id": "cybersecurity-d19-c2", "title": "From Snowflake to the DBIR", "lessonTitle": "Who you are versus what you can do", "slot": 2, "type": "connect", "brief": {"headline": "In 2024, stolen logins on accounts without MFA hit as many as 165 Snowflake customers. In Verizon's 2025 report, credential abuse was the top way into breaches, at 22%.", "kicker": "Connect day 3 and day 19: logins are now the main door.", "fullText": "Day 3 told the Snowflake story. Attackers used stolen customer logins, many harvested by malware, on accounts without multifactor authentication. As many as 165 customers may have had data exposed.\n\nDay 19 showed it was not a one-off. In Verizon's 2025 report, credential abuse was the top way into breaches, at 22%, just ahead of exploited flaws at 20%. Authentication proves who you are; when a login is stolen, the attacker passes that check.", "sources": [{"url": "https://thehackernews.com/2024/06/snowflake-breach-exposes-165-customers.html", "label": "The Hacker News, Snowflake breach exposes 165 customers"}, {"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What was the top way into breaches in Verizon's 2025 report?", "options": ["Lost laptops", "Credential abuse", "Exploited flaws"], "correctIndex": 1, "explanation": "Credential abuse led at 22%, just ahead of exploited flaws at 20%."}, "numbers": {"kind": "numberSense", "prompt": "What share of breaches started with credential abuse?", "min": 0, "max": 60, "value": 22, "unit": "%", "explanation": "22%, per Verizon's 2025 report."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why identity matters so much now.", "prompt": "What is the best answer?", "options": ["Stolen logins are the top way into breaches", "Firewalls have stopped all other attacks", "Passwords can no longer be stolen"], "correctIndex": 0, "consequences": ["22% in Verizon's report.", "Exploits were 20%.", "Snowflake shows they can."], "explanation": "When attackers log in with real credentials, identity checks are the front line."}, "proReasoning": "Strong candidates back the claim with a number.", "commonMistake": "Talking about identity without the data.", "mentalModel": "Back it with the data."}, "invest": {"call": {"kind": "theCall", "situation": "You are weighing identity security companies.", "prompt": "Which fact supports demand?", "options": ["Snowflake was not affected by logins", "Credential abuse led breaches at 22%", "Logins are rarely used in attacks"], "correctIndex": 1, "consequences": ["Stolen logins caused it.", "It is the most common way in.", "They are the most common."], "explanation": "The most common way in sets where spending goes."}, "proReasoning": "Investors follow the leading cause of breaches.", "commonMistake": "Investing against the data.", "mentalModel": "Follow the leading cause."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup flags logins that come from stolen credentials.", "prompt": "Which story makes your case?", "options": ["A breach caused by a broken office door lock", "An outage caused by bad weather", "Snowflake customers hit by old stolen logins"], "correctIndex": 2, "consequences": ["Not a login problem.", "Not a login problem.", "Credentials stolen years earlier still worked."], "explanation": "Snowflake shows stolen logins stay useful until someone notices them."}, "proReasoning": "Founders anchor the pitch in a well-known case.", "commonMistake": "Using an example unrelated to the product.", "mentalModel": "Anchor in a known case."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether most hackers break in through software bugs.", "prompt": "What's the more accurate picture?", "options": ["Stolen logins are slightly more common", "Software bugs cause every breach", "Hackers never use real logins"], "correctIndex": 0, "consequences": ["22% versus 20%.", "Logins edged them out.", "They often do."], "explanation": "Stolen logins and software bugs are close, with logins just ahead."}, "proReasoning": "Ask how attackers got in.", "commonMistake": "Assuming hacks are always about bugs.", "mentalModel": "Logins are the top door."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b13cdd7a61e8$ml$]::text[]),
($ml$b6ba6dfe-82e9-5a21-921e-a4b8952e2d48$ml$::uuid, $ml$cybersecurity$ml$, 19, 3, $ml${"id": "cybersecurity-d19-c3", "title": "Everyone is an admin", "lessonTitle": "Who you are versus what you can do", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a 200-person law firm where every employee has admin rights. Credential abuse was the top way into breaches in 2025, at 22%.", "kicker": "Decide: which check fails when a login is stolen, and what limits the damage?", "fullText": "You run IT at a law firm. For convenience, every employee has administrator rights on their laptop and broad access to shared files.\n\nDay 19 split identity into two checks. Authentication proves who you are; authorization decides what you can reach once you are in. Credential abuse led breaches at 22% in Verizon's 2025 report. When a login is stolen, authentication waves the attacker through, so authorization decides how much damage they can do.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}]}, "evidence": {"kind": "faceOff", "prompt": "Which change limits damage from a stolen login most?", "left": {"name": "Give each account only what it needs", "note": "Least privilege"}, "right": {"name": "Make every password longer", "note": "Stronger authentication only"}, "correctIndex": 0, "explanation": "Least privilege limits what a stolen account can reach, even after authentication fails."}, "numbers": {"kind": "numberSense", "prompt": "What share of breaches started with exploited flaws, per Verizon 2025?", "min": 0, "max": 60, "value": 20, "unit": "%", "explanation": "20%, just behind credential abuse at 22%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to explain authentication and authorization.", "prompt": "Which explanation is right?", "options": ["Authorization is proving who you are", "AuthN is who you are; authZ is what you can do", "They mean the same thing in day to day practice"], "correctIndex": 1, "consequences": ["That is authentication.", "That is the split.", "They are different checks."], "explanation": "Two checks, two jobs. Least privilege is an authorization control."}, "proReasoning": "Strong candidates use the terms precisely.", "commonMistake": "Mixing up the two checks.", "mentalModel": "Who you are vs. what you can do."}, "invest": {"call": {"kind": "theCall", "situation": "A professional services firm you might back gives everyone admin rights.", "prompt": "What risk does that create?", "options": ["Admin rights for all make breaches impossible", "It only affects printing speed", "One stolen login can reach almost everything"], "correctIndex": 2, "consequences": ["They do the opposite.", "The risk is access.", "No limits after authentication."], "explanation": "Broad access turns one stolen login into a firm-wide problem."}, "proReasoning": "Investors ask how access is limited, not just how logins are protected.", "commonMistake": "Ignoring authorization because MFA exists.", "mentalModel": "Ask how access is limited."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run IT at the firm. Partners resist losing admin rights.", "prompt": "What do you propose?", "options": ["Remove admin by default, grant it when needed", "Keep admin for all and hope for the best", "Ban laptops for everyone at the firm"], "correctIndex": 0, "consequences": ["Least privilege with a path for exceptions.", "One stolen login could reach everything.", "Too disruptive to work."], "explanation": "Default to least privilege, with a quick way to get more access when justified."}, "proReasoning": "Founders and leaders pair a security change with a smooth workflow.", "commonMistake": "Pushing a change with no path for real needs.", "mentalModel": "Least privilege, with a fast path."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their company removed their admin rights.", "prompt": "What's a good answer?", "options": ["Because admin rights cost money monthly", "So a stolen login cannot reach everything", "To make their laptop run more slowly"], "correctIndex": 1, "consequences": ["It is about limiting damage.", "That is least privilege.", "It is about access."], "explanation": "If your login is stolen, less access means less damage."}, "proReasoning": "Ask what a stolen login could reach.", "commonMistake": "Taking it as a sign of distrust.", "mentalModel": "Less access, less damage."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d526a2af32f2$ml$]::text[]),
($ml$c1de20f8-f9b4-5edb-b6da-1ce8401b234e$ml$::uuid, $ml$cybersecurity$ml$, 20, 1, $ml${"id": "cybersecurity-d20-c1", "title": "SailPoint returns to the market", "lessonTitle": "A $25 billion bet on identity", "slot": 1, "type": "apply", "brief": {"headline": "In February 2025, identity security firm SailPoint raised $1.38 billion in an IPO, valuing it at $12.8 billion. Thoma Bravo had taken it private in 2022 for $6.9 billion.", "kicker": "Apply the idea: investors are paying up for identity.", "fullText": "SailPoint sells identity security software that manages who can access what inside a company. Customers include General Motors and Hershey.\n\nPrivate equity firm Thoma Bravo took SailPoint private in 2022 for $6.9 billion. On February 13, 2025, it returned to the stock market after an upsized $1.38 billion IPO. Its shares opened at $23, in line with the offer price, valuing it at $12.8 billion.", "sources": [{"url": "https://www.thestar.com.my/tech/tech-news/2025/02/14/thoma-bravo-backed-sailpoint-valued-at-128-billion-in-stock-market-return", "label": "Reuters via The Star, SailPoint valued at $12.8 billion"}]}, "evidence": {"kind": "buildChain", "prompt": "Put SailPoint's story in order.", "steps": ["SailPoint builds identity security software", "Thoma Bravo buys it for $6.9 billion in 2022", "It raises $1.38 billion in an IPO", "It opens at $23, valued at $12.8 billion"], "explanation": "Taken private, then back on the market at a higher valuation."}, "numbers": {"kind": "numberSense", "prompt": "At what valuation did SailPoint return to the market, in billions of dollars?", "min": 0, "max": 20, "value": 12.8, "unit": "B", "explanation": "$12.8 billion, at its $23 opening price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an identity security company. They ask why the market is hot.", "prompt": "What do you say?", "options": ["Stolen logins lead breaches, so access control matters", "Identity tools are mostly for printing staff badges", "Companies are cutting all identity spending"], "correctIndex": 0, "consequences": ["Credential abuse led breaches in 2025.", "It is about access, not badges.", "SailPoint's IPO suggests otherwise."], "explanation": "When attackers log in, controlling who can access what becomes core security."}, "proReasoning": "Strong candidates link market demand to the attack data.", "commonMistake": "Explaining a market without its driver.", "mentalModel": "Link demand to the attacks."}, "invest": {"call": {"kind": "theCall", "situation": "You are reading about SailPoint's IPO.", "prompt": "What does the valuation change suggest?", "options": ["The IPO was priced far below its offer", "Investors value identity security more than in 2022", "Identity security has lost value since its 2022 sale"], "correctIndex": 1, "consequences": ["It opened in line with the offer.", "$6.9 billion to $12.8 billion.", "It rose."], "explanation": "A higher valuation on return signals strong investor demand for identity."}, "proReasoning": "Investors compare entry and exit values to read sentiment.", "commonMistake": "Ignoring the earlier price.", "mentalModel": "Compare entry and exit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells access reviews to mid-size companies.", "prompt": "What does SailPoint's IPO tell you?", "options": ["Only tiny firms care about access", "Identity software has no customers", "Large buyers pay for identity security"], "correctIndex": 2, "consequences": ["Large firms buy it.", "SailPoint has major customers.", "GM and Hershey are customers."], "explanation": "A large public identity company shows buyers will pay. You can serve the segment below it."}, "proReasoning": "Founders use a leader's success to validate the market.", "commonMistake": "Assuming there is no market.", "mentalModel": "Use the leader to validate demand."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a company like SailPoint actually does.", "prompt": "What's the simple answer?", "options": ["It manages who can access what inside a company", "It makes antivirus software for home computers", "It sells passwords to other companies"], "correctIndex": 0, "consequences": ["That is identity security.", "Different product.", "It manages access."], "explanation": "Identity security decides and tracks who can reach which systems."}, "proReasoning": "Ask what a product controls.", "commonMistake": "Lumping all security into antivirus.", "mentalModel": "It manages access."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:454ddfc10f02$ml$]::text[]),
($ml$21110d2f-627c-5b80-be51-668521fce159$ml$::uuid, $ml$cybersecurity$ml$, 20, 2, $ml${"id": "cybersecurity-d20-c2", "title": "The top door and the master keys", "lessonTitle": "A $25 billion bet on identity", "slot": 2, "type": "connect", "brief": {"headline": "Credential abuse was the top way into breaches in 2025, at 22%. Months later, Palo Alto Networks agreed to buy CyberArk, which protects the most powerful logins, for $25 billion.", "kicker": "Connect day 19 and day 20: if logins are the door, privileged logins are the master keys.", "fullText": "Day 19 showed attackers logging in more than breaking in. Credential abuse led Verizon's 2025 breach data at 22%.\n\nDay 20 showed where the money went. In July 2025, Palo Alto Networks agreed to buy CyberArk for about $25 billion. CyberArk protects privileged accounts, the logins that can change systems, read everything or turn defenses off. Palo Alto offered $45 in cash plus 2.2005 of its shares per CyberArk share, a 26% premium.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}, {"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each account privileged or standard?", "buckets": ["Privileged", "Standard"], "items": [{"text": "An administrator who can change any server", "bucket": 0}, {"text": "A bot that can turn off security tools", "bucket": 0}, {"text": "A salesperson reading the team calendar", "bucket": 1}, {"text": "An intern viewing the company handbook", "bucket": 1}], "explanation": "Privileged accounts can change systems or switch defenses off; that is why attackers want them."}, "numbers": {"kind": "numberSense", "prompt": "What premium did Palo Alto offer CyberArk shareholders?", "min": 0, "max": 60, "value": 26, "unit": "%", "explanation": "26%, in cash plus stock."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why privileged accounts deserve extra protection.", "prompt": "What is the best answer?", "options": ["They cannot be stolen by attackers", "They can change systems or turn defenses off", "They are used less, so they matter less"], "correctIndex": 1, "consequences": ["They can be stolen like any login.", "That is what attackers want most.", "Power, not frequency, sets the risk."], "explanation": "With logins the top door, the most powerful ones are the biggest prize."}, "proReasoning": "Strong candidates rank accounts by what they can do.", "commonMistake": "Treating every account the same.", "mentalModel": "Rank accounts by power."}, "invest": {"call": {"kind": "theCall", "situation": "You follow Palo Alto Networks after the CyberArk deal.", "prompt": "What is the strategic logic?", "options": ["Leaving the security market entirely", "Cutting its product lineup down to just one tool", "Adding identity to network and cloud security"], "correctIndex": 2, "consequences": ["It is expanding.", "It is adding, not cutting.", "Palo Alto said identity becomes core."], "explanation": "With stolen logins leading breaches, owning identity rounds out a security platform."}, "proReasoning": "Investors read deals through the problem they target.", "commonMistake": "Judging a deal by price alone.", "mentalModel": "Read the deal by the problem it targets."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup protects admin accounts for small companies.", "prompt": "Which deal helps your pitch?", "options": ["Palo Alto paying $25 billion for CyberArk", "A bakery buying a new oven", "A sports team trading a player for cash"], "correctIndex": 0, "consequences": ["It shows how much privileged access is valued.", "Unrelated.", "Unrelated."], "explanation": "A $25 billion deal shows the market's view of privileged access. Smaller firms need it too."}, "proReasoning": "Founders use big deals to signal market value.", "commonMistake": "Citing irrelevant comparisons.", "mentalModel": "Use big deals as signals."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a security company would pay $25 billion for another.", "prompt": "What's a good answer?", "options": ["The deal was a gift with no reason", "Protecting powerful logins is a top priority", "CyberArk makes the fastest laptops on the market"], "correctIndex": 1, "consequences": ["There was a clear reason.", "Logins are the top way in.", "It protects accounts."], "explanation": "Attackers want the most powerful logins. Protecting them is worth a lot."}, "proReasoning": "Ask what problem the buyer is solving.", "commonMistake": "Seeing a big deal as hype.", "mentalModel": "Ask what problem it solves."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:73f1c5c56658$ml$]::text[]),
($ml$53fce975-84dc-5763-aadc-7a0afd3a5bdd$ml$::uuid, $ml$cybersecurity$ml$, 20, 3, $ml${"id": "cybersecurity-d20-c3", "title": "Hundreds of bots log in", "lessonTitle": "A $25 billion bet on identity", "slot": 3, "type": "decide", "brief": {"headline": "You lead security at a mid-size company. Hundreds of software bots now log in to your systems daily. Palo Alto cited machine identities when it agreed to buy CyberArk.", "kicker": "Decide: should machine identities get admin-level controls?", "fullText": "You lead security at a mid-size company. Hundreds of software bots and AI agents now log in to your systems every day, some with broad access.\n\nDay 20 showed why that matters. When Palo Alto Networks agreed to buy CyberArk for about $25 billion in July 2025, its CEO pointed to AI and an explosion of machine identities. Not every identity is a person anymore, and some machine logins are as powerful as administrators.", "sources": [{"url": "https://www.intelligentcio.com/north-america/2025/07/30/palo-alto-networks-to-acquire-cyberark-in-25-billion-deal-to-expand-identity-security-and-ai-protection/", "label": "Intelligent CIO, Palo Alto Networks to acquire CyberArk"}]}, "evidence": {"kind": "faceOff", "prompt": "How should powerful bot accounts be treated?", "left": {"name": "Like admins, with the same controls", "note": "Least privilege and monitoring"}, "right": {"name": "As trusted, since they are software", "note": "Broad access, little oversight"}, "correctIndex": 0, "explanation": "Machine identities can be as powerful as admins, so they need the same controls."}, "numbers": {"kind": "numberSense", "prompt": "About how much did Palo Alto agree to pay for CyberArk, in billions of dollars?", "min": 0, "max": 40, "value": 25, "unit": "B", "explanation": "About $25 billion, in cash and stock."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to secure bot and AI agent accounts.", "prompt": "What do you recommend?", "options": ["Give bots full access so nothing breaks", "Ignore bots since only people get hacked", "Give each bot only what it needs, and watch it"], "correctIndex": 2, "consequences": ["One stolen bot login could reach everything.", "Machine logins can be abused too.", "Same controls as powerful human accounts."], "explanation": "Bots are identities. Least privilege and monitoring apply to them too."}, "proReasoning": "Strong candidates include machines in identity plans.", "commonMistake": "Securing people and forgetting machines.", "mentalModel": "Machines are identities too."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold is adding many AI agents to its operations.", "prompt": "What should you ask?", "options": ["How it controls what those agents can access", "How many of its agents have friendly names", "Whether agents use a nice font"], "correctIndex": 0, "consequences": ["Powerful machine logins need controls.", "Names do not limit access.", "Irrelevant."], "explanation": "More machine identities means more powerful logins to control."}, "proReasoning": "Investors ask how new technology changes the risk surface.", "commonMistake": "Adopting AI without asking about access.", "mentalModel": "Ask how agents are controlled."}, "build_startup": {"call": {"kind": "theCall", "situation": "You lead security. A team wants a bot with full admin rights to move fast.", "prompt": "What do you decide?", "options": ["Block all bots from every system", "Scope its access to the task, with logging", "Approve full admin rights to avoid any delays"], "correctIndex": 1, "consequences": ["Too blunt; bots are useful.", "Least privilege keeps speed and limits risk.", "One compromise would reach everything."], "explanation": "Scoped access lets the team move without handing out master keys."}, "proReasoning": "Founders balance speed with control.", "commonMistake": "Trading safety for convenience.", "mentalModel": "Scope access to the task."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why bots need security controls.", "prompt": "What's the answer?", "options": ["Bots get tired and make mistakes", "Bots always report themselves if hacked", "Their logins can be as powerful as admins'"], "correctIndex": 2, "consequences": ["The risk is access.", "They do not.", "That is why Palo Alto cited them."], "explanation": "A bot with broad access is a master key if it is stolen."}, "proReasoning": "Ask what a login can do, not who uses it.", "commonMistake": "Assuming only human logins matter.", "mentalModel": "Every login is a key."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e4339f8a3613$ml$]::text[]),
($ml$0f39eb54-f1f6-5b33-8ed3-777deed8750c$ml$::uuid, $ml$cybersecurity$ml$, 21, 1, $ml${"id": "cybersecurity-d21-c1", "title": "A retailer loses six weeks online", "lessonTitle": "The help desk holds the keys", "slot": 1, "type": "apply", "brief": {"headline": "An attack over Easter 2025 forced Marks & Spencer to pause online orders for about six weeks. It cost about £324 million in lost sales, and profit more than halved.", "kicker": "Apply the idea: people, not code, were the way in.", "fullText": "Marks & Spencer was hit by a cyberattack over the Easter 2025 weekend. By April 25 it had suspended online orders, and they stayed off for about six weeks.\n\nThe company put lost sales at about £324 million and direct costs at £135.6 million, with a £100 million insurance payout. Underlying pre-tax profit fell 55.4% to £184.1 million. The attack was linked to a third-party contractor's access through phishing and social engineering, and the chief executive called it human error.", "sources": [{"url": "https://breached.company/the-300-million-aftermath-marks-spencers-profit-collapse-reveals-the-true-cost-of-cyber-resilience/", "label": "Breached.company, the cost of the Marks & Spencer attack"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Online orders were paused for about six weeks.", "M&S profit rose after the attack.", "Social engineering was part of the attack."], "fakeIndex": 1, "explanation": "Underlying pre-tax profit fell 55.4%, to £184.1 million."}, "numbers": {"kind": "numberSense", "prompt": "About how much did M&S lose in sales, in millions of pounds?", "min": 0, "max": 500, "value": 324, "unit": "M", "explanation": "About £324 million, with £135.6 million in direct costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a retailer. They ask what the M&S attack teaches.", "prompt": "Which lesson do you lead with?", "options": ["Only firewalls matter for keeping attackers out", "Train and verify people who can grant access", "Retail websites cannot be attacked at all"], "correctIndex": 1, "consequences": ["People were the weak point here.", "Social engineering opened the door.", "M&S was attacked."], "explanation": "Social engineering targets people with access. Verification steps protect them."}, "proReasoning": "Strong candidates look past technology to the people who grant access.", "commonMistake": "Treating security as only a technical problem.", "mentalModel": "Protect the people with access."}, "invest": {"call": {"kind": "theCall", "situation": "A retailer you hold relies heavily on online sales.", "prompt": "What does M&S show about its risk?", "options": ["Online sales are immune to cyberattacks", "Insurance covers every pound of the loss", "An attack can halt online revenue for weeks"], "correctIndex": 2, "consequences": ["M&S shows otherwise.", "Insurance covered about £100 million.", "M&S paused online orders for six weeks."], "explanation": "Weeks without online orders hit sales and profit, and insurance covered only part."}, "proReasoning": "Investors compare the size of the loss to what insurance covers.", "commonMistake": "Assuming insurance makes a company whole.", "mentalModel": "Compare loss to coverage."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup trains contractors and staff to spot social engineering.", "prompt": "Which M&S detail supports your pitch?", "options": ["A contractor's access was abused through phishing", "The attack used a brand new software flaw only", "No people were involved at any point"], "correctIndex": 0, "consequences": ["People outside the company were the way in.", "It was linked to social engineering.", "Human error was named."], "explanation": "If contractors can be tricked, training must reach beyond your own staff."}, "proReasoning": "Founders point to who was actually fooled.", "commonMistake": "Training only employees and forgetting contractors.", "mentalModel": "Train everyone with access."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how hackers shut down a big retailer's website.", "prompt": "What's the simple answer?", "options": ["They bought the company's shares", "They tricked people who had access", "They cut the store's power lines"], "correctIndex": 1, "consequences": ["It was not a takeover.", "Phishing and social engineering.", "It was a cyberattack."], "explanation": "The attackers fooled people rather than breaking code. The CEO called it human error."}, "proReasoning": "Ask who was fooled.", "commonMistake": "Picturing only technical hacks.", "mentalModel": "People can be the way in."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4d9fccd2fc2b$ml$]::text[]),
($ml$15e1fa33-799c-5274-bf76-659d3d4c1ec3$ml$::uuid, $ml$cybersecurity$ml$, 21, 2, $ml${"id": "cybersecurity-d21-c2", "title": "Logging in through the help desk", "lessonTitle": "The help desk holds the keys", "slot": 2, "type": "connect", "brief": {"headline": "Credential abuse led breaches in 2025 at 22%. At MGM in 2023, attackers claimed they got a login another way: by calling the help desk posing as an employee.", "kicker": "Connect day 19 and day 21: a password reset is an authentication shortcut.", "fullText": "Day 19 showed that credential abuse led Verizon's 2025 breach data at 22%. Authentication proves who you are, and a stolen login passes that check.\n\nDay 21 showed another way to get a login. In September 2023, an attack disrupted MGM Resorts for about 10 days and cost it about $100 million. MGM never named the way in, but attackers linked to Scattered Spider claimed they called the IT help desk posing as an employee. A reset hands over the account.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}, {"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, "evidence": {"kind": "faceOff", "prompt": "Who holds more power over an employee's account?", "left": {"name": "The employee", "note": "Knows the password"}, "right": {"name": "The help desk", "note": "Can reset the password"}, "correctIndex": 1, "explanation": "Whoever can reset a password holds power over every account."}, "numbers": {"kind": "numberSense", "prompt": "About how many days was MGM disrupted?", "min": 0, "max": 30, "value": 10, "unit": "days", "explanation": "About 10 days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why help desks are a security risk.", "prompt": "What is the best answer?", "options": ["They have no access to any staff accounts", "They only handle printer problems", "They can reset logins for anyone who calls"], "correctIndex": 2, "consequences": ["They can reset passwords.", "They reset access.", "A reset hands over the account."], "explanation": "A help desk that resets logins is an authentication path attackers can target."}, "proReasoning": "Strong candidates see every reset path as part of authentication.", "commonMistake": "Thinking of the help desk as outside security.", "mentalModel": "Every reset path is authentication."}, "invest": {"call": {"kind": "theCall", "situation": "A hotel group you hold says its help desk resets passwords over the phone.", "prompt": "What should you ask?", "options": ["How callers prove their identity", "How fast the phones get answered", "Whether calls play hold music"], "correctIndex": 0, "consequences": ["That is the MGM risk.", "Speed can help attackers.", "Irrelevant."], "explanation": "If a convincing voice is enough, the help desk is a way in."}, "proReasoning": "Investors ask about the human steps in security.", "commonMistake": "Ignoring processes that grant access.", "mentalModel": "Ask how callers are verified."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup verifies callers' identity for IT help desks.", "prompt": "Which story makes your case?", "options": ["A firewall blocked a scan", "MGM attackers claimed a help desk call got them in", "A help desk fixed a broken office printer quickly"], "correctIndex": 1, "consequences": ["Not about help desks.", "The cost was about $100 million.", "Not a security story."], "explanation": "A claimed 10-minute call and a $100 million hit make the case for verification."}, "proReasoning": "Founders anchor pitches in costly, well-known incidents.", "commonMistake": "Pitching without a concrete incident.", "mentalModel": "Anchor in a costly incident."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a phone call could cost a company $100 million.", "prompt": "What's the answer?", "options": ["The call bill was very expensive", "The phone itself had malware on it", "A reset gave attackers a working login"], "correctIndex": 2, "consequences": ["The cost was the attack.", "The claim was a reset.", "That is what attackers claimed at MGM."], "explanation": "If the help desk resets the wrong person's login, the attacker walks in with real access."}, "proReasoning": "Ask what the caller was able to get.", "commonMistake": "Underestimating social engineering.", "mentalModel": "A reset can hand over access."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:92035aa52724$ml$]::text[]),
($ml$a734b732-0548-5ab3-9534-b94057f109a9$ml$::uuid, $ml$cybersecurity$ml$, 21, 3, $ml${"id": "cybersecurity-d21-c3", "title": "A caller says he is the CFO", "lessonTitle": "The help desk holds the keys", "slot": 3, "type": "decide", "brief": {"headline": "You run the IT help desk at a hotel chain. A caller says he is the CFO, locked out before a board meeting, and wants an urgent reset. MGM shows what one call can cost.", "kicker": "Decide: help fast, or verify first?", "fullText": "You run the IT help desk at a hotel chain. A confident caller says he is the CFO, locked out minutes before a board meeting, and needs his password and MFA reset now.\n\nDay 21 showed the stakes. Attackers linked to Scattered Spider claimed a help desk call got them into MGM in 2023, an attack that cost about $100 million. Microsoft describes the group as financially motivated and native English-speaking, which makes their calls convincing.", "sources": [{"url": "https://www.adaptivesecurity.com/blog/mgm-ransomware-attack", "label": "Adaptive Security, the MGM attack, citing MGM filings"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What cuts this attack short?", "options": ["Verifying identity through a separate channel", "Answering the phone faster", "Asking the caller to spell out his full name"], "correctIndex": 0, "explanation": "If the help desk verifies identity properly, a convincing voice is not enough."}, "numbers": {"kind": "numberSense", "prompt": "About how much did the MGM attack cost, in millions of dollars?", "min": 0, "max": 160, "value": 100, "unit": "M", "explanation": "About $100 million, plus under $10 million in one-time costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a help desk lead role, you're asked how you'd handle this call.", "prompt": "What do you do?", "options": ["Verify through a known channel before resetting", "Reset it right away; he sounds urgent", "Hang up and block all calls from the CFO forever"], "correctIndex": 0, "consequences": ["A call back to a known number defeats impersonation.", "Urgency is a common social engineering tool.", "Too blunt; real executives need help."], "explanation": "Verification through a separate channel stops impersonation without refusing real users."}, "proReasoning": "Strong candidates resist urgency and follow process.", "commonMistake": "Letting pressure override verification.", "mentalModel": "Verify, then help."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold lets help desk staff reset MFA after a short phone call.", "prompt": "How should that affect your view?", "options": ["It has no link to security at all", "It is a known path for costly attacks", "It shows excellent customer service only"], "correctIndex": 1, "consequences": ["It is an access control.", "MGM attackers claimed this path.", "Service without checks is risk."], "explanation": "Fast resets without strong checks are a recognized attack path."}, "proReasoning": "Investors look for controls on high-power processes.", "commonMistake": "Mistaking convenience for safety.", "mentalModel": "Fast resets need strong checks."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the help desk. Staff say verification slows them down.", "prompt": "What do you change?", "options": ["Drop verification to keep staff happy", "Let callers choose whether to verify", "Make verification quick but mandatory"], "correctIndex": 2, "consequences": ["That reopens the door.", "Attackers would opt out.", "Speed and safety together."], "explanation": "A fast, required check keeps the line moving and closes the door."}, "proReasoning": "Founders and leaders design controls people will actually follow.", "commonMistake": "Making security optional.", "mentalModel": "Quick but mandatory."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend works at a help desk and wonders why they must verify executives.", "prompt": "What's a good answer?", "options": ["Attackers often pretend to be senior staff", "Executives forget their own names", "Verification is only needed for brand new hires"], "correctIndex": 0, "consequences": ["Urgency and rank are common pressure tools.", "It is about impersonation.", "Everyone needs it."], "explanation": "Pretending to be an executive adds pressure. Verification removes the advantage."}, "proReasoning": "Ask what the caller gains if you are wrong.", "commonMistake": "Assuming rank proves identity.", "mentalModel": "Rank is not proof."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a61296c84af4$ml$]::text[]),
($ml$b6bc61ea-4ac6-55a3-9449-853e7cc77ac2$ml$::uuid, $ml$cybersecurity$ml$, 22, 1, $ml${"id": "cybersecurity-d22-c1", "title": "150 million users, half the hacks", "lessonTitle": "99.22%", "slot": 1, "type": "apply", "brief": {"headline": "Google auto-enrolled more than 150 million users in two-step verification. In 2022, it said those users saw 50% fewer account compromises.", "kicker": "Apply the idea: turning MFA on by default moves the numbers.", "fullText": "Google automatically enrolled more than 150 million users in two-step verification and required it for more than 2 million YouTube accounts. In February 2022, it said enrolled users saw a 50% decrease in account compromises.\n\nGoogle noted the comparison was not perfectly one to one. Still, it showed that turning on a second check by default, rather than waiting for users to opt in, can cut account takeovers at huge scale.", "sources": [{"url": "https://www.techtarget.com/cybersecurity/news/252513218/Google-2-step-verification-led-to-50-fewer-account-hacks", "label": "TechTarget, Google 2-step verification led to 50% fewer account hacks"}]}, "evidence": {"kind": "faceOff", "prompt": "Which approach reached more users?", "left": {"name": "Auto-enrolling users by default", "note": "What Google did"}, "right": {"name": "Waiting for users to opt in", "note": "The usual approach"}, "correctIndex": 0, "explanation": "Defaults reach people who would never change a setting on their own."}, "numbers": {"kind": "numberSense", "prompt": "About how many users did Google auto-enroll, in millions?", "min": 0, "max": 250, "value": 150, "unit": "M", "explanation": "More than 150 million, plus 2 million YouTube creators."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a consumer app. They ask how to raise MFA use.", "prompt": "What do you suggest?", "options": ["Hide the MFA setting in deep menus", "Wait for users to ask for MFA", "Turn it on by default for users"], "correctIndex": 2, "consequences": ["Hidden settings go unused.", "Few users ask.", "Google did this for 150 million users."], "explanation": "Defaults beat opt-in. Google's auto-enrollment reached millions at once."}, "proReasoning": "Strong candidates use defaults to change behavior.", "commonMistake": "Relying on users to opt in.", "mentalModel": "Make the safe choice the default."}, "invest": {"call": {"kind": "theCall", "situation": "A consumer platform you hold says MFA is available but optional.", "prompt": "What does Google's result suggest?", "options": ["Defaulting users in could cut takeovers", "Optional MFA works just as well as a default", "MFA has no measurable effect"], "correctIndex": 0, "consequences": ["Google saw 50% fewer compromises.", "Opt-in reaches fewer users.", "Google measured an effect."], "explanation": "Making MFA the default can sharply reduce account takeovers."}, "proReasoning": "Investors ask whether security is on by default.", "commonMistake": "Accepting \"available\" as enough.", "mentalModel": "Ask what is on by default."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds login tools for consumer apps.", "prompt": "Which feature does Google's result support?", "options": ["Password hints shown on screen", "MFA turned on by default at sign-up", "Optional MFA buried in settings"], "correctIndex": 1, "consequences": ["That weakens security.", "Defaults drive adoption.", "Few users find it."], "explanation": "A default-on second step is the feature with evidence behind it."}, "proReasoning": "Founders build features with proven impact.", "commonMistake": "Shipping features without evidence.", "mentalModel": "Build what the data supports."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why Google suddenly asked them to confirm logins on their phone.", "prompt": "What's a good answer?", "options": ["Their phone was hacked", "Google stopped using passwords entirely", "Google turned on a second check by default"], "correctIndex": 2, "consequences": ["It was a default change.", "Passwords were still used.", "Auto-enrollment reached 150 million users."], "explanation": "Google auto-enrolled users because it cut account compromises sharply."}, "proReasoning": "Ask why a default changed.", "commonMistake": "Seeing a security prompt as a problem.", "mentalModel": "Defaults protect at scale."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2cf095e08cc8$ml$]::text[]),
($ml$cc5607af-8522-5093-a335-1f798e97bc92$ml$::uuid, $ml$cybersecurity$ml$, 22, 2, $ml${"id": "cybersecurity-d22-c2", "title": "The missing setting", "lessonTitle": "99.22%", "slot": 2, "type": "connect", "brief": {"headline": "Change Healthcare's attacked systems lacked MFA, and the breach touched 192.7 million people. Microsoft researchers found MFA cuts account compromise risk by 99.22%.", "kicker": "Connect day 1 and day 22: one setting, enormous stakes.", "fullText": "Day 1 told the Change Healthcare story. The former CEO testified that the outdated systems involved lacked multifactor authentication. The breach touched 192.7 million people, and the company paid a $22 million ransom.\n\nDay 22 put a number on that gap. Microsoft researchers studying Azure Active Directory users found MFA reduced the risk of account compromise by 99.22%, and by 98.56% even for accounts whose passwords had already leaked.", "sources": [{"url": "https://www.digitalhealthnews.com/uhg-confirms-final-count-in-change-healthcare-breach-192-7-mn-affected", "label": "Digital Health News, Change Healthcare final count"}, {"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["MFA cut compromise risk by 99.22% overall.", "MFA stopped working once a password leaked.", "Change Healthcare's systems lacked MFA."], "fakeIndex": 1, "explanation": "Even with leaked passwords, MFA cut risk by 98.56%."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did MFA cut risk for accounts with leaked passwords?", "min": 0, "max": 100, "value": 99, "unit": "%", "explanation": "98.56%, versus 99.22% overall."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked for the single highest-value control.", "prompt": "Which answer has evidence behind it?", "options": ["MFA, which cut compromise risk by 99.22%", "A bright new logo on the company login page", "Longer office opening hours"], "correctIndex": 0, "consequences": ["Microsoft researchers measured it.", "No security effect.", "No security effect."], "explanation": "Few controls move risk that far. MFA is the classic example."}, "proReasoning": "Strong candidates cite measured impact.", "commonMistake": "Recommending controls without evidence.", "mentalModel": "Cite measured impact."}, "invest": {"call": {"kind": "theCall", "situation": "A health company you might invest in has some systems without MFA.", "prompt": "How should you weigh that?", "options": ["As proof of strong security", "As a serious, fixable gap", "As a minor detail"], "correctIndex": 1, "consequences": ["It suggests the opposite.", "Change Healthcare shows the cost.", "MFA cuts risk by 99.22%."], "explanation": "Missing MFA is a cheap fix for a huge risk. Its absence says something about priorities."}, "proReasoning": "Investors treat missing basics as a warning sign.", "commonMistake": "Overlooking basic controls.", "mentalModel": "Missing basics are a warning."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup finds systems where MFA is not enforced.", "prompt": "Which two facts make your pitch?", "options": ["MFA has no effect; breaches are rare", "All systems already enforce MFA", "192.7M people hit; MFA cuts risk 99.22%"], "correctIndex": 2, "consequences": ["Both false.", "Change Healthcare shows otherwise.", "The cost of the gap and the power of the fix."], "explanation": "Show the cost of a gap and how much the fix reduces risk."}, "proReasoning": "Founders pair a costly story with a strong statistic.", "commonMistake": "Using a story with no data, or data with no story.", "mentalModel": "Pair story and statistic."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether MFA really matters if they have a strong password.", "prompt": "What's the answer?", "options": ["Yes, MFA cut risk even when passwords leaked", "No, strong passwords are always enough", "No, MFA makes accounts easier to hack"], "correctIndex": 0, "consequences": ["98.56% for leaked passwords.", "Passwords can leak.", "The data shows the opposite."], "explanation": "Passwords leak. MFA still cut risk by 98.56% for accounts whose passwords had leaked."}, "proReasoning": "Ask what happens when the password leaks.", "commonMistake": "Trusting a password alone.", "mentalModel": "MFA covers a leaked password."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:26f6004dd5be$ml$]::text[]),
($ml$5575cf87-e30f-580f-b63d-19b401623e49$ml$::uuid, $ml$cybersecurity$ml$, 22, 3, $ml${"id": "cybersecurity-d22-c3", "title": "Make MFA mandatory?", "lessonTitle": "99.22%", "slot": 3, "type": "decide", "brief": {"headline": "You run security at a mid-size company where MFA is optional and about half of staff use it. Microsoft researchers found MFA cuts compromise risk by 99.22%.", "kicker": "Decide: is a few seconds per login worth it?", "fullText": "You run security at a mid-size company. MFA is optional, and about half of your staff use it. Some managers say it slows people down.\n\nDay 22 gave the evidence. Microsoft researchers found MFA reduced the risk of account compromise by 99.22%, and by 98.56% even when passwords had leaked. MFA adds a few seconds per login. Codes and push prompts can still be phished or approved by mistake; stronger forms resist that.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}]}, "evidence": {"kind": "multipleChoice", "prompt": "By about how much did MFA cut compromise risk overall?", "options": ["50%", "10%", "99.22%"], "correctIndex": 2, "explanation": "99.22% overall, and 98.56% even for accounts with leaked passwords."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did MFA cut compromise risk overall?", "min": 0, "max": 100, "value": 99, "unit": "%", "explanation": "99.22%, per Microsoft researchers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to roll out mandatory MFA.", "prompt": "What do you recommend?", "options": ["Require it only for the IT team", "Require it for all, starting with high-risk accounts", "Keep it optional to avoid any staff complaints"], "correctIndex": 1, "consequences": ["Every account can be a way in.", "Highest risk first, then everyone.", "Half of accounts stay exposed."], "explanation": "Mandatory MFA, phased by risk, gets the benefit without chaos."}, "proReasoning": "Strong candidates plan rollouts, not just mandates.", "commonMistake": "Leaving a known gap open for comfort.", "mentalModel": "Mandate it, phase it by risk."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold says half its staff use MFA.", "prompt": "What does that tell you?", "options": ["It is fully protected from account takeover", "MFA use does not matter", "Half its accounts lack a 99% risk cut"], "correctIndex": 2, "consequences": ["Half are not.", "The research says it does.", "The other half are exposed."], "explanation": "Partial adoption leaves many accounts open to takeover."}, "proReasoning": "Investors ask for coverage, not just availability.", "commonMistake": "Accepting partial coverage as done.", "mentalModel": "Ask for coverage."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run security. A manager says MFA wastes time.", "prompt": "How do you answer?", "options": ["A few seconds removes almost all takeover risk", "Agree and drop MFA for the whole team right away", "Make MFA codes much longer"], "correctIndex": 0, "consequences": ["99.22% for a few seconds.", "That reopens the risk.", "Longer codes add friction, not safety."], "explanation": "Put the cost and benefit side by side: seconds per login versus most takeover risk."}, "proReasoning": "Leaders frame security in trade-offs people accept.", "commonMistake": "Debating feelings instead of numbers.", "mentalModel": "Seconds versus risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks MFA is just an annoyance.", "prompt": "What's a good answer?", "options": ["It makes accounts slower to hack by a minute", "It removes almost all account takeover risk", "It is mostly for show"], "correctIndex": 1, "consequences": ["It blocks most takeovers entirely.", "99.22% risk reduction.", "The data says otherwise."], "explanation": "A few seconds per login buys protection against nearly all account takeovers."}, "proReasoning": "Ask what the few seconds buy.", "commonMistake": "Judging a control by its annoyance.", "mentalModel": "Small cost, big protection."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ce3871798a7a$ml$]::text[]),
($ml$8632047f-a043-558b-946d-e21e9f6bd0e0$ml$::uuid, $ml$cybersecurity$ml$, 23, 1, $ml${"id": "cybersecurity-d23-c1", "title": "Three logins, zero breaches", "lessonTitle": "The memo that retired weak MFA", "slot": 1, "type": "apply", "brief": {"headline": "In July 2022, at least 76 Cloudflare employees got convincing phishing texts within a minute. Three entered their logins, but hardware security keys stopped the attack.", "kicker": "Apply the idea: phishing-resistant MFA held where codes would not have.", "fullText": "Starting July 20, 2022, Cloudflare employees received phishing texts pointing to a fake login page. At least 76 employees got them within one minute, and three entered their credentials.\n\nThe attack still failed. Cloudflare required FIDO2 hardware security keys, which check that the site is genuine, so stolen passwords alone could not be used. Twilio employees hit by the same campaign gave up credentials that attackers then used.", "sources": [{"url": "https://www.theregister.com/2022/08/10/cloudflare_twilio_phishing/", "label": "The Register, Cloudflare and Twilio phishing"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Cloudflare story in order.", "steps": ["Employees get phishing texts within a minute", "Three enter their credentials on a fake page", "Hardware keys refuse the fake site", "The attack fails at Cloudflare"], "explanation": "Phishing worked on people, but the keys would not work on a fake site."}, "numbers": {"kind": "numberSense", "prompt": "At least how many Cloudflare employees received the texts?", "min": 0, "max": 120, "value": 76, "unit": "", "explanation": "At least 76, within one minute."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a tech company. They ask why Cloudflare stopped the attack.", "prompt": "What is the precise answer?", "options": ["Its hardware keys would not work on the fake site", "None of its employees ever clicked the link", "It used one-time text codes for login"], "correctIndex": 0, "consequences": ["Origin binding defeated the phish.", "Three entered credentials.", "Codes can be phished."], "explanation": "Phishing-resistant keys check the site. A fake page cannot use them."}, "proReasoning": "Strong candidates explain why a control worked, not just that it did.", "commonMistake": "Crediting luck instead of the control.", "mentalModel": "Explain why it worked."}, "invest": {"call": {"kind": "theCall", "situation": "Two companies were hit by the same phishing campaign. One used keys, one did not.", "prompt": "What does the outcome show?", "options": ["Both companies were breached", "The type of MFA made the difference", "Phishing never works on employees"], "correctIndex": 1, "consequences": ["Cloudflare was not.", "Cloudflare held; Twilio did not.", "Three entered logins."], "explanation": "Same attack, different results, explained by the type of MFA."}, "proReasoning": "Investors look for natural experiments like this.", "commonMistake": "Treating all MFA as equal.", "mentalModel": "Not all MFA is equal."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells hardware security keys to businesses.", "prompt": "Which story makes your case?", "options": ["A company that never got phished by anyone at all", "A firm that used SMS codes safely", "Cloudflare held while Twilio, hit the same way, did not"], "correctIndex": 2, "consequences": ["No contrast.", "Codes can be phished.", "A side-by-side outcome."], "explanation": "The same campaign with two outcomes shows exactly what keys buy."}, "proReasoning": "Founders use head-to-head evidence.", "commonMistake": "Telling a story with no contrast.", "mentalModel": "Show the side-by-side."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how three employees fell for phishing and nothing happened.", "prompt": "What's the answer?", "options": ["Their keys only work on the real site", "The attackers forgot to log in", "Cloudflare deleted the texts first"], "correctIndex": 0, "consequences": ["FIDO2 checks the site.", "They tried.", "The texts arrived."], "explanation": "A security key will not sign in to a fake site, even if a person is fooled."}, "proReasoning": "Ask what happens after someone clicks.", "commonMistake": "Assuming a click means a breach.", "mentalModel": "The key checks the site."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a12e7040484d$ml$]::text[]),
($ml$a207b062-ad21-59f2-a11c-a0b11593e00a$ml$::uuid, $ml$cybersecurity$ml$, 23, 2, $ml${"id": "cybersecurity-d23-c2", "title": "Good MFA versus strong MFA", "lessonTitle": "The memo that retired weak MFA", "slot": 2, "type": "connect", "brief": {"headline": "Microsoft researchers found MFA cuts compromise risk by 99.22%. Yet a 2022 White House memo told agencies to drop codes and push prompts because they can be phished.", "kicker": "Connect day 22 and day 23: MFA helps, but some forms can be tricked.", "fullText": "Day 22 showed MFA's power. Microsoft researchers found it reduced account compromise risk by 99.22%. The lesson also noted that codes and push prompts can still be phished or approved by mistake.\n\nDay 23 acted on that. OMB memo M-22-09, issued in January 2022, required phishing-resistant MFA for federal staff by the end of fiscal 2024. It told agencies to stop supporting SMS or voice codes, one-time codes and push notifications for routine access.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each method resist phishing?", "buckets": ["Phishing-resistant", "Can be phished"], "items": [{"text": "A hardware security key", "bucket": 0}, {"text": "A passkey tied to the real site", "bucket": 0}, {"text": "A code sent by text message", "bucket": 1}, {"text": "A push prompt you tap to approve", "bucket": 1}], "explanation": "Phishing-resistant methods check the site; codes and prompts can be relayed or approved by mistake."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did MFA cut compromise risk overall?", "min": 0, "max": 100, "value": 99, "unit": "%", "explanation": "99.22%, per Microsoft researchers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why the memo dropped text codes if MFA works.", "prompt": "What is the best answer?", "options": ["Text messages cost too much to send", "Codes can be typed into fake sites", "MFA was found not to work at all"], "correctIndex": 1, "consequences": ["The issue is phishing.", "Phishing-resistant methods check the site.", "MFA cut risk by 99.22%."], "explanation": "MFA helps a lot, but phishable forms leave a gap. The memo closed it."}, "proReasoning": "Strong candidates distinguish good from best.", "commonMistake": "Treating all MFA as the same.", "mentalModel": "Good MFA, then strong MFA."}, "invest": {"call": {"kind": "theCall", "situation": "A security key maker you follow sells to government.", "prompt": "Which policy supports demand?", "options": ["Agencies banned all forms of MFA in 2022", "Agencies prefer text codes", "M-22-09 required phishing-resistant MFA"], "correctIndex": 2, "consequences": ["The opposite happened.", "The memo dropped them.", "Keys meet that bar."], "explanation": "A requirement for phishing-resistant MFA creates demand for methods that meet it."}, "proReasoning": "Investors watch for rules that pick winning technologies.", "commonMistake": "Missing how policy shapes demand.", "mentalModel": "Watch policy pick winners."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers push-prompt MFA to agencies.", "prompt": "What does M-22-09 mean for you?", "options": ["Push alone will not meet the memo's bar", "Push is the preferred federal method", "The memo does not affect MFA"], "correctIndex": 0, "consequences": ["It is not phishing-resistant.", "The memo dropped it for routine access.", "It is all about MFA."], "explanation": "If your method is on the drop list, you need a phishing-resistant option."}, "proReasoning": "Founders track rules that make their product obsolete.", "commonMistake": "Ignoring a rule that excludes you.", "mentalModel": "Know if a rule excludes you."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their bank code is weaker than a security key.", "prompt": "What's the answer?", "options": ["Keys are made of metal", "A code can be typed into a fake site", "Codes expire too slowly to be useful"], "correctIndex": 1, "consequences": ["Material is not the reason.", "Keys check the real site.", "Timing is not the issue."], "explanation": "A code works wherever it is typed. A key only works on the genuine site."}, "proReasoning": "Ask whether the method checks the site.", "commonMistake": "Assuming all second factors are equal.", "mentalModel": "Keys check the site."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c789002c2b4d$ml$]::text[]),
($ml$60cfcf20-3f2d-5531-954d-003849a3c41e$ml$::uuid, $ml$cybersecurity$ml$, 23, 3, $ml${"id": "cybersecurity-d23-c3", "title": "Text codes at an agency", "lessonTitle": "The memo that retired weak MFA", "slot": 3, "type": "decide", "brief": {"headline": "You run identity at a US agency that uses text-message codes for logins. Memo M-22-09 requires phishing-resistant MFA and drops forced password rotation.", "kicker": "Decide: what changes first?", "fullText": "You run identity at a US federal agency. Staff log in with a password, changed every 90 days, plus a code sent by text message.\n\nDay 23 set the rules. M-22-09 required phishing-resistant MFA for agency staff, contractors and partners by the end of fiscal 2024. It told agencies to stop supporting SMS or voice codes, one-time codes and push notifications for routine access, and to drop password rules requiring special characters and regular rotation.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan follows the memo?", "left": {"name": "Keep texts, rotate passwords monthly", "note": "More of the same"}, "right": {"name": "Move to keys, end forced rotation", "note": "Phishing-resistant, simpler passwords"}, "correctIndex": 1, "explanation": "The memo targets phishable methods and outdated password rules alike."}, "numbers": {"kind": "numberSense", "prompt": "How many years did agencies get to remove forced password rules?", "min": 0, "max": 5, "value": 1, "unit": "years", "explanation": "One year, under M-22-09."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a federal identity role, you're asked what M-22-09 changed.", "prompt": "What do you say?", "options": ["More frequent password changes for all staff", "Text codes for every login", "Phishing-resistant MFA, and no forced rotation"], "correctIndex": 2, "consequences": ["It dropped forced rotation.", "It dropped text codes.", "Both are in the memo."], "explanation": "The memo raised the bar on MFA and dropped outdated password rules."}, "proReasoning": "Strong candidates know both halves of the memo.", "commonMistake": "Remembering only one half.", "mentalModel": "Know both halves."}, "invest": {"call": {"kind": "theCall", "situation": "A contractor serving agencies still relies on text-code logins.", "prompt": "What risk should you note?", "options": ["Its method does not meet the memo", "Text codes are the federal standard", "The memo exempts contractors"], "correctIndex": 0, "consequences": ["SMS was dropped for routine access.", "They are not.", "It covers contractors."], "explanation": "A contractor on outdated MFA may not meet agency requirements."}, "proReasoning": "Investors check whether vendors meet buyers' rules.", "commonMistake": "Assuming old methods stay acceptable.", "mentalModel": "Check vendors against the rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run identity at the agency. Staff fear losing text codes.", "prompt": "How do you roll out the change?", "options": ["Keep text codes as the main login method", "Issue keys or passkeys and train staff first", "Turn off all logins for a week"], "correctIndex": 1, "consequences": ["It fails the memo.", "Smooth move to resistant methods.", "Too disruptive."], "explanation": "Give people the new method and training before removing the old one."}, "proReasoning": "Leaders sequence changes so people can follow them.", "commonMistake": "Removing the old method before the new one works.", "mentalModel": "New method first, then retire the old."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the government stopped forcing password changes.", "prompt": "What's a good answer?", "options": ["Passwords were banned entirely", "Hackers asked for the change", "A memo dropped rotation as outdated"], "correctIndex": 2, "consequences": ["They were not banned.", "It was a federal policy choice.", "M-22-09 dropped forced rotation."], "explanation": "Forced rotation and special-character rules were dropped as outdated."}, "proReasoning": "Ask what a rule actually protects against.", "commonMistake": "Assuming more rules mean more security.", "mentalModel": "Some rules were outdated."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5a071d6151e1$ml$]::text[]),
($ml$1a73bb34-c595-5ee8-835c-77e5ced3e1df$ml$::uuid, $ml$cybersecurity$ml$, 24, 1, $ml${"id": "cybersecurity-d24-c1", "title": "Passwordless by default", "lessonTitle": "The end of the password?", "slot": 1, "type": "apply", "brief": {"headline": "From May 2025, new Microsoft accounts no longer need a password. Microsoft said it saw more than 7,000 password attacks per second over the prior year.", "kicker": "Apply the idea: a major platform takes passwords off the default path.", "fullText": "Microsoft announced that from May 2, 2025, new Microsoft accounts would be passwordless by default. Existing users can delete their passwords and sign in with passkeys or other methods.\n\nMicrosoft said more than a million passkeys were being registered every day. It also said it had seen more than 7,000 password attacks per second over the previous year, about double the year before.", "sources": [{"url": "https://www.techradar.com/pro/security/microsoft-is-making-all-new-accounts-passwordless-by-default", "label": "TechRadar, Microsoft makes new accounts passwordless by default"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What changed for new Microsoft accounts in May 2025?", "options": ["They must change passwords monthly", "They no longer need a password", "They need two passwords"], "correctIndex": 1, "explanation": "New accounts became passwordless by default."}, "numbers": {"kind": "numberSense", "prompt": "About how many password attacks per second did Microsoft see, in thousands?", "min": 0, "max": 15, "value": 7, "unit": "K", "explanation": "More than 7,000 per second, about double the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a software company. They ask what Microsoft's move signals.", "prompt": "What do you say?", "options": ["Microsoft stopped supporting logins", "Passwords are leaving the default sign-in path", "Passwords are becoming more important than ever"], "correctIndex": 1, "consequences": ["It changed how they work.", "New accounts skip passwords.", "The opposite."], "explanation": "When a major platform drops passwords by default, the market follows."}, "proReasoning": "Strong candidates read platform moves as signals.", "commonMistake": "Ignoring what large platforms change.", "mentalModel": "Read platform moves as signals."}, "invest": {"call": {"kind": "theCall", "situation": "An identity company you follow builds passkey tools.", "prompt": "What does Microsoft's move suggest?", "options": ["Falling interest in passkeys", "Passwords are making a comeback with users", "Rising demand for passwordless sign-in"], "correctIndex": 2, "consequences": ["Registrations are rising.", "The trend is away from them.", "Defaults shape what users adopt."], "explanation": "Platform defaults speed adoption, which can lift demand for related tools."}, "proReasoning": "Investors watch defaults at major platforms.", "commonMistake": "Missing a shift in defaults.", "mentalModel": "Watch defaults."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps companies move staff to passkeys.", "prompt": "Which fact helps your pitch?", "options": ["7,000+ password attacks per second at Microsoft", "Password attacks have stopped", "Passkeys are not supported anywhere by Microsoft"], "correctIndex": 0, "consequences": ["Shows the pressure on passwords.", "They doubled.", "Microsoft supports them."], "explanation": "Huge attack volume against passwords shows why moving off them matters."}, "proReasoning": "Founders use the scale of the threat.", "commonMistake": "Pitching without scale.", "mentalModel": "Show the scale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend opens a new Microsoft account and is not asked for a password.", "prompt": "What's going on?", "options": ["The new account is not secure at all", "Microsoft made new accounts passwordless", "Microsoft forgot to ask"], "correctIndex": 1, "consequences": ["Passkeys resist phishing.", "A default since May 2025.", "It was deliberate."], "explanation": "Microsoft now signs new accounts in without passwords by default."}, "proReasoning": "Ask why a default changed.", "commonMistake": "Assuming no password means less secure.", "mentalModel": "No password can be safer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5eea3f603b88$ml$]::text[]),
($ml$dab5f379-d27a-5c24-91a6-c5a1317bdb71$ml$::uuid, $ml$cybersecurity$ml$, 24, 2, $ml${"id": "cybersecurity-d24-c2", "title": "From the memo to the mainstream", "lessonTitle": "The end of the password?", "slot": 2, "type": "connect", "brief": {"headline": "In 2022, a White House memo required phishing-resistant MFA for federal staff. By December 2024, Google said 800 million accounts used passkeys, a phishing-resistant login.", "kicker": "Connect day 23 and day 24: what agencies were ordered to adopt, consumers are adopting.", "fullText": "Day 23 showed M-22-09 requiring phishing-resistant MFA for federal staff and dropping codes and push prompts for routine access.\n\nDay 24 showed the same idea reaching consumers. A passkey signs you in with your device, often with a fingerprint or face scan, and only works with the genuine site. By December 2024, Google said 800 million accounts used passkeys, and Amazon users had created 175 million.", "sources": [{"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}, {"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, "evidence": {"kind": "faceOff", "prompt": "Which had more passkey accounts by December 2024?", "left": {"name": "Google", "note": "Accounts using passkeys"}, "right": {"name": "Amazon", "note": "Passkeys created by users"}, "correctIndex": 0, "explanation": "Google said 800 million accounts; Amazon users had created 175 million passkeys."}, "numbers": {"kind": "numberSense", "prompt": "How many Google accounts used passkeys by December 2024, in millions?", "min": 0, "max": 1500, "value": 800, "unit": "M", "explanation": "800 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why passkeys satisfy phishing-resistant requirements.", "prompt": "What is the best answer?", "options": ["They are longer than passwords", "They change every day", "They only work with the genuine site"], "correctIndex": 2, "consequences": ["Length is not the reason.", "They do not need to.", "A fake page cannot collect them."], "explanation": "Passkeys are tied to the real site, like the methods M-22-09 requires."}, "proReasoning": "Strong candidates explain the mechanism.", "commonMistake": "Confusing length with resistance.", "mentalModel": "Tied to the real site."}, "invest": {"call": {"kind": "theCall", "situation": "You follow consumer platforms adding passkeys.", "prompt": "What does the 800 million figure suggest?", "options": ["Passkeys are reaching mass adoption", "Passkeys are a niche experiment", "Users are rejecting passkeys"], "correctIndex": 0, "consequences": ["Hundreds of millions of accounts.", "Far beyond niche.", "Adoption is growing."], "explanation": "Hundreds of millions of users makes passkeys mainstream."}, "proReasoning": "Investors track adoption at scale.", "commonMistake": "Dismissing a fast-growing standard.", "mentalModel": "Track adoption at scale."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells passkey login to mid-size apps.", "prompt": "Which pair of facts frames the market?", "options": ["Passwords are growing faster than passkeys", "Government requires it; 800M already use it", "No one uses it, and agencies ban it"], "correctIndex": 1, "consequences": ["The trend is the reverse.", "Policy and adoption both point the same way.", "Both false."], "explanation": "Policy pressure plus mass adoption makes a strong market story."}, "proReasoning": "Founders show policy and users moving together.", "commonMistake": "Relying on one signal.", "mentalModel": "Policy plus adoption."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether passkeys are just a fad.", "prompt": "What's a good answer?", "options": ["Only a few hundred people anywhere use them", "They were banned in 2024", "800 million Google accounts already use them"], "correctIndex": 2, "consequences": ["Far more.", "They were not.", "That is mass adoption."], "explanation": "Passkeys resist phishing and are already used at huge scale."}, "proReasoning": "Ask how many people use something.", "commonMistake": "Dismissing what you have not tried.", "mentalModel": "Look at adoption."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:650f189c60df$ml$]::text[]),
($ml$0788f980-5a33-5c31-996b-79a955db6c8a$ml$::uuid, $ml$cybersecurity$ml$, 24, 3, $ml${"id": "cybersecurity-d24-c3", "title": "Add passkeys to your app?", "lessonTitle": "The end of the password?", "slot": 3, "type": "decide", "brief": {"headline": "You run product at a consumer app. Microsoft said passkey sign-ins succeed 98% of the time, against 32% for passwords, and are three times faster.", "kicker": "Decide: is it worth the engineering time?", "fullText": "You run product at a consumer app. Failed logins drive many support tickets, and phishing hits some users.\n\nDay 24 gave the numbers. Microsoft said passkey sign-ins were three times faster than passwords and succeeded 98% of the time, against 32% for passwords. Fewer failed logins also means fewer help desk calls. Big platforms support passkeys, but most companies still run on passwords.", "sources": [{"url": "https://www.biometricupdate.com/202412/passkeys-build-momentum-enabling-access-to-15-billion-online-accounts", "label": "Biometric Update, passkeys build momentum"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What makes a passkey resist phishing?", "options": ["It only works with the genuine site", "It is a very long, random password", "It changes every hour"], "correctIndex": 0, "explanation": "A passkey only works with the real site, so a fake page cannot collect it."}, "numbers": {"kind": "numberSense", "prompt": "What share of password sign-ins succeeded, by Microsoft's count, in percent?", "min": 0, "max": 100, "value": 32, "unit": "%", "explanation": "32%, against 98% for passkeys."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to make the case for passkeys.", "prompt": "Which argument is strongest?", "options": ["More successful logins and less phishing", "They look more modern on screen", "They make logins slower but a bit safer"], "correctIndex": 0, "consequences": ["98% vs 32%, and phishing-resistant.", "Looks are not the case.", "They are faster."], "explanation": "Passkeys improve both security and user experience, which rarely go together."}, "proReasoning": "Strong candidates show wins on more than one axis.", "commonMistake": "Arguing security alone.", "mentalModel": "Win on security and experience."}, "invest": {"call": {"kind": "theCall", "situation": "A consumer app you hold adds passkeys.", "prompt": "What business effect might follow?", "options": ["Slower sign-ins for users", "Fewer failed logins and support calls", "More password reset tickets for support"], "correctIndex": 1, "consequences": ["They are three times faster.", "98% success versus 32%.", "Fewer failures, fewer resets."], "explanation": "Better login success can cut support costs and lost sessions."}, "proReasoning": "Investors look for security changes that also cut costs.", "commonMistake": "Seeing security only as cost.", "mentalModel": "Find security that saves money."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run product. Engineering asks for one quarter to add passkeys.", "prompt": "What do you decide?", "options": ["Skip it; passwords work fine", "Wait until every rival already has it", "Fund it; faster, safer logins pay back"], "correctIndex": 2, "consequences": ["32% success says otherwise.", "You lose the head start.", "Success rates and phishing both improve."], "explanation": "Better success rates, faster logins and phishing resistance justify the work."}, "proReasoning": "Founders invest where several metrics improve at once.", "commonMistake": "Waiting for others to move first.", "mentalModel": "Invest where many metrics improve."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why apps keep offering passkeys.", "prompt": "What's a good answer?", "options": ["They are faster and resist phishing", "They collect more personal data", "They are required by every law"], "correctIndex": 0, "consequences": ["Three times faster, phishing-resistant.", "They do not.", "Not a universal law."], "explanation": "Passkeys make logging in faster and harder to phish."}, "proReasoning": "Ask what the user gains.", "commonMistake": "Suspecting every new feature.", "mentalModel": "Faster and safer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b712cf7a86c7$ml$]::text[]),
($ml$1f37e281-732e-5772-b608-66780cca983d$ml$::uuid, $ml$cybersecurity$ml$, 25, 1, $ml${"id": "cybersecurity-d25-c1", "title": "Google removes the castle wall", "lessonTitle": "Never trust, always verify", "slot": 1, "type": "apply", "brief": {"headline": "After the 2009 Operation Aurora attack, Google built BeyondCorp. Its corporate network grants no inherent trust, and every internal app checks the user and device.", "kicker": "Apply the idea: an early zero trust network, years before NIST defined it.", "fullText": "Google created BeyondCorp in response to Operation Aurora, a 2009 attack on Google and other companies. It described the approach in a series of articles from 2014 to 2018.\n\nUnder BeyondCorp, being on Google's corporate network grants no inherent trust. Every internal application is reached through BeyondCorp, which decides access based on the user's and device's credentials, wherever the person is working. NIST later defined the same idea as zero trust.", "sources": [{"url": "https://en.wikipedia.org/wiki/BeyondCorp", "label": "Wikipedia, BeyondCorp"}, {"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each idea belong to the old perimeter or to BeyondCorp?", "buckets": ["Perimeter model", "BeyondCorp"], "items": [{"text": "Inside the office network means trusted", "bucket": 0}, {"text": "A strong wall with everyone inside trusted", "bucket": 0}, {"text": "Every app checks the user and device", "bucket": 1}, {"text": "Access is the same from home or office", "bucket": 1}], "explanation": "The perimeter trusts location; BeyondCorp verifies the user and device each time."}, "numbers": {"kind": "numberSense", "prompt": "How many years after the 2009 attack did Google start publishing BeyondCorp articles?", "min": 0, "max": 15, "value": 5, "unit": "years", "explanation": "About five: the articles ran from 2014 to 2018."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a tech firm. They ask what BeyondCorp changed.", "prompt": "What is the best answer?", "options": ["It built a thicker firewall around the office", "It banned remote work for engineers", "It removed trust based on being on the network"], "correctIndex": 2, "consequences": ["It did the opposite.", "It works from anywhere.", "Access depends on user and device."], "explanation": "BeyondCorp moved trust from location to identity and device."}, "proReasoning": "Strong candidates explain the shift, not just the name.", "commonMistake": "Describing zero trust as a better wall.", "mentalModel": "Trust moves from place to identity."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold says it is copying Google's BeyondCorp model.", "prompt": "What should that mean in practice?", "options": ["Every access checks the user and device", "A bigger VPN for remote staff", "No logins at all inside the office"], "correctIndex": 0, "consequences": ["That is the core idea.", "VPNs extend the perimeter.", "Logins are checked everywhere."], "explanation": "Real zero trust checks every access, not just the front door."}, "proReasoning": "Investors test buzzwords against practice.", "commonMistake": "Accepting the label without the substance.", "mentalModel": "Test the label against practice."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells zero trust access for mid-size firms.", "prompt": "Which history helps your pitch?", "options": ["Zero trust was invented in 2025", "Google adopted it after a major 2009 attack", "Google has never used zero trust internally"], "correctIndex": 1, "consequences": ["It goes back years.", "A respected early adopter.", "BeyondCorp shows it did."], "explanation": "A well-known company adopting it after an attack makes the model credible."}, "proReasoning": "Founders borrow credibility from respected adopters.", "commonMistake": "Presenting a proven idea as untested.", "mentalModel": "Borrow credibility."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google stopped trusting its own office network.", "prompt": "What's a good answer?", "options": ["Its offices had become too crowded to secure well", "It lost its office keys", "After an attack, it decided location proves nothing"], "correctIndex": 2, "consequences": ["It was about security.", "It was about trust.", "Operation Aurora led to BeyondCorp."], "explanation": "Being inside a network does not prove who you are. Google checks each access instead."}, "proReasoning": "Ask what really proves identity.", "commonMistake": "Assuming inside means safe.", "mentalModel": "Location proves nothing."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7dc5fbbd65f2$ml$]::text[]),
($ml$9e681330-c8ab-5498-b629-03aa3d47ab2b$ml$::uuid, $ml$cybersecurity$ml$, 25, 2, $ml${"id": "cybersecurity-d25-c2", "title": "One stolen login, one open network", "lessonTitle": "Never trust, always verify", "slot": 2, "type": "connect", "brief": {"headline": "Credential abuse led breaches in 2025, at 22%. Under the old perimeter model, one stolen login could open the whole network. Zero trust checks every session.", "kicker": "Connect day 19 and day 25: zero trust limits what a stolen login can reach.", "fullText": "Day 19 showed that credential abuse was the top way into breaches in Verizon's 2025 report, at 22%. A stolen login passes authentication.\n\nDay 25 showed why that is worse under the old model. Perimeter security trusts anyone already inside the wall, so one stolen login could open the whole network. NIST defined zero trust in August 2020 as granting no implicit trust based on network location, with every user and device authenticated and authorized before each session.", "sources": [{"url": "https://www.verizon.com/about/news/2025%2Ddata%2Dbreach%2Dinvestigations%2Dreport", "label": "Verizon, 2025 Data Breach Investigations Report"}, {"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}]}, "evidence": {"kind": "faceOff", "prompt": "Which model limits a stolen login more?", "left": {"name": "Perimeter security", "note": "Inside the wall means trusted"}, "right": {"name": "Zero trust", "note": "Checks every session"}, "correctIndex": 1, "explanation": "Zero trust re-checks access each session, so one login does not open everything."}, "numbers": {"kind": "numberSense", "prompt": "What share of breaches started with credential abuse in 2025?", "min": 0, "max": 60, "value": 22, "unit": "%", "explanation": "22%, per Verizon."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how zero trust helps against stolen logins.", "prompt": "What is the best answer?", "options": ["It checks each session, not just the first login", "It makes passwords impossible for anyone to steal", "It removes the need for any login"], "correctIndex": 0, "consequences": ["That limits what one login reaches.", "Logins can still be stolen.", "Every session is checked."], "explanation": "Zero trust assumes a login might be stolen and keeps checking."}, "proReasoning": "Strong candidates connect a model to the threat it addresses.", "commonMistake": "Claiming zero trust stops credential theft.", "mentalModel": "Assume breach, keep checking."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold still relies on a VPN that grants full network access.", "prompt": "What risk should you note?", "options": ["Full access has no downside", "One stolen login could reach everything", "VPNs make logins impossible to steal"], "correctIndex": 1, "consequences": ["It magnifies a stolen login.", "That is the perimeter problem.", "Logins are stolen often."], "explanation": "With credential abuse leading breaches, full network access magnifies each theft."}, "proReasoning": "Investors ask how far one compromised account can go.", "commonMistake": "Assuming the VPN is a security control in itself.", "mentalModel": "Ask how far one login goes."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup replaces VPNs with per-app access.", "prompt": "Which two facts frame your pitch?", "options": ["Logins are never stolen; VPNs are perfect", "Breaches only come from hardware", "Logins lead breaches; perimeters trust insiders"], "correctIndex": 2, "consequences": ["Both false.", "Logins lead.", "Together they show the risk."], "explanation": "The leading cause of breaches meets the model that trusts it most."}, "proReasoning": "Founders connect a trend to a structural weakness.", "commonMistake": "Pitching without the threat data.", "mentalModel": "Connect trend to weakness."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their company wants them to log in to each app separately.", "prompt": "What's a good answer?", "options": ["So one stolen login cannot open everything", "To make everyone's work slower on purpose", "Because the network is broken"], "correctIndex": 0, "consequences": ["That is the zero trust idea.", "It is about limiting damage.", "It is by design."], "explanation": "Checking each access limits what an attacker with one login can do."}, "proReasoning": "Ask what one stolen login could reach.", "commonMistake": "Taking extra checks as a nuisance.", "mentalModel": "Each check limits damage."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e97e9574adec$ml$]::text[]),
($ml$0292d740-ad66-5da1-99fa-ef6d182c8f62$ml$::uuid, $ml$cybersecurity$ml$, 25, 3, $ml${"id": "cybersecurity-d25-c3", "title": "Retire the flat network?", "lessonTitle": "Never trust, always verify", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a 500-person firm. Anyone who connects to the VPN can reach almost every system. NIST says zero trust grants no trust based on network location.", "kicker": "Decide: where do you start the move to zero trust?", "fullText": "You run IT at a 500-person company. Remote staff connect through a VPN, and once inside, they can reach almost every system.\n\nDay 25 set the model. NIST's August 2020 definition says zero trust grants no implicit trust based on network location. It moves defenses from the perimeter to users, assets and resources, and authenticates and authorizes every user and device before each session. A 2022 White House memo set zero trust goals for federal agencies by the end of fiscal 2024.", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}, {"url": "https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf", "label": "OMB memo M-22-09, federal zero trust strategy"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Under zero trust, what earns a device access?", "options": ["Being plugged into the office network", "Having logged in once last month", "Checks on user and device each session"], "correctIndex": 2, "explanation": "Authentication and authorization happen before every session, not once."}, "numbers": {"kind": "numberSense", "prompt": "About how many months after NIST's August 2020 definition did the January 2022 memo arrive?", "min": 0, "max": 40, "value": 17, "unit": "months", "explanation": "About 17 months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to start a zero trust move.", "prompt": "What do you recommend?", "options": ["Rename the VPN and call it done", "Start with the most sensitive apps, checked per session", "Rip out the whole network over one weekend in May"], "correctIndex": 1, "consequences": ["Labels change nothing.", "Phased, risk-first.", "Too disruptive."], "explanation": "Begin where the risk is highest, then expand. Zero trust is a journey, not a switch."}, "proReasoning": "Strong candidates phase big changes by risk.", "commonMistake": "Treating zero trust as a product to install.", "mentalModel": "Phase it by risk."}, "invest": {"call": {"kind": "theCall", "situation": "A company you might back says it \"has zero trust\" because it bought one tool.", "prompt": "What should you ask?", "options": ["How much did the tool cost them per year?", "What color is the main dashboard?", "Does every access check user and device?"], "correctIndex": 2, "consequences": ["Cost does not prove it.", "Irrelevant.", "That is what zero trust means."], "explanation": "Zero trust is a model, not a product. Ask whether every access is verified."}, "proReasoning": "Investors test claims against definitions.", "commonMistake": "Accepting a product name as proof.", "mentalModel": "Test claims against definitions."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run IT. The CEO wants zero trust done this quarter.", "prompt": "What do you propose?", "options": ["A phased plan starting with critical systems", "Turn off the VPN tomorrow", "Promise the CEO it is already complete today"], "correctIndex": 0, "consequences": ["Realistic and risk-first.", "Would break remote work.", "Not true."], "explanation": "A phased plan delivers early wins on critical systems without breaking work."}, "proReasoning": "Leaders set realistic plans for big changes.", "commonMistake": "Overpromising timelines.", "mentalModel": "Phased and honest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what zero trust actually means.", "prompt": "What's the simple answer?", "options": ["Delete the company network", "Check every access, wherever you are", "Trust nobody, so no one can work"], "correctIndex": 1, "consequences": ["The network stays.", "That is NIST's idea.", "People still work, with checks."], "explanation": "Zero trust means being inside the network earns nothing. Each access is verified."}, "proReasoning": "Ask what earns access.", "commonMistake": "Taking the name too literally.", "mentalModel": "Verify every access."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8ed1766ff18e$ml$]::text[]),
($ml$30461d27-a44b-5d36-a18e-20db7b608901$ml$::uuid, $ml$cybersecurity$ml$, 26, 1, $ml${"id": "cybersecurity-d26-c1", "title": "CrowdStrike passes $5 billion ARR", "lessonTitle": "Selling zero trust by subscription", "slot": 1, "type": "apply", "brief": {"headline": "In fiscal 2026, CrowdStrike's revenue rose 22% to $4.81 billion, and subscriptions made up $4.56 billion of it. Annual recurring revenue reached $5.25 billion.", "kicker": "Apply the idea: security sold as a subscription.", "fullText": "CrowdStrike sells endpoint and cloud security mostly by subscription. For the fiscal year ended January 31, 2026, revenue rose 22% to $4.81 billion, from $3.95 billion. Subscription revenue was $4.56 billion, up 21%.\n\nEnding annual recurring revenue, the yearly value of active subscriptions, reached $5.25 billion, up 24%, with a record $1.01 billion of net new ARR. The company guided to about $5.87 billion to $5.93 billion in revenue for fiscal 2027.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1535527/000153552726000007/crwd-20260303xex991.htm", "label": "CrowdStrike fiscal 2026 results, SEC filing"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Subscriptions were most of CrowdStrike's revenue.", "Ending ARR reached $5.25 billion.", "CrowdStrike's revenue fell in fiscal 2026."], "fakeIndex": 2, "explanation": "Revenue rose 22% to $4.81 billion."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did CrowdStrike's ending ARR grow in fiscal 2026?", "min": 0, "max": 60, "value": 24, "unit": "%", "explanation": "24%, to $5.25 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a security software company. They ask why ARR matters.", "prompt": "What is the best answer?", "options": ["It shows the yearly value of active subscriptions", "It counts one-off hardware sales each year", "It measures the number of staff in the company"], "correctIndex": 0, "consequences": ["CrowdStrike reached $5.25 billion.", "ARR is about subscriptions.", "It measures revenue."], "explanation": "ARR tracks recurring subscription value, which makes future revenue easier to see."}, "proReasoning": "Strong candidates know the metrics subscription businesses live by.", "commonMistake": "Confusing ARR with total sales.", "mentalModel": "Know the subscription metrics."}, "invest": {"call": {"kind": "theCall", "situation": "You are comparing a subscription security firm with a hardware seller.", "prompt": "Why might investors pay more for the subscription firm?", "options": ["Subscriptions can never be cancelled", "Recurring revenue is easier to predict", "Hardware never needs replacing at all"], "correctIndex": 1, "consequences": ["They can be, but often renew.", "Subscriptions carry over year to year.", "Hardware does age."], "explanation": "Predictable recurring revenue is valued more than one-off sales."}, "proReasoning": "Investors pay for visibility into future revenue.", "commonMistake": "Treating all revenue as equal.", "mentalModel": "Pay for predictability."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells security software and is choosing a pricing model.", "prompt": "What does CrowdStrike's mix suggest?", "options": ["One-off licenses are the only path", "Security software should be given away forever", "Subscriptions can build large, steady revenue"], "correctIndex": 2, "consequences": ["CrowdStrike shows another path.", "That builds no revenue.", "$4.56 billion of $4.81 billion was subscription."], "explanation": "A subscription model turned into most of CrowdStrike's revenue."}, "proReasoning": "Founders choose models that compound over time.", "commonMistake": "Picking a model that resets every year.", "mentalModel": "Choose revenue that compounds."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how CrowdStrike makes money.", "prompt": "What's the simple answer?", "options": ["Mostly from security subscriptions", "Mostly from selling its own laptops", "Mostly from consulting fees"], "correctIndex": 0, "consequences": ["$4.56 billion was subscription revenue.", "It sells software.", "Subscriptions dominate."], "explanation": "Customers pay every year for CrowdStrike's security services."}, "proReasoning": "Ask how the company gets paid.", "commonMistake": "Assuming security firms sell hardware.", "mentalModel": "Mostly subscriptions."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9527491b0a7b$ml$]::text[]),
($ml$c287e194-df5c-5d30-b411-715ce5e910b6$ml$::uuid, $ml$cybersecurity$ml$, 26, 2, $ml${"id": "cybersecurity-d26-c2", "title": "From model to market", "lessonTitle": "Selling zero trust by subscription", "slot": 2, "type": "connect", "brief": {"headline": "NIST defined zero trust in 2020 as granting no trust based on network location. Zscaler sells that idea from the cloud and earned $2.67 billion in fiscal 2025, up 23%.", "kicker": "Connect day 25 and day 26: a security model became a subscription business.", "fullText": "Day 25 set out the model. NIST defined zero trust in August 2020: no implicit trust based on where a user or device sits on the network, with every access verified.\n\nDay 26 showed it as a business. Zscaler routes users' traffic through its cloud and checks each connection, instead of selling boxes for a server room. Customers pay by subscription. It earned $2.67 billion in fiscal 2025, up 23%, and said annual recurring revenue topped $3 billion.", "sources": [{"url": "https://csrc.nist.gov/Pubs/sp/800/207/Final", "label": "NIST SP 800-207, Zero Trust Architecture"}, {"url": "https://www.constellationr.com/insights/news/zscaler-delivers-strong-q4-fiscal-2026-outlook", "label": "Constellation Research, Zscaler fiscal 2025 results"}]}, "evidence": {"kind": "faceOff", "prompt": "Which fits zero trust for staff who work from anywhere?", "left": {"name": "A firewall box in one office", "note": "Protects the office perimeter"}, "right": {"name": "Checks on each connection in the cloud", "note": "Follows the user wherever they are"}, "correctIndex": 1, "explanation": "When staff work from anywhere, checking each connection fits better than a wall around one office."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did Zscaler's revenue grow in fiscal 2025?", "min": 0, "max": 60, "value": 23, "unit": "%", "explanation": "23%, to $2.67 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why zero trust suits cloud delivery.", "prompt": "What is the best answer?", "options": ["Cloud tools never need to verify users", "Users connect from anywhere, so checks follow them", "Clouds have much thicker walls than office networks"], "correctIndex": 1, "consequences": ["Zero trust verifies every access.", "Remote work broke the perimeter.", "It is about checks, not walls."], "explanation": "With no single office to guard, checking each connection in the cloud fits the model."}, "proReasoning": "Strong candidates connect architecture to how people work.", "commonMistake": "Treating zero trust as a cloud firewall.", "mentalModel": "Checks follow the user."}, "invest": {"call": {"kind": "theCall", "situation": "You follow Zscaler.", "prompt": "What makes its revenue attractive?", "options": ["It depends on one-off box sales", "It comes from a single customer", "It recurs by subscription each year"], "correctIndex": 2, "consequences": ["It sells cloud service.", "Many customers subscribe.", "ARR topped $3 billion."], "explanation": "Subscription revenue carries over, making growth easier to forecast."}, "proReasoning": "Investors favor recurring revenue models.", "commonMistake": "Ignoring how revenue is earned.", "mentalModel": "Recurring revenue is valued."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers zero trust access for small firms.", "prompt": "Which model fits your buyers?", "options": ["A monthly cloud subscription", "A large hardware box per office", "A one-time license with no updates"], "correctIndex": 0, "consequences": ["Small firms prefer pay-as-you-go.", "Hard for small, remote teams.", "Security needs ongoing updates."], "explanation": "Cloud subscriptions fit small, remote teams and build recurring revenue."}, "proReasoning": "Founders match delivery to how buyers work.", "commonMistake": "Selling hardware to remote teams.", "mentalModel": "Match delivery to buyers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a security idea becomes a business.", "prompt": "What's a good example?", "options": ["Zero trust is sold only as hardware", "Zscaler sells zero trust by subscription", "NIST sells its standards as an app"], "correctIndex": 1, "consequences": ["It is sold from the cloud.", "$2.67 billion in fiscal 2025.", "NIST publishes standards."], "explanation": "A model like zero trust can be delivered as a cloud service and sold by subscription."}, "proReasoning": "Ask who turns the idea into a product.", "commonMistake": "Thinking standards and products are the same.", "mentalModel": "Ideas become services."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:58c7eac03e66$ml$]::text[]),
($ml$1835438c-c414-5e7b-8156-85288f91c519$ml$::uuid, $ml$cybersecurity$ml$, 26, 3, $ml${"id": "cybersecurity-d26-c3", "title": "Renew the boxes or subscribe?", "lessonTitle": "Selling zero trust by subscription", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a firm where most staff now work remotely. Your office firewalls are due for renewal. Zscaler earned $2.67 billion in fiscal 2025 selling cloud zero trust.", "kicker": "Decide: protect the office, or protect the user?", "fullText": "You run IT at a mid-size company. Most staff now work from home or on the road, and your office firewall hardware is due for a costly replacement.\n\nDay 26 showed the alternative. Zscaler routes users' traffic through its cloud and checks each connection. Customers rent security as a service instead of buying hardware. It earned $2.67 billion in fiscal 2025, up 23%, with annual recurring revenue above $3 billion.", "sources": [{"url": "https://www.constellationr.com/insights/news/zscaler-delivers-strong-q4-fiscal-2026-outlook", "label": "Constellation Research, Zscaler fiscal 2025 results"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which revenue is easier for investors to predict?", "options": ["Occasional consulting work", "Recurring subscriptions", "One-off hardware sales"], "correctIndex": 1, "explanation": "Subscriptions carry over from year to year, so they are easier to forecast."}, "numbers": {"kind": "numberSense", "prompt": "About how much ARR did Zscaler report, in billions of dollars?", "min": 0, "max": 8, "value": 3, "unit": "B", "explanation": "Above $3 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to secure a mostly remote workforce.", "prompt": "What do you recommend?", "options": ["Buy a bigger, faster firewall for the main office", "Ask staff to come back to the office", "Check each user connection, wherever they are"], "correctIndex": 2, "consequences": ["Most traffic no longer passes through it.", "Not a security plan.", "That fits where people work."], "explanation": "When work leaves the office, the checks should follow the user."}, "proReasoning": "Strong candidates design for how people actually work.", "commonMistake": "Protecting a building nobody is in.", "mentalModel": "Protect the user, not the building."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold just spent heavily on new office firewalls, though most staff are remote.", "prompt": "What concern does that raise?", "options": ["Spending may not match where work happens", "It guarantees full security for remote staff", "Hardware always beats cloud services"], "correctIndex": 0, "consequences": ["Remote users bypass the office.", "It protects the office only.", "Not for remote teams."], "explanation": "Security spending should follow where users and data actually are."}, "proReasoning": "Investors check whether spending matches the business.", "commonMistake": "Assuming any spending is good spending.", "mentalModel": "Spending should match reality."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run IT. Finance prefers buying hardware once over paying monthly.", "prompt": "How do you frame the choice?", "options": ["Neither option matters for security", "Subscriptions cover remote staff and stay updated", "Office hardware covers remote staff just as well"], "correctIndex": 1, "consequences": ["The choice shapes coverage.", "It fits how the company works.", "Remote traffic skips office boxes."], "explanation": "Frame it on coverage: a subscription protects users wherever they work."}, "proReasoning": "Leaders frame costs in terms of what they cover.", "commonMistake": "Comparing price without comparing coverage.", "mentalModel": "Compare coverage, not just cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why companies pay monthly for security instead of buying it once.", "prompt": "What's a good answer?", "options": ["Monthly bills are always cheaper than buying hardware", "Buying once is illegal", "Cloud security follows remote staff and keeps updating"], "correctIndex": 2, "consequences": ["Not always.", "It is allowed.", "That is Zscaler's model."], "explanation": "A subscription service protects users anywhere and is kept current by the vendor."}, "proReasoning": "Ask what the subscription delivers.", "commonMistake": "Judging only by the payment schedule.", "mentalModel": "Pay for ongoing protection."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c6334155ffd0$ml$]::text[]),
($ml$16517716-9466-50cd-a43e-313d5aeb0093$ml$::uuid, $ml$cybersecurity$ml$, 27, 1, $ml${"id": "cybersecurity-d27-c1", "title": "24 hours to check the firewalls", "lessonTitle": "Unplug it within 48 hours", "slot": 1, "type": "apply", "brief": {"headline": "In September 2025, CISA gave US agencies 24 hours to find and fix Cisco firewalls targeted by attackers. Older devices hitting end of life on September 30 had to go.", "kicker": "Apply the idea: edge devices get the shortest deadlines.", "fullText": "In late September 2025, CISA issued Emergency Directive 25-03 over attacks on Cisco ASA and Firepower Threat Defense devices, tracked as CVE-2025-20333 and CVE-2025-20362. The activity was linked to the ArcaneDoor campaign.\n\nAgencies got 24 hours to identify affected devices, collect and check logs, and apply fixes. ASA devices reaching end of life on September 30 were to be removed. Like Ivanti in 2024, the target was equipment sitting at the network's edge.", "sources": [{"url": "https://www.theregister.com/2025/09/26/cisco_firewall_flaws/", "label": "The Register, CISA emergency directive on Cisco firewalls"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the agency response in order.", "steps": ["CISA issues an emergency directive on Cisco devices", "Agencies identify affected firewalls", "They collect and check logs for signs of attack", "They apply fixes or remove end-of-life devices"], "explanation": "Find the devices, look for compromise, then fix or retire them."}, "numbers": {"kind": "numberSense", "prompt": "How many hours did agencies get under ED 25-03?", "min": 0, "max": 72, "value": 24, "unit": "hours", "explanation": "24 hours to identify devices, check logs and apply fixes."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a network security role. They ask why firewalls are targets.", "prompt": "What is the best answer?", "options": ["They are always switched off at night", "They face the internet and guard the way in", "They hold no data, so they are ignored"], "correctIndex": 1, "consequences": ["They run constantly.", "Edge devices face the whole internet.", "They are prime targets."], "explanation": "Edge devices face the internet and control access, so attackers go after them."}, "proReasoning": "Strong candidates explain why attackers pick a target.", "commonMistake": "Assuming security devices are secure by default.", "mentalModel": "Edges are targets."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold still runs firewalls past their end of life.", "prompt": "What does ED 25-03 suggest?", "options": ["Old firewalls are safer than new ones", "End of life has no security meaning", "Unsupported edge gear is a serious risk"], "correctIndex": 2, "consequences": ["They stop getting fixes.", "No fixes means more risk.", "Agencies had to remove them."], "explanation": "Devices that no longer get fixes sit at the edge as open targets."}, "proReasoning": "Investors ask about aging equipment at the network edge.", "commonMistake": "Ignoring end-of-life gear.", "mentalModel": "Retire unsupported edge gear."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks the support status of network devices.", "prompt": "Which directive detail helps your pitch?", "options": ["End-of-life ASA devices had to be removed", "All the affected devices were declared safe", "Only printers were affected"], "correctIndex": 0, "consequences": ["Knowing what is out of support matters.", "The opposite.", "Firewalls were affected."], "explanation": "If regulators order out-of-support devices removed, knowing which you have is valuable."}, "proReasoning": "Founders point to the rule that creates the need.", "commonMistake": "Ignoring the rule behind demand.", "mentalModel": "Point to the rule."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the government gave agencies only a day.", "prompt": "What's the answer?", "options": ["It was a routine yearly check", "Attackers were actively targeting the devices", "The fix took only about one minute to install"], "correctIndex": 1, "consequences": ["It was an emergency directive.", "Linked to the ArcaneDoor campaign.", "Logs had to be checked too."], "explanation": "Active attacks on edge devices made speed critical."}, "proReasoning": "Ask why a deadline is short.", "commonMistake": "Assuming short deadlines are arbitrary.", "mentalModel": "Active attacks shorten deadlines."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:79333a1e7222$ml$]::text[]),
($ml$4683d32a-1ca9-59d7-baac-fa86bb0d1c50$ml$::uuid, $ml$cybersecurity$ml$, 27, 2, $ml${"id": "cybersecurity-d27-c2", "title": "Two weeks, then 48 hours", "lessonTitle": "Unplug it within 48 hours", "slot": 2, "type": "connect", "brief": {"headline": "CISA usually gives agencies two weeks to fix known exploited flaws. In February 2024, it gave them 48 hours to disconnect Ivanti VPNs, because attackers were getting around the fixes.", "kicker": "Connect day 9 and day 27: the clock shortens when fixes fail.", "fullText": "Day 9 set the usual clock. Under BOD 22-01, US civilian agencies get two weeks to fix most flaws on CISA's Known Exploited Vulnerabilities catalog.\n\nDay 27 showed an exception. In February 2024, CISA ordered agencies to disconnect Ivanti VPN products within 48 hours. Attackers, including suspected Chinese state-backed hackers, were exploiting zero-day flaws and had bypassed published fixes. One research firm counted at least 2,200 compromised devices.", "sources": [{"url": "https://cisa.gov/binding-operational-directive-22-01", "label": "CISA, Binding Operational Directive 22-01"}, {"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, "evidence": {"kind": "faceOff", "prompt": "Which deadline was shorter?", "left": {"name": "BOD 22-01 standard", "note": "For most listed flaws"}, "right": {"name": "Ivanti disconnect order", "note": "February 2024"}, "correctIndex": 1, "explanation": "48 hours, against two weeks for most listed flaws."}, "numbers": {"kind": "numberSense", "prompt": "At least how many Ivanti devices did one firm count as compromised, in thousands?", "min": 0, "max": 5000, "value": 2200, "unit": "K", "explanation": "At least 2,200."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked why CISA ordered unplugging instead of patching.", "prompt": "What is the best answer?", "options": ["Ivanti had no patches planned for the flaws at all", "Unplugging is the routine response", "Attackers were bypassing the published fixes"], "correctIndex": 2, "consequences": ["Fixes existed but were bypassed.", "It was unusually drastic.", "Mitigations were being bypassed."], "explanation": "When the fix itself is beaten, removing the device is the safer step."}, "proReasoning": "Strong candidates explain why the usual step was not enough.", "commonMistake": "Assuming a patch always works.", "mentalModel": "When fixes fail, disconnect."}, "invest": {"call": {"kind": "theCall", "situation": "A VPN vendor you follow had products ordered disconnected by CISA.", "prompt": "What risk does that pose to the vendor?", "options": ["Lost trust and customers moving away", "More sales from all the publicity", "No effect on its customers"], "correctIndex": 0, "consequences": ["Agencies had to unplug its gear.", "The order was a warning sign.", "Agencies had to act."], "explanation": "An emergency order to unplug a product can hurt a vendor's reputation and sales."}, "proReasoning": "Investors watch for government actions against a product.", "commonMistake": "Ignoring regulatory signals about a vendor.", "mentalModel": "Watch regulatory signals."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps agencies rebuild edge devices cleanly.", "prompt": "Which Ivanti detail supports your pitch?", "options": ["Only one device was affected", "Reconnecting required a fresh, patched install", "A quick restart of each device fixed everything"], "correctIndex": 1, "consequences": ["At least 2,200 were.", "Clean rebuilds are your service.", "Factory resets were advised."], "explanation": "If reconnecting means a clean rebuild, helping do it fast is valuable."}, "proReasoning": "Founders build for the hard step in a response.", "commonMistake": "Assuming a simple restart is enough.", "mentalModel": "Build for the hard step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why agencies had to unplug their VPNs.", "prompt": "What's the answer?", "options": ["The VPNs were too slow for staff", "Agencies stopped using the internet", "Attackers were getting around the fixes"], "correctIndex": 2, "consequences": ["It was about security.", "They still use it.", "Mitigations were bypassed."], "explanation": "When attackers beat the fix, unplugging is the safest move."}, "proReasoning": "Ask whether the fix worked.", "commonMistake": "Assuming a patch always closes a hole.", "mentalModel": "Unplug when the fix fails."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:df244f98ed33$ml$]::text[]),
($ml$85f23310-99e3-5445-a48e-b6a46b38dd73$ml$::uuid, $ml$cybersecurity$ml$, 27, 3, $ml${"id": "cybersecurity-d27-c3", "title": "Your VPN, the same flaw", "lessonTitle": "Unplug it within 48 hours", "slot": 3, "type": "decide", "brief": {"headline": "Your company runs the same VPN as the agencies. A patch is out, but attackers are reportedly getting around it. CISA gave agencies 48 hours to disconnect.", "kicker": "Decide: patch and move on, or rebuild and hunt?", "fullText": "You run security at a company that uses the same Ivanti VPN. A patch is out, but reports say attackers are bypassing it.\n\nDay 27 showed the federal response. CISA ordered agencies to disconnect within 48 hours. Reconnecting effectively required a fresh, patched install, and Ivanti advised factory resets so attackers could not hang on. Agencies also had to hunt for threats on connected systems and audit privileged accounts.", "sources": [{"url": "https://techcrunch.com/2024/02/01/cisa-federal-agencies-disconnect-ivanti-vpn", "label": "TechCrunch, CISA orders agencies to disconnect Ivanti VPNs"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did agencies have to do besides disconnecting?", "options": ["Hunt for threats and audit admin accounts", "Change their office Wi-Fi names", "Buy a second VPN from the same vendor"], "correctIndex": 0, "explanation": "They had to hunt for threats on connected systems and audit privileged accounts."}, "numbers": {"kind": "numberSense", "prompt": "Within how many hours were agencies told to disconnect?", "min": 0, "max": 120, "value": 48, "unit": "hours", "explanation": "48 hours, far shorter than the usual weeks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to respond when attackers bypass a patch.", "prompt": "What do you recommend?", "options": ["Rebuild clean and hunt for intruders", "Install the patch and assume it works", "Wait for a second patch before acting"], "correctIndex": 0, "consequences": ["That follows CISA's steps.", "It is being bypassed.", "Attackers do not wait."], "explanation": "When attackers beat the fix, assume compromise: rebuild, then hunt."}, "proReasoning": "Strong candidates assume compromise when fixes fail.", "commonMistake": "Trusting a patch known to be bypassed.", "mentalModel": "Rebuild, then hunt."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold patched its VPN and declared the issue closed.", "prompt": "What should you ask?", "options": ["Did it announce the patch on social media?", "Did it check for intruders already inside?", "What brand of VPN does it prefer?"], "correctIndex": 1, "consequences": ["Irrelevant.", "Attackers may already be in.", "Brand does not matter now."], "explanation": "Patching closes a door, but intruders may already be inside."}, "proReasoning": "Investors ask whether a response looked for existing compromise.", "commonMistake": "Accepting \"patched\" as \"safe\".", "mentalModel": "Patched is not clean."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run security. The business wants the VPN back up in an hour.", "prompt": "What do you decide?", "options": ["Reconnect the old setup right away to save time", "Leave it off forever", "Rebuild clean first, even if it takes longer"], "correctIndex": 2, "consequences": ["Attackers could still be inside.", "Staff need remote access.", "A clean install keeps attackers out."], "explanation": "A clean rebuild costs hours but avoids reconnecting a compromised device."}, "proReasoning": "Leaders trade a short delay for a real fix.", "commonMistake": "Rushing back to a compromised state.", "mentalModel": "A short delay beats reinfection."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their company's VPN was down for a day.", "prompt": "What's a good answer?", "options": ["It was rebuilt clean after a known attack", "The VPN was being moved to a new building", "Staff used too much bandwidth"], "correctIndex": 0, "consequences": ["That follows Ivanti's advice.", "Not a real reason.", "Not the cause."], "explanation": "When attackers beat a patch, a clean rebuild keeps them from hanging on."}, "proReasoning": "Ask what the downtime fixed.", "commonMistake": "Seeing downtime as only a nuisance.", "mentalModel": "Downtime can be protection."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bd11bcdcb3ae$ml$]::text[]),
($ml$074492ab-d1c5-5998-8222-7bdafca0fe07$ml$::uuid, $ml$cybersecurity$ml$, 28, 1, $ml${"id": "cybersecurity-d28-c1", "title": "29 minutes to spread", "lessonTitle": "48 minutes to spread", "slot": 1, "type": "apply", "brief": {"headline": "CrowdStrike's 2026 report said criminal intruders took 29 minutes on average in 2025 to move beyond their first foothold. The fastest took 27 seconds.", "kicker": "Apply the idea: breakout time keeps shrinking.", "fullText": "Breakout time is how long an intruder takes to move from the first compromised machine to others. CrowdStrike's 2025 report put the average at 48 minutes.\n\nIts 2026 Global Threat Report said the average eCrime breakout time in 2025 fell to 29 minutes, with the fastest at 27 seconds. It also said adversaries using AI increased their operations by 89% year over year.", "sources": [{"url": "https://crowdstrike.com/en-us/press-releases/2026-crowdstrike-global-threat-report", "label": "CrowdStrike 2026 Global Threat Report release"}, {"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What was the average breakout time in 2025, per CrowdStrike's 2026 report?", "options": ["29 minutes", "48 minutes", "29 hours"], "correctIndex": 0, "explanation": "29 minutes, down from 48 in the prior report."}, "numbers": {"kind": "numberSense", "prompt": "What was the average eCrime breakout time in 2025, in minutes?", "min": 0, "max": 75, "value": 29, "unit": "minutes", "explanation": "29 minutes; the fastest was 27 seconds."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a security operations role. They ask what 29 minutes means.", "prompt": "What is the best answer?", "options": ["Teams can safely wait a full day before responding", "Attackers usually stay on one machine", "Responders have under half an hour to contain"], "correctIndex": 2, "consequences": ["The intrusion spreads by then.", "They move fast.", "The average is 29 minutes."], "explanation": "A short breakout time means alerts must be acted on within minutes."}, "proReasoning": "Strong candidates translate a statistic into a response target.", "commonMistake": "Treating alerts as next-day work.", "mentalModel": "Turn the number into a target."}, "invest": {"call": {"kind": "theCall", "situation": "A managed detection firm you follow promises response within 15 minutes.", "prompt": "Why might that matter?", "options": ["It beats the 29-minute average breakout", "It is slower than any attacker could ever be", "Response time has no value"], "correctIndex": 0, "consequences": ["Containment before spread.", "It is faster than the average.", "Speed limits damage."], "explanation": "Responding before the average breakout can stop spread."}, "proReasoning": "Investors compare service promises to threat benchmarks.", "commonMistake": "Ignoring the benchmark behind a promise.", "mentalModel": "Compare promises to benchmarks."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup automates containment of compromised machines.", "prompt": "Which number makes your pitch?", "options": ["Attackers never move between machines", "Fastest breakout took just 27 seconds", "Average breakout took a full week"], "correctIndex": 1, "consequences": ["Breakout is moving.", "Humans cannot match that speed.", "It was 29 minutes."], "explanation": "If the fastest attackers move in seconds, automation is the only match."}, "proReasoning": "Founders use the extreme case to justify automation.", "commonMistake": "Pitching speed without the numbers.", "mentalModel": "Use the extreme case."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how fast hackers spread once they get in.", "prompt": "What's a good answer?", "options": ["Usually about a month after they get in", "They never spread", "About 29 minutes on average in 2025"], "correctIndex": 2, "consequences": ["Much faster.", "They do.", "Per CrowdStrike's 2026 report."], "explanation": "On average under half an hour, and sometimes in seconds."}, "proReasoning": "Ask how long defenders have.", "commonMistake": "Assuming defenders have days.", "mentalModel": "Under half an hour."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:753793e96cef$ml$]::text[]),
($ml$82337a18-66d0-53a7-a256-e57174d7b19f$ml$::uuid, $ml$cybersecurity$ml$, 28, 2, $ml${"id": "cybersecurity-d28-c2", "title": "Fast in, fast across", "lessonTitle": "48 minutes to spread", "slot": 2, "type": "connect", "brief": {"headline": "Attackers exploited new flaws within five days on average in 2023. Once inside, CrowdStrike found they took 48 minutes on average to spread beyond the first machine.", "kicker": "Connect day 10 and day 28: speed on both ends of an attack.", "fullText": "Day 10 timed how fast attackers get in. Mandiant found the average time-to-exploit fell to five days in 2023, down from 63 days in 2018 and 2019.\n\nDay 28 timed what comes next. CrowdStrike's 2025 report put average breakout time, moving from the first compromised machine to others, at 48 minutes, with the fastest at 51 seconds. It also found 79% of attacks to gain initial access were malware-free, often using stolen logins.", "sources": [{"url": "https://cloud.google.com/blog/topics/threat-intelligence/time-to-exploit-trends-2023?hl=en", "label": "Google Cloud (Mandiant), time-to-exploit trends 2023"}, {"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each number measure getting in or spreading?", "buckets": ["Getting in", "Spreading"], "items": [{"text": "Five days from disclosure to first exploit", "bucket": 0}, {"text": "63 days to exploit, back in 2018 and 2019", "bucket": 0}, {"text": "48 minutes from first machine to others", "bucket": 1}, {"text": "Fastest breakout in 51 seconds", "bucket": 1}], "explanation": "Time-to-exploit measures getting in; breakout time measures spreading."}, "numbers": {"kind": "numberSense", "prompt": "What share of initial access attacks were malware-free?", "min": 0, "max": 100, "value": 79, "unit": "%", "explanation": "79%, per CrowdStrike's 2025 report."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked where defenders should focus given these numbers.", "prompt": "What is the best answer?", "options": ["Patch fast, and contain within minutes", "Patch monthly and review logs weekly", "Focus only on stopping malware"], "correctIndex": 0, "consequences": ["Both clocks are short.", "Too slow on both ends.", "79% were malware-free."], "explanation": "Attackers are fast getting in and fast spreading. Defenses must be fast at both."}, "proReasoning": "Strong candidates connect two metrics into one plan.", "commonMistake": "Optimizing one stage and ignoring the other.", "mentalModel": "Be fast at both ends."}, "invest": {"call": {"kind": "theCall", "situation": "A security vendor you follow mainly sells malware detection.", "prompt": "What does the 79% figure suggest?", "options": ["Detection tools are no longer needed", "Most initial access used no malware", "Malware is behind every attack"], "correctIndex": 1, "consequences": ["They need to cover more.", "Stolen logins often replace malware.", "79% were malware-free."], "explanation": "If most attacks use no malware, malware-only tools miss a lot."}, "proReasoning": "Investors check whether a product fits how attacks happen now.", "commonMistake": "Backing a product built for yesterday's attacks.", "mentalModel": "Fit the product to current attacks."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup spots stolen logins being used inside networks.", "prompt": "Which fact supports your pitch?", "options": ["All attacks rely on malware", "Attackers never use real logins to get in", "79% of initial access was malware-free"], "correctIndex": 2, "consequences": ["Most do not.", "They often do.", "Stolen logins look normal."], "explanation": "If attackers use real logins, spotting misuse is the gap to fill."}, "proReasoning": "Founders build where existing tools are blind.", "commonMistake": "Building for threats tools already catch.", "mentalModel": "Build where tools are blind."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether hackers mainly use viruses.", "prompt": "What's the more accurate picture?", "options": ["Most now get in without malware", "Every attack uses a virus", "Hackers stopped attacking in 2025"], "correctIndex": 0, "consequences": ["79% were malware-free.", "Most did not.", "Attacks continue."], "explanation": "Many attackers log in with stolen credentials instead of using malware."}, "proReasoning": "Ask how the attacker got in.", "commonMistake": "Picturing every attack as a virus.", "mentalModel": "Often no malware at all."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:06981b441980$ml$]::text[]),
($ml$8e854576-2dde-5cfd-b79e-88752b38ab2b$ml$::uuid, $ml$cybersecurity$ml$, 28, 3, $ml${"id": "cybersecurity-d28-c3", "title": "An alert at 2 a.m.", "lessonTitle": "48 minutes to spread", "slot": 3, "type": "decide", "brief": {"headline": "You run a small security team. An alert fires at 2 a.m. on one laptop. CrowdStrike found intruders take 48 minutes on average to spread, and the fastest took 51 seconds.", "kicker": "Decide: wait for morning, or contain now?", "fullText": "You run a small security team. At 2 a.m., an alert flags suspicious activity on one employee laptop. No one is on shift.\n\nDay 28 set the clock. CrowdStrike's 2025 report put average breakout time at 48 minutes, with the fastest at 51 seconds. 79% of initial access attacks were malware-free. Splitting a network into zones, each checked separately, makes moving from one machine to the next harder.", "sources": [{"url": "https://www.businesswire.com/news/home/20250227012922/en", "label": "CrowdStrike 2025 Global Threat Report release"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan fits a 48-minute breakout time?", "left": {"name": "Isolate the laptop automatically now", "note": "Contain first, investigate after"}, "right": {"name": "Review the alert at 9 a.m.", "note": "Investigate with the full team"}, "correctIndex": 0, "explanation": "By morning, an intruder could have spread many times over."}, "numbers": {"kind": "numberSense", "prompt": "What was the average breakout time in CrowdStrike's 2025 report, in minutes?", "min": 0, "max": 120, "value": 48, "unit": "minutes", "explanation": "48 minutes; the fastest was 51 seconds."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how a small team can handle night alerts.", "prompt": "What do you recommend?", "options": ["Hire twenty more analysts at once", "Automate isolation for high-risk alerts", "Ignore night alerts until morning"], "correctIndex": 1, "consequences": ["Not realistic for a small team.", "Contains spread without staff on shift.", "Breakout takes minutes."], "explanation": "Automation lets a small team act within the breakout window."}, "proReasoning": "Strong candidates design for constraints.", "commonMistake": "Assuming alerts can wait.", "mentalModel": "Automate the first move."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold has no overnight security coverage.", "prompt": "What risk does that create?", "options": ["Attackers only work business hours", "Nothing happens at night", "Intrusions can spread before anyone acts"], "correctIndex": 2, "consequences": ["They work any time.", "Attacks happen at night.", "Breakout averages 48 minutes."], "explanation": "Without coverage or automation, the breakout window passes unwatched."}, "proReasoning": "Investors ask how fast a company can respond at any hour.", "commonMistake": "Assuming attacks wait for office hours.", "mentalModel": "Ask about off-hours response."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the team. Isolating a laptop may interrupt a real employee.", "prompt": "What do you decide?", "options": ["Isolate first; a brief interruption is cheaper", "Never isolate without full proof", "Shut down the whole company network for a week"], "correctIndex": 0, "consequences": ["Spread costs far more.", "Proof may come too late.", "Too drastic for one alert."], "explanation": "Isolating one laptop briefly is a small cost against an intrusion spreading."}, "proReasoning": "Leaders accept small costs to avoid large ones.", "commonMistake": "Waiting for certainty while the clock runs.", "mentalModel": "Contain first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their laptop was cut off from the network at night.", "prompt": "What's a good answer?", "options": ["Laptops sleep at midnight", "An alert triggered automatic isolation", "The network ran out of space for laptops"], "correctIndex": 1, "consequences": ["Not why it happened.", "To stop possible spread.", "Not a real reason."], "explanation": "Intruders spread fast, so suspicious machines are isolated first and checked after."}, "proReasoning": "Ask what the isolation protected.", "commonMistake": "Seeing isolation as a punishment.", "mentalModel": "Isolate, then investigate."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d3f58a4f0f7c$ml$]::text[]),
($ml$17162536-e4c1-5448-883e-68e7a78a7cbc$ml$::uuid, $ml$cybersecurity$ml$, 29, 1, $ml${"id": "cybersecurity-d29-c1", "title": "A test account without MFA", "lessonTitle": "One old password, one shut pipeline", "slot": 1, "type": "apply", "brief": {"headline": "In late 2023, Russian state hackers got into Microsoft by guessing the password of an old test account that had no MFA. They then reached some senior leaders' email.", "kicker": "Apply the idea: a forgotten account opened the door, just like at Colonial.", "fullText": "In late November 2023, the Russian state group Midnight Blizzard used a password spray attack, trying common passwords across many accounts, to get into a legacy, non-production test tenant account at Microsoft. The account did not have multifactor authentication.\n\nFrom there, the attackers reached a very small percentage of Microsoft's corporate email accounts, including senior leadership and staff in cybersecurity and legal. Microsoft detected the attack on January 12, 2024. Like Colonial's unused VPN account, an old login that no one watched became the way in.", "sources": [{"url": "https://www.theregister.com/2024/01/27/microsoft_cozy_bear_mfa", "label": "The Register, Microsoft breached through a test account without MFA"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Microsoft story in order.", "steps": ["An old test account is left without MFA", "Attackers guess its password in a spray attack", "They reach some corporate email accounts", "Microsoft detects the attack on January 12, 2024"], "explanation": "A forgotten account, a guessed password, wider access, then detection."}, "numbers": {"kind": "numberSense", "prompt": "How many weeks passed from late November 2023 to detection on January 12, 2024?", "min": 0, "max": 20, "value": 7, "unit": "weeks", "explanation": "About seven weeks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an identity role. They ask what the Microsoft case teaches.", "prompt": "Which lesson do you lead with?", "options": ["Find and lock down old and test accounts", "Test accounts never need any protection", "Only production accounts are attacked"], "correctIndex": 0, "consequences": ["A legacy test account was the way in.", "This one lacked MFA.", "Attackers used a test account."], "explanation": "Forgotten accounts escape normal controls. Inventory and MFA close them."}, "proReasoning": "Strong candidates look for the accounts nobody owns.", "commonMistake": "Securing only the accounts people use daily.", "mentalModel": "Find the forgotten accounts."}, "invest": {"call": {"kind": "theCall", "situation": "A software company you hold has many old test environments.", "prompt": "What risk does Microsoft's case highlight?", "options": ["Only customers face this kind of risk", "Old test accounts can lead to real systems", "Test systems are always fully isolated"], "correctIndex": 1, "consequences": ["Microsoft itself was hit.", "It led to corporate email.", "This one was not."], "explanation": "An old test account at one of the largest software firms led to senior email."}, "proReasoning": "Investors ask how companies clean up old systems.", "commonMistake": "Assuming test systems are harmless.", "mentalModel": "Ask about old systems."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup finds dormant accounts without MFA.", "prompt": "Which two cases make your pitch?", "options": ["Two companies that never had any breach at all", "A broken printer and a slow website", "Colonial's VPN account and Microsoft's test account"], "correctIndex": 2, "consequences": ["No story to tell.", "Unrelated.", "Both were forgotten logins without MFA."], "explanation": "Two famous breaches through forgotten logins show exactly what you find."}, "proReasoning": "Founders use matching cases to show a pattern.", "commonMistake": "Using one case when a pattern exists.", "mentalModel": "Show the pattern."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how hackers got into Microsoft's email.", "prompt": "What's the simple answer?", "options": ["They guessed the password of an old test account", "They broke into a Microsoft data center at night", "An employee emailed them a password"], "correctIndex": 0, "consequences": ["Password spray on an account without MFA.", "It was a login.", "They guessed it."], "explanation": "They found an old account with no second factor and guessed its password."}, "proReasoning": "Ask which account was used.", "commonMistake": "Assuming a high-tech break-in.", "mentalModel": "An old login, no MFA."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2e5f9247e615$ml$]::text[]),
($ml$7d5945da-defe-5e01-9030-f0c437aeae26$ml$::uuid, $ml$cybersecurity$ml$, 29, 2, $ml${"id": "cybersecurity-d29-c2", "title": "One setting, one pipeline", "lessonTitle": "One old password, one shut pipeline", "slot": 2, "type": "connect", "brief": {"headline": "Microsoft researchers found MFA cuts account compromise risk by 99.22%. In 2021, hackers entered Colonial Pipeline through a VPN account that had no MFA.", "kicker": "Connect day 22 and day 29: the setting that was missing.", "fullText": "Day 22 measured MFA's effect. Microsoft researchers found it reduced account compromise risk by 99.22%, and by 98.56% even when passwords had leaked.\n\nDay 29 showed what its absence cost. Hackers entered Colonial Pipeline on April 29, 2021, through a VPN account that was no longer used but still active, with no multifactor authentication. A ransom note appeared on May 7. The pipeline, which carries about 2.5 million barrels of fuel a day, stayed shut until May 12, and Colonial paid a $4.4 million ransom.", "sources": [{"url": "https://arxiv.org/abs/2305.00945", "label": "Microsoft researchers, how effective is MFA"}, {"url": "https://www.aljazeera.com/economy/2021/6/4/hackers-breached-colonial-pipeline-with-one-compromised-password", "label": "Al Jazeera, Colonial Pipeline breached with one password"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which control would most likely have stopped the Colonial login?", "options": ["Multifactor authentication", "A faster internet connection", "A longer ransom negotiation"], "correctIndex": 0, "explanation": "The attackers had a valid password. A second factor would have blocked them."}, "numbers": {"kind": "numberSense", "prompt": "How many days after the May 7 ransom note did the pipeline restart?", "min": 0, "max": 20, "value": 5, "unit": "days", "explanation": "Five days: it restarted on May 12. Colonial paid a $4.4 million ransom."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to explain Colonial in one line.", "prompt": "Which line is most accurate?", "options": ["An insider opened the valves on purpose", "One unused VPN account with no MFA shut a pipeline", "A zero-day flaw in the pipeline control system"], "correctIndex": 1, "consequences": ["It was a login.", "That is what happened.", "It was a password."], "explanation": "A forgotten account and a missing second factor led to a national shutdown."}, "proReasoning": "Strong candidates compress a case to its cause.", "commonMistake": "Overcomplicating a simple failure.", "mentalModel": "Name the cause in one line."}, "invest": {"call": {"kind": "theCall", "situation": "An energy company you hold uses VPNs with password-only logins.", "prompt": "What does Colonial suggest?", "options": ["A strong and modern remote setup", "No risk for energy firms", "A serious, cheap-to-fix exposure"], "correctIndex": 2, "consequences": ["It is the Colonial setup.", "Colonial was an energy firm.", "MFA cuts risk by 99.22%."], "explanation": "Password-only remote access is the exact setup that failed at Colonial."}, "proReasoning": "Investors look for known failure patterns.", "commonMistake": "Missing a well-known risk.", "mentalModel": "Spot known failure patterns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup enforces MFA on every remote access login.", "prompt": "Which pair of facts makes your pitch?", "options": ["MFA cuts risk 99.22%; Colonial lacked it", "MFA does nothing; pipelines are safe", "Colonial used MFA and still fell"], "correctIndex": 0, "consequences": ["Cost of the gap, power of the fix.", "Both false.", "It did not."], "explanation": "Pair a famous failure with the measured fix."}, "proReasoning": "Founders pair a story with a statistic.", "commonMistake": "Using only one of the two.", "mentalModel": "Story plus statistic."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a fuel pipeline got shut down by hackers.", "prompt": "What's the answer?", "options": ["They cut the power to the pumps along the line", "They logged in with a password and no second check", "They dug up the pipe"], "correctIndex": 1, "consequences": ["It was a login.", "An unused VPN account without MFA.", "It was a cyberattack."], "explanation": "A forgotten account with only a password let attackers in."}, "proReasoning": "Ask how the attackers got in.", "commonMistake": "Picturing a physical attack.", "mentalModel": "A password was enough."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e83a95177025$ml$]::text[]),
($ml$bb6e6fff-bf36-5d30-b5a8-f17f77c2716d$ml$::uuid, $ml$cybersecurity$ml$, 29, 3, $ml${"id": "cybersecurity-d29-c3", "title": "Audit the old accounts?", "lessonTitle": "One old password, one shut pipeline", "slot": 3, "type": "decide", "brief": {"headline": "You run IT at a utility. An audit finds dozens of VPN accounts for people who left years ago, some without MFA. Colonial was breached through one such account.", "kicker": "Decide: what do you do first?", "fullText": "You run IT at a regional utility. An audit finds dozens of VPN accounts belonging to people who left years ago. Some have no MFA.\n\nDay 29 showed the risk. Colonial Pipeline was breached through a VPN account that was no longer used but still active, with no MFA. Its password later turned up in a batch of leaked passwords. Colonial shut the whole pipeline within about an hour of finding the ransom note and restarted on May 12.", "sources": [{"url": "https://www.aljazeera.com/economy/2021/6/4/hackers-breached-colonial-pipeline-with-one-compromised-password", "label": "Al Jazeera, Colonial Pipeline breached with one password"}]}, "evidence": {"kind": "faceOff", "prompt": "Which first step closes the Colonial gap fastest?", "left": {"name": "Disable unused accounts now", "note": "Then require MFA for the rest"}, "right": {"name": "Schedule a review next quarter", "note": "Keep accounts active until then"}, "correctIndex": 0, "explanation": "An unused account with only a password is exactly how Colonial was breached."}, "numbers": {"kind": "numberSense", "prompt": "About how many million barrels of fuel a day does Colonial's pipeline carry?", "min": 0, "max": 6000000, "value": 2500000, "unit": "M", "explanation": "About 2.5 million barrels a day."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to handle accounts of former staff.", "prompt": "What do you recommend?", "options": ["Keep them all active in case people come back", "Leave them as long as nobody complains", "Disable them on departure and audit regularly"], "correctIndex": 2, "consequences": ["An unused account was the way in.", "Unused accounts are risky.", "Closes the Colonial gap."], "explanation": "Accounts should end when the job ends, with audits to catch misses."}, "proReasoning": "Strong candidates pair a process with a check.", "commonMistake": "Relying on memory to remove access.", "mentalModel": "Remove on departure, audit often."}, "invest": {"call": {"kind": "theCall", "situation": "A utility you hold says it reviews VPN accounts once a year.", "prompt": "What concern does Colonial raise?", "options": ["Unused accounts can sit open for months", "Yearly reviews catch every single risk", "Utilities are never targeted"], "correctIndex": 0, "consequences": ["Colonial's account was unused but active.", "Gaps last between reviews.", "Colonial was hit."], "explanation": "Rare reviews leave forgotten accounts open for long stretches."}, "proReasoning": "Investors ask how quickly access is removed.", "commonMistake": "Assuming an annual check is enough.", "mentalModel": "Ask how fast access is removed."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run IT. Managers say some old accounts may still be needed.", "prompt": "What do you decide?", "options": ["Delete every account in the company", "Disable them now and re-enable on request", "Leave all of them active just in case"], "correctIndex": 1, "consequences": ["Too disruptive.", "Safe by default, easy to restore.", "That is the Colonial gap."], "explanation": "Disabling is reversible. Leaving them open could be catastrophic."}, "proReasoning": "Leaders choose the reversible safe option.", "commonMistake": "Keeping risk open for convenience.", "mentalModel": "Disable now, restore if needed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their old company account was shut off the day they left.", "prompt": "What's a good answer?", "options": ["The company was angry at them", "Accounts expire on their own", "Unused accounts are a common way in"], "correctIndex": 2, "consequences": ["It is standard security.", "Someone switched it off.", "Colonial was breached that way."], "explanation": "An account nobody uses can still be used by an attacker."}, "proReasoning": "Ask who else could use an old login.", "commonMistake": "Taking it personally.", "mentalModel": "Unused accounts are risky."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2f097251ee83$ml$]::text[]),
($ml$da61e039-74f7-5d83-a584-c852c485700e$ml$::uuid, $ml$cybersecurity$ml$, 30, 1, $ml${"id": "cybersecurity-d30-c1", "title": "iMessage gets quantum protection", "lessonTitle": "Encryption for the quantum age", "slot": 1, "type": "apply", "brief": {"headline": "In February 2024, Apple announced PQ3, a new iMessage protocol built to resist future quantum computers. It rolled out starting with iOS 17.4.", "kicker": "Apply the idea: harvest now, decrypt later pushed Apple to act early.", "fullText": "On February 21, 2024, Apple announced PQ3, a new security protocol for iMessage. Apple said it was the first messaging protocol to reach what it calls Level 3 security, protecting both the initial key exchange and the ongoing exchange of messages.\n\nApple pointed to the risk of attackers collecting encrypted data today to decrypt it once quantum computers can. PQ3 began rolling out with iOS 17.4 in March 2024, months before NIST published its first post-quantum standards in August.", "sources": [{"url": "https://www.macrumors.com/2024/02/21/apple-announces-imessage-security-upgrade/", "label": "MacRumors, Apple announces iMessage PQ3"}, {"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["PQ3 was announced in February 2024.", "PQ3 protects ongoing messages, not just setup.", "Apple waited for quantum computers to exist first."], "fakeIndex": 2, "explanation": "Apple acted early because data collected now could be decrypted later."}, "numbers": {"kind": "numberSense", "prompt": "Which iOS version began the PQ3 rollout?", "min": 0, "max": 30, "value": 17, "unit": "", "explanation": "iOS 17.4, in March 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a messaging company. They ask why Apple moved early.", "prompt": "What is the best answer?", "options": ["Apple wanted messages to send faster", "Messages stolen now could be read later", "Quantum computers already break iMessage"], "correctIndex": 1, "consequences": ["It is about security.", "Harvest now, decrypt later.", "Not yet."], "explanation": "Data harvested today stays exposed until it is protected against future decryption."}, "proReasoning": "Strong candidates explain why the timing is now, not later.", "commonMistake": "Waiting for the threat to arrive.", "mentalModel": "Protect long-lived data now."}, "invest": {"call": {"kind": "theCall", "situation": "You follow companies that handle sensitive messages.", "prompt": "What does Apple's move suggest?", "options": ["Quantum risk is decades away and ignored", "Encryption is being abandoned", "Post-quantum upgrades are starting now"], "correctIndex": 2, "consequences": ["Apple acted early.", "It is being upgraded.", "PQ3 rolled out in 2024."], "explanation": "When a major platform upgrades early, peers face pressure to follow."}, "proReasoning": "Investors watch leaders set new security baselines.", "commonMistake": "Dismissing a shift because the threat is future.", "mentalModel": "Watch leaders set baselines."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps apps add post-quantum encryption.", "prompt": "Which fact supports your timing?", "options": ["Apple shipped quantum protection in 2024", "No major company has started on it yet", "Quantum risk was ruled out"], "correctIndex": 0, "consequences": ["A leader already moved.", "Apple has.", "It was not."], "explanation": "A major platform shipping it shows the work has begun."}, "proReasoning": "Founders time launches to leaders' moves.", "commonMistake": "Launching into a market no one has started.", "mentalModel": "Follow the leader's move."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why iMessage needs protection from computers that barely exist.", "prompt": "What's the answer?", "options": ["It makes emojis load faster", "Messages stored today could be decrypted later", "Quantum computers already read everyone's texts"], "correctIndex": 1, "consequences": ["Unrelated.", "Harvest now, decrypt later.", "Not yet."], "explanation": "Attackers can save encrypted messages now and decrypt them when the machines arrive."}, "proReasoning": "Ask how long the data must stay secret.", "commonMistake": "Thinking only today's threats matter.", "mentalModel": "Today's data, tomorrow's risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8b67bb360c29$ml$]::text[]),
($ml$5ce1af9a-cff6-57c1-aab4-a2e508a0e564$ml$::uuid, $ml$cybersecurity$ml$, 30, 2, $ml${"id": "cybersecurity-d30-c2", "title": "You cannot replace what you cannot find", "lessonTitle": "Encryption for the quantum age", "slot": 2, "type": "connect", "brief": {"headline": "Log4j showed that firms could not patch what they did not know they ran. NIST's 2024 post-quantum standards raise the same problem: first find every place you use old encryption.", "kicker": "Connect day 11 and day 30: inventory comes before migration.", "fullText": "Day 11 showed the inventory problem. The Cyber Safety Review Board warned that unpatched Log4j copies would remain for a decade or longer, and companies often did not know the library was inside their products.\n\nDay 30 set up the same challenge. In August 2024, NIST published FIPS 203, 204 and 205, its first post-quantum standards. Companies must first find every place they use vulnerable encryption before they can replace it.", "sources": [{"url": "https://therecord.media/first-cyber-safety-review-board-report-finds-log4j-has-become-an-endemic-vulnerability/", "label": "The Record, Log4j is an endemic vulnerability"}, {"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a post-quantum migration in order.", "steps": ["Find every place old encryption is used", "Rank them by how long the data must stay secret", "Replace them with NIST's new standards", "Check that nothing old was missed"], "explanation": "Inventory, prioritize, replace, verify."}, "numbers": {"kind": "numberSense", "prompt": "How many post-quantum standards did NIST publish in August 2024?", "min": 0, "max": 10, "value": 3, "unit": "", "explanation": "Three: FIPS 203, 204 and 205."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how to start a post-quantum migration.", "prompt": "What do you recommend?", "options": ["Replace a few systems you remember", "Wait for quantum computers to arrive", "Inventory where encryption is used first"], "correctIndex": 2, "consequences": ["Hidden uses get missed.", "Harvested data is already exposed.", "Log4j shows why."], "explanation": "As with Log4j, you cannot fix what you cannot find."}, "proReasoning": "Strong candidates reuse lessons across problems.", "commonMistake": "Starting replacements without a map.", "mentalModel": "Map before you migrate."}, "invest": {"call": {"kind": "theCall", "situation": "A company you hold says it has started post-quantum work.", "prompt": "What should you ask first?", "options": ["Does it know where it uses encryption?", "What color are its encryption keys?", "Has it bought a quantum computer yet?"], "correctIndex": 0, "consequences": ["Inventory comes first.", "Irrelevant.", "Not needed for migration."], "explanation": "Without an inventory, a migration plan has blind spots."}, "proReasoning": "Investors ask for the foundation before the roadmap.", "commonMistake": "Accepting a plan without a map.", "mentalModel": "Ask for the inventory."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup scans software to find vulnerable encryption.", "prompt": "Which lesson supports your pitch?", "options": ["Encryption is always easy to locate", "Log4j lingered because firms could not find it", "Log4j was fixed everywhere within a single week"], "correctIndex": 1, "consequences": ["It hides in many products.", "The same problem returns with crypto.", "It was not."], "explanation": "If firms struggled to find one library, finding every use of encryption is harder."}, "proReasoning": "Founders point to a past problem with the same shape.", "commonMistake": "Ignoring history that supports the pitch.", "mentalModel": "Point to the same-shaped problem."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why switching to quantum-safe encryption is hard.", "prompt": "What's the answer?", "options": ["The new standards do not exist yet, so firms wait", "Quantum-safe encryption is illegal", "Companies must first find every place it is used"], "correctIndex": 2, "consequences": ["NIST published three in 2024.", "It is not.", "Like Log4j, uses are hidden everywhere."], "explanation": "Encryption is buried in many systems. Finding it all is the first big job."}, "proReasoning": "Ask whether people know where it is.", "commonMistake": "Assuming the switch is a single update.", "mentalModel": "Finding it is the hard part."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:17bc97c8c664$ml$]::text[]),
($ml$505b7623-c093-5ea6-aced-187a14c5be6b$ml$::uuid, $ml$cybersecurity$ml$, 30, 3, $ml${"id": "cybersecurity-d30-c3", "title": "Secrets that must last 20 years", "lessonTitle": "Encryption for the quantum age", "slot": 3, "type": "decide", "brief": {"headline": "You run security at a bank that keeps customer records secret for 20 years. NIST published its first post-quantum standards in August 2024.", "kicker": "Decide: start now, or wait for quantum computers?", "fullText": "You run security at a bank. Some customer records must stay confidential for 20 years.\n\nDay 30 set the stakes. In August 2024, NIST published its first three post-quantum encryption standards: FIPS 203 for general encryption, and FIPS 204 and 205 for digital signatures. The worry is harvest now, decrypt later: attackers collect encrypted data today and read it once quantum computers can break it. Secrets that must last a decade are already at risk.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2024/08/nist-releases-three-post-quantum-cryptography-standards", "label": "Holland & Knight, NIST post-quantum standards"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects 20-year secrets?", "left": {"name": "Inventory and plan migration now", "note": "Start with long-lived data"}, "right": {"name": "Wait until quantum computers exist", "note": "Act when the threat is real"}, "correctIndex": 0, "explanation": "Long-lived secrets are exposed now, so the inventory and migration plan should start now."}, "numbers": {"kind": "numberSense", "prompt": "How many years must the bank's records stay secret?", "min": 0, "max": 50, "value": 20, "unit": "years", "explanation": "20 years, so data harvested today must stay safe that long."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked when a bank should start post-quantum work.", "prompt": "What do you say?", "options": ["Now, starting with the longest-lived secrets", "Only after quantum computers are built", "Never, since encryption cannot be broken"], "correctIndex": 0, "consequences": ["Harvested data is at risk today.", "Data stolen before then is exposed.", "Quantum computers could break it."], "explanation": "Data that must stay secret for years is at risk from attacks happening today."}, "proReasoning": "Strong candidates tie urgency to how long data must last.", "commonMistake": "Treating a future threat as a future problem.", "mentalModel": "Urgency follows data lifetime."}, "invest": {"call": {"kind": "theCall", "situation": "A bank you hold says quantum risk is not a priority.", "prompt": "What concern does that raise?", "options": ["Quantum risk only affects online video games", "Long-lived data may already be harvested", "Banks hold no sensitive data"], "correctIndex": 1, "consequences": ["It affects encrypted data.", "Harvest now, decrypt later.", "They hold a lot."], "explanation": "A bank with long-lived secrets faces quantum risk on data stolen today."}, "proReasoning": "Investors ask how long a company's secrets must last.", "commonMistake": "Dismissing a slow-building risk.", "mentalModel": "Ask how long secrets last."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run security at the bank. The board asks for a first step.", "prompt": "What do you propose?", "options": ["Buy a quantum computer for testing", "Delete all customer records older than one year now", "Map where vulnerable encryption protects long-lived data"], "correctIndex": 2, "consequences": ["Not needed to migrate.", "Banks must keep records.", "Inventory first, longest-lived first."], "explanation": "Start with an inventory focused on the data that must stay secret longest."}, "proReasoning": "Leaders start big changes with a map and a priority.", "commonMistake": "Jumping to tools before knowing the scope.", "mentalModel": "Map, then prioritize."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why banks worry about computers that do not exist yet.", "prompt": "What's the answer?", "options": ["Stolen data could be decrypted when they do", "Banks already own quantum computers", "Quantum computers can rob banks directly"], "correctIndex": 0, "consequences": ["Harvest now, decrypt later.", "Not the reason.", "They break encryption."], "explanation": "Data stolen today can be saved and decrypted later, so long-lived secrets need protection now."}, "proReasoning": "Ask how long the secret must last.", "commonMistake": "Thinking future threats can wait.", "mentalModel": "Long secrets need early protection."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7559a1c455aa$ml$]::text[])
